// 文法詳解 N5(老師口吻,scripts/gen-grammar-detail.mjs 產生、build-grammar-detail.mjs 合併;改風格改 scripts/grammar-detail-samples.js 再重產)。
// key=文法 id;value=HTML(渲染時 .gd-jp 日文過 furiganaHTML→furigana+即點即查;中文解說不動)。
window.GRAMMAR_DETAIL = window.GRAMMAR_DETAIL || {};
Object.assign(window.GRAMMAR_DETAIL, {
  "n5-51": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文不管誰給誰都說「給」，日文會看<b>東西往哪個方向跑</b>：從我這邊<b>送出去</b>用<span class='gd-jp'>あげます</span>，從別人那邊<b>送進來</b>用<span class='gd-jp'>くれます</span>，站在我這邊說「我<b>收到</b>」用<span class='gd-jp'>もらいます</span>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>あげます</span>我（或我這邊的人）給別人，東西往外送。別人給別人也用它。</div><div class='gd-ex-line'>・<span class='gd-jp'>友達に誕生日プレゼントをあげました。</span>（我送了朋友生日禮物）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは山田さんに花をあげました。</span>（田中先生送花給山田小姐）</div><div class='gd-sec'><span class='gd-tag'>くれます</span>別人給<b>我</b>，或給<b>我的家人</b>，東西往我這邊送進來。「給我」通常不用講出來，日本人一聽就知道。</div><div class='gd-ex-line'>・<span class='gd-jp'>母が時計をくれました。</span>（媽媽給了我一支手錶）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が妹にお菓子をくれました。</span>（朋友給了我妹妹零食）</div><div class='gd-sec'><span class='gd-tag'>もらいます</span>站在收的人這邊說「我拿到、我收到」。</div><div class='gd-ex-line'>・<span class='gd-jp'>先生から手紙をもらいました。</span>（我收到老師寫的信）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>三句都是「誰、給誰、什麼東西」，差別在<b>誰當主角</b>：<br><b>あげます</b>：給的人<span class='gd-jp'>は</span>　收的人<span class='gd-jp'>に</span>　東西<span class='gd-jp'>を</span>　<span class='gd-jp'>あげます</span><br><b>くれます</b>：給的人<span class='gd-jp'>が</span>　（我<span class='gd-jp'>に</span>）　東西<span class='gd-jp'>を</span>　<span class='gd-jp'>くれます</span><br><b>もらいます</b>：我<span class='gd-jp'>は</span>　給的人<span class='gd-jp'>に</span>／<span class='gd-jp'>から</span>　東西<span class='gd-jp'>を</span>　<span class='gd-jp'>もらいます</span><br>過去式一樣把ます換成ました：<span class='gd-pair'><span class='gd-jp'>くれます</span> → <span class='gd-jp'>くれました</span></span></div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一件事：<b>朋友給我一本書</b>。<br>・<span class='gd-jp'>友達が本をくれました。</span>（朋友給了我一本書）主角是朋友，書往我這邊來。<br>・<span class='gd-jp'>友達に本をもらいました。</span>（我從朋友那裡拿到一本書）主角是我，我收下。<br>這兩句意思一樣，都可以講。<br>・<span class='gd-jp'>友達が私に本をあげました。</span>　這句<b>錯</b>，あげます不能用在「給我」。<br><br>反過來，<b>我給朋友一本書</b>，只能說：<br>・<span class='gd-jp'>友達に本をあげました。</span>（我給了朋友一本書）</div><div class='gd-warn'>判斷小訣竅：先問自己「東西是不是往我這邊來？」是的話，用くれます或もらいます；往外送就用あげます。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・照中文直覺，「媽媽給我」很多人會寫成<span class='gd-jp'>母があげました</span>，錯。給我、給我家人一律用<b>くれます</b>。<br>・くれます的主角不會是「我」：<span class='gd-jp'>私が友達にくれました</span>是錯的，要說<span class='gd-jp'>友達にあげました</span>。<br>・もらいます前面的<span class='gd-jp'>に</span>是「<b>從</b>」，不是「給」：<span class='gd-jp'>友達にもらいました</span>是「從朋友那裡拿到」，不是「拿給朋友」。怕搞混就改用<span class='gd-jp'>から</span>，意思一樣。<br>・家人算「我這邊的人」，所以朋友給你妹妹東西，也用くれます。<br>・東西給老師、主管，直接說あげます聽起來有點高高在上，之後會學更客氣的說法。<br>・有時會聽到<span class='gd-jp'>花に水をやります</span>（幫花澆水），やります用在給動物、植物；對人講やります比較粗魯，初學先用あげます就好。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>到了N4，這三個動詞會接在て形後面，變成「幫別人做事」：<span class='gd-jp'>友達が駅まで送ってくれました。</span>（朋友送我到車站）方向的判斷跟這裡完全一樣，現在分清楚，後面就很輕鬆。</div>",
  "n5-38": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「だけ」和「しか」都是「只」。<b>だけ</b>像中文的「只～」，單純說範圍；<b>しか〜ません</b>比較像「才～」「只有～而已」，話裡帶著<b>「好少、不夠」</b>的感覺。最大的特色是：<b>しか後面一定要接否定</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>だけ</b>：直接放在名詞、數量後面。<br><span class='gd-pair'><span class='gd-jp'>水</span> → <span class='gd-jp'>水だけ</span></span><span class='gd-pair'><span class='gd-jp'>一つ</span> → <span class='gd-jp'>一つだけ</span></span><br>動詞也可以接，用辭書形（字典上那個樣子）：<span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るだけ</span></span>（只是看）</div><div class='gd-sec'><b>しか</b>：放在名詞、數量後面，句尾動詞一定換成否定。<br><span class='gd-pair'><span class='gd-jp'>水を飲みます</span> → <span class='gd-jp'>水しか飲みません</span></span>（只喝水）</div><div class='gd-sec'><b>原本的「を」「が」要拿掉</b>：<span class='gd-jp'>水を</span>變成<span class='gd-jp'>水だけ</span>、<span class='gd-jp'>水しか</span>。（だけ後面留著を也可以，不過平常多半直接拿掉。）<br>「に」「で」「へ」這些<b>要留著</b>，放在しか前面：</div><div class='gd-ex-line'>・<span class='gd-jp'>友達にしか言いませんでした。</span>（我只跟朋友說了）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>だけ：單純說範圍</span>沒有特別覺得多或少，就是交代「只有這個」。</div><div class='gd-ex-line'>・<span class='gd-jp'>サラダだけ注文します。</span>（我只點沙拉）</div><div class='gd-ex-line'>・<span class='gd-jp'>見ているだけです。</span>（我只是看看）</div><div class='gd-sec'>第二句在日本逛街很好用，店員過來招呼時這樣回就可以了。</div><div class='gd-sec'><span class='gd-tag'>しか：覺得少、不夠</span>心裡覺得「太少了」「比想像的少」。</div><div class='gd-ex-line'>・<span class='gd-jp'>10分しか残っていません。</span>（只剩 10 分鐘了）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は3時間しか寝ませんでした。</span>（我昨天才睡三個小時）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>しか後面一定是否定</b>：說<span class='gd-jp'>千円しかありません</span>，不能說「千円しかあります」。<br>・<b>跟中文直覺相反</b>：看到「ません」別以為是「沒有」。<span class='gd-jp'>千円しかありません</span>是「只有一千塊」，不是「沒有一千塊」；<span class='gd-jp'>肉しか食べません</span>是「只吃肉」，不是「不吃肉」。可以想成「除了一千塊以外，都沒有」。<br>・<b>しか前面不能留を、が</b>：不能說「水をしか」，要說<span class='gd-jp'>水しか</span>。<br>・<b>だけ不代表「夠」</b>：だけ只是中性的「只」，本身不帶「夠用」的意思。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一件事，用だけ是在報告，用しか是在感嘆「好少」。</div><div class='gd-ex-line'>・<span class='gd-jp'>パーティーに一人だけ来ました。</span>（派對只來了一個人：單純報告）</div><div class='gd-ex-line'>・<span class='gd-jp'>パーティーに一人しか来ませんでした。</span>（派對才來一個人：人好少）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が少しだけ分かります。</span>（我懂一點點日文：客氣地說自己會一點）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が少ししか分かりません。</span>（我只懂一點點日文：強調懂得不多，請對方別講太難）</div><div class='gd-warn'>判斷小訣竅：中文想說「才～」「只有～而已」，心裡覺得少，就用「しか＋ません」；只是交代範圍，就用「だけ」。記得しか一定配ません。</div>",
  "n5-62": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文說「門開了」和「我把門打開」，都用同一個「開」字。日文<b>要換成另一個動詞</b>：說「門開了」用<span class='gd-jp'>開く</span>，說「有人把門打開」用<span class='gd-jp'>開ける</span>。前面那種叫<b>自動詞</b>，後面那種叫<b>他動詞</b>，前面的助詞也要跟著換。</div><div class='gd-h'>兩個名字先搞懂</div><div class='gd-sec'><span class='gd-tag'>自動詞＋が</span>只說「東西變成怎樣」，不管是誰弄的，前面用<b>が</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアが開きます。</span>（門要開了：電車裡常聽到的廣播）</div><div class='gd-sec'><span class='gd-tag'>他動詞＋を</span>說「有人去弄某個東西」，被弄的那個東西後面接<b>を</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアを開けます。</span>（我把門打開）</div><div class='gd-sec'>簡單的判斷方法：中文能不能加「<b>把</b>」？「把門打開」說得通，就用他動詞＋を；「門開了」不用加「把」，就用自動詞＋が。</div><div class='gd-h'>最常見的幾對</div><div class='gd-ex-line'>・<span class='gd-jp'>電気がつきました。</span>（燈亮了）</div><div class='gd-ex-line'>・<span class='gd-jp'>電気をつけてください。</span>（請開燈）</div><div class='gd-ex-line'>・<span class='gd-jp'>授業が始まります。</span>（要上課了）</div><div class='gd-ex-line'>・<span class='gd-jp'>授業を始めます。</span>（我們開始上課）</div><div class='gd-ex-line'>・<span class='gd-jp'>財布が落ちました。</span>（錢包掉了）</div><div class='gd-ex-line'>・<span class='gd-jp'>財布を落としました。</span>（我把錢包弄掉了）</div><div class='gd-sec'>還有這幾對，左邊是自動詞，右邊是他動詞：<br><span class='gd-jp'>閉まる</span>／<span class='gd-jp'>閉める</span>（關）<br><span class='gd-jp'>消える</span>／<span class='gd-jp'>消す</span>（熄、關掉）<br><span class='gd-jp'>入る</span>／<span class='gd-jp'>入れる</span>（進去／放進去）<br><span class='gd-jp'>出る</span>／<span class='gd-jp'>出す</span>（出去／拿出來）<br>哪個是自動詞、哪個是他動詞，沒有一條規則能全部套用，最好<b>一對一對配著例句背</b>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・助詞和動詞要配對好：<span class='gd-jp'>電気を消します</span>、<span class='gd-jp'>電気が消えます</span>都對，「電気を消えます」就錯了。<br>・拜託別人做事要用他動詞：<span class='gd-jp'>窓を閉めてください</span>，不能說「窓が閉まってください」。<br>・這裡的<span class='gd-jp'>開く</span>念<b>あく</b>。同一個漢字還有「ひらく」的念法，用法不一樣，先不要混在一起。<br>・<span class='gd-jp'>入る</span>、<span class='gd-jp'>出る</span>常常和地點一起用：<span class='gd-jp'>部屋に入ります</span>（進房間）用に；<span class='gd-jp'>家を出ます</span>（出門）的を是「離開的地方」，不是「被弄的東西」，所以出る還是自動詞。<br>・自動詞不只講「自然發生」的事：<span class='gd-jp'>行く</span>、<span class='gd-jp'>寝る</span>也是自動詞，是人自己在做的動作。重點在<b>有沒有一個被弄的東西</b>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>兩種動詞加上「〜ています」，意思差很多：<br><span class='gd-jp'>窓が開いています。</span>（窗戶開著）→ 只是描述你看到的樣子<br><span class='gd-jp'>夏はいつも窓を開けています。</span>（夏天我都會把窗戶打開）→ 說的是人做的動作、習慣</div><div class='gd-warn'>判斷小訣竅：只是看到「開著、亮著、關著」，就用「が＋自動詞ています」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>他動詞加「〜てあります」，意思是「有人特地弄好、放著」：<span class='gd-jp'>窓が開けてあります。</span>（窗戶有人特地打開了）</div>",
  "n5-15": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「は」就是中文的<b>「說到～啊，…」</b>。先把要聊的東西擺在句子最前面，跟對方說「現在要講這個喔」，後面再說它怎麼樣。<span class='gd-jp'>私は学生です。</span>就是「說到我啊，是學生」，也就是「我是學生」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞後面直接加は就好：<br><span class='gd-pair'><span class='gd-jp'>私</span> → <span class='gd-jp'>私は</span></span><span class='gd-pair'><span class='gd-jp'>伊藤さん</span> → <span class='gd-jp'>伊藤さんは</span></span><span class='gd-pair'><span class='gd-jp'>今日</span> → <span class='gd-jp'>今日は</span></span><br><b>念法很重要</b>：當助詞用的時候，寫成<span class='gd-jp'>は</span>，但是念 <b>wa</b>，跟<span class='gd-jp'>わ</span>同音。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>介紹、說明</span>最基本的用法：先講「誰／什麼」，再講「是怎樣」。</div><div class='gd-ex-line'>・<span class='gd-jp'>伊藤さんは建築家です。</span>（伊藤先生是建築師）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は暑いですね。</span>（今天好熱喔）</div><div class='gd-sec'><span class='gd-tag'>先講主題，再講細節</span>は前面放「這句在聊什麼」，後面可以再出現別的主角。</div><div class='gd-ex-line'>・<span class='gd-jp'>象は鼻が長いです。</span>（大象的鼻子很長）</div><div class='gd-ex-line'>・<span class='gd-jp'>そのケーキは姉が焼きました。</span>（那個蛋糕是姊姊烤的）</div><div class='gd-sec'>第二句很多人會卡住：烤蛋糕的是姊姊，不是蛋糕。所以<b>は前面不一定是「做動作的人」</b>，它只是在說「這句話在聊什麼」。這句聊的是蛋糕，再補充「是姊姊烤的」。</div><div class='gd-sec'><span class='gd-tag'>比較兩樣東西</span>兩邊都用は，就有「這個是這樣，那個就不一樣了」的對比感。</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーは好きですが、お茶はあまり飲みません。</span>（咖啡我喜歡，茶就不太喝）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・助詞的は念 wa。招呼語<span class='gd-jp'>こんにちは</span>、<span class='gd-jp'>こんばんは</span>最後的は也念 wa。其他單字裡的は照樣念 ha，像<span class='gd-jp'>はい</span>、<span class='gd-jp'>花</span>。<br>・用「誰」「どれ」這種疑問詞當句子的主角問問題時，後面要接が，不能接は：<span class='gd-jp'>誰は来ましたか</span>是錯的，要說<span class='gd-jp'>誰が来ましたか</span>（誰來了？）。<br>・主題講過一次，後面就可以省略。中文習慣每句都說「我」，日文講過一次<span class='gd-jp'>私は</span>之後通常就不再重複，一直講反而很囉嗦：<span class='gd-jp'>私は陳です。台湾から来ました。</span>（我姓陳，從台灣來的）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>は跟が最容易混。看同一個場景：公司來了新同事。<br>大家還不認識你，你自我介紹：<span class='gd-jp'>私は陳です。</span>（我是陳）→ 大家想知道的是<b>後面</b>的「陳」。<br>有人在找你：<span class='gd-jp'>陳さんはどちらですか。</span>（請問哪位是陳先生？）你舉手說：<span class='gd-jp'>私が陳です。</span>（我就是陳）→ 這時候重點是<b>前面</b>的「我」。<br>另外，眼前剛看到、剛發生的事，也用が：<span class='gd-jp'>あ、バスが来ました。</span>（啊，公車來了）</div><div class='gd-warn'>判斷小訣竅：用は，重點在<b>は的後面</b>；用が，重點在<b>が的前面</b>。回答「誰？哪個？」的答案、剛看到的事，用が。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把は換成<b>も</b>，就變成「也」：<span class='gd-jp'>私も学生です。</span>（我也是學生）。注意是直接換掉，不是疊在一起，沒有「私はも」這種說法。</div>",
  "n5-34": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「が」就像用手指著說<b>「就是它！」</b>。某件事是<b>誰</b>做的、是<b>什麼</b>發生了，要把那個主角點出來的時候，後面就放が。<br>例如有人問「誰來了？」你答「田中先生來了」。這個「田中先生」就是被點出來的答案，所以用<span class='gd-jp'>田中さんが来ました</span>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞後面直接加が，不用變化。<br><span class='gd-jp'>私が</span>、<span class='gd-jp'>雨が</span>、<span class='gd-jp'>田中さんが</span>、<span class='gd-jp'>誰が</span>、<span class='gd-jp'>何が</span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>問誰、問什麼</span>「誰」「什麼」是句子的主角時，問的時候用が，回答也用が。</div><div class='gd-ex-line'>・<span class='gd-jp'>誰が来ましたか。</span>（誰來了？）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんが来ました。</span>（田中先生來了。）</div><div class='gd-ex-line'>・<span class='gd-jp'>何が一番おいしいですか。</span>（什麼最好吃？）</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンが一番おいしいです。</span>（這碗拉麵最好吃。）</div><div class='gd-sec'><span class='gd-tag'>眼前看到的事</span>剛看到、剛發生的狀況，直接把畫面講出來。</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、バスが来ました。</span>（啊，公車來了。）</div><div class='gd-ex-line'>・<span class='gd-jp'>雪が降っています。</span>（正在下雪。）</div><div class='gd-sec'><span class='gd-tag'>第一次提到</span>對方還不知道的人或事，你第一次把它帶出來。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、友達が家に来ました。</span>（昨天有朋友來我家。）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>「誰、什麼、哪裡」後面不能接は</b>。<span class='gd-jp'>誰は来ましたか</span>是錯的，要說<span class='gd-jp'>誰が来ましたか</span>。其他疑問詞也一樣，例如<span class='gd-jp'>どこが痛いですか</span>（哪裡痛？）。<br>・<b>用が問，就用が答</b>。人家問<span class='gd-jp'>誰が作りましたか</span>（誰做的？），你要答<span class='gd-jp'>私が作りました</span>（是我做的）。答成「私は作りました」會變成「我嘛，是有做啦」，聽起來很怪。<br>・台灣人很習慣每句話的主語都放は。可是看到窗外突然在下雨，要說<span class='gd-jp'>あ、雨が降っています</span>，這種直接講眼前畫面的句子用が才自然。<br>・<span class='gd-jp'>日本語が好きです</span>、<span class='gd-jp'>ピアノができます</span>也用が，但那是「喜歡什麼、會什麼」的用法，另一張卡「助詞が（能力・好惡）」會講，先不要混在一起。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>は</b>是「說到～嘛」，先把話題擺出來，<b>重點在後面</b>。<br><b>が</b>是「就是～」，<b>重點就在前面這個名詞</b>。<br><br>同樣在講自己是田中：<br>自我介紹時說<span class='gd-jp'>私は田中です。</span>（我是田中。）這時大家在聽「我是誰」。<br>有人問<span class='gd-jp'>田中さんはどの人ですか。</span>（田中先生是哪一位？）你要說<span class='gd-jp'>私が田中です。</span>（我就是田中。）這時是從一群人裡把田中點出來。<br><br>同樣在講田中有來：<br><span class='gd-jp'>田中さんが来ました。</span>（田中先生來了。）單純報告是誰來了。<br><span class='gd-jp'>田中さんは来ました。</span>（田中先生是有來啦。）先拿田中當話題，帶有「至於別人就不一定」的味道。</div><div class='gd-warn'>判斷小訣竅：要回答「是誰、是什麼」就用が；要講「這個人、這個東西怎麼樣」就用は。疑問詞當主角的時候，後面一律用が。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「有什麼東西在哪裡」也用が：<span class='gd-jp'>あそこに猫がいます。</span>（那邊有一隻貓。）接著可以學存在表現，還有「喜歡、會」用が的說法。</div>",
  "n5-31": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「から」就是中文的<b>「因為～，所以～」</b>。不一樣的是，中文把「因為」放在最前面，日文的「から」放在<b>理由那句話的最後面</b>，說完理由再說結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>時間がないから、急ぎましょう。</span>（因為沒時間了，我們快一點吧）</div><div class='gd-sec'>順序就是：<b>理由 ＋ から、結果</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>「から」前面放一句完整的話，可以是普通的說法，也可以是有です・ます的禮貌說法。<br><b>動詞</b>：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くから</span></span><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きますから</span></span><br><b>い形容詞</b>：<span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いから</span></span><span class='gd-pair'><span class='gd-jp'>寒いです</span> → <span class='gd-jp'>寒いですから</span></span><br><b>な形容詞</b>：要先加「だ」或「です」。<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだから</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かですから</span></span><br><b>名詞</b>：一樣要加「だ」或「です」。<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だから</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨ですから</span></span><br>過去的事也可以：<span class='gd-pair'><span class='gd-jp'>寝なかった</span> → <span class='gd-jp'>寝なかったから</span></span></div><div class='gd-sec'>前面用普通說法、句尾用ます，日常很常見；想講得更客氣，就前後都用です・ます。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>說明理由</span>先講原因，再講結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いから、よく来ます。</span>（這家店很便宜，所以我常來）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は日曜日だから、学校は休みです。</span>（今天是星期天，所以學校放假）</div><div class='gd-sec'><span class='gd-tag'>拜託、提醒、揪人</span>後面接請求或邀約也很自然。</div><div class='gd-ex-line'>・<span class='gd-jp'>危ないですから、触らないでください。</span>（很危險，請不要碰）</div><div class='gd-sec'><span class='gd-tag'>只回答理由</span>別人問「為什麼」，結果大家都知道了，就只講理由加から。</div><div class='gd-ex-line'>・<span class='gd-jp'>「どうして食べないの？」「辛いから。」</span>（「你怎麼不吃？」「因為很辣。」）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞後面<b>不能直接接から</b>：說<span class='gd-jp'>雨だから</span>，不是「雨から」；說<span class='gd-jp'>静かだから</span>，不是「静かから」。<br>・い形容詞反過來，<b>不能加だ</b>：說<span class='gd-jp'>高いから</span>，不是「高いだから」。<br>・別照中文順序把から放在句子開頭。「因為下雨」是<span class='gd-jp'>雨だから</span>，から在後面。<br>・句子開頭單獨一個<span class='gd-jp'>だから</span>，意思是「所以」：<span class='gd-jp'>雨です。だから、行きません。</span>（下雨。所以不去）<br>・對老師、主管解釋自己的狀況（例如遲到的原因）時，から聽起來比較直接，有時像在找藉口。日常講話用から完全沒問題。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>你已經學過表示起點的「から」（<b>從～</b>），兩個長得一模一樣。<br><b>起點</b>：<span class='gd-jp'>9時から働きます。</span>（從 9 點開始工作）<br><b>理由</b>：<span class='gd-jp'>雨だから、働きません。</span>（因為下雨，所以不工作）<br>差別在前面接什麼：起點的から前面直接接時間或地點的名詞；理由的から前面是一句話的結尾，例如動詞、形容詞，或是「だ」「です」。</div><div class='gd-warn'>判斷小訣竅：から前面只有<span class='gd-jp'>9時</span>、<span class='gd-jp'>駅</span>這種名詞，就是「從」；前面是<span class='gd-jp'>雨だ</span>、<span class='gd-jp'>寒い</span>、<span class='gd-jp'>あります</span>這種完整說法，就是「因為」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把理由放到句尾變成「〜からです」，用來回答「為什麼」：<span class='gd-jp'>熱があるからです。</span>（因為發燒）。之後還會學到「〜ので」，也是「因為」，口氣比から柔和，跟主管請假、道歉時更常用。</div>",
  "n5-54": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這三個句型用來排<b>做事的順序</b>，跟中文一樣好懂：<br><span class='gd-jp'>〜てから</span>＝「先～，再～」<br><span class='gd-jp'>〜たあとで</span>＝「～之後」<br><span class='gd-jp'>〜まえに</span>＝「～之前」<br>像在跟朋友講自己的一天：刷完牙再睡、吃完飯之後看電視、出門前先看天氣。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>先～再～</span>動詞<b>て形</b>＋から。<br><span class='gd-pair'><span class='gd-jp'>磨く</span> → <span class='gd-jp'>磨いて</span> → <span class='gd-jp'>磨いてから</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べてから</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>してから</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>歯を磨いてから、寝ます。</span>（刷完牙再睡覺）</div><div class='gd-ex-line'>・<span class='gd-jp'>手を洗ってから、食べてください。</span>（請先洗手再吃）</div><div class='gd-sec'><span class='gd-tag'>～之後</span>動詞<b>た形</b>＋あとで。た形就是把て形的「て」換成「た」，「で」換成「だ」。<br><span class='gd-pair'><span class='gd-jp'>見て</span> → <span class='gd-jp'>見た</span> → <span class='gd-jp'>見たあとで</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだあとで</span></span><br>前面是名詞的話，中間加「の」：<span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事のあとで</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>映画を見たあとで、ご飯を食べました。</span>（看完電影之後吃了飯）</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事のあとで、ビールを飲みます。</span>（下班之後喝啤酒）</div><div class='gd-sec'><span class='gd-tag'>～之前</span>動詞<b>辭書形</b>（字典裡查到的原本樣子）＋まえに。<br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝るまえに</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くまえに</span></span><br>前面是名詞一樣加「の」：<span class='gd-pair'><span class='gd-jp'>食事</span> → <span class='gd-jp'>食事のまえに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>寝るまえに、シャワーを浴びます。</span>（睡覺前沖個澡）</div><div class='gd-ex-line'>・<span class='gd-jp'>食事のまえに、手を洗います。</span>（吃飯前洗手）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・まえに前面<b>永遠是辭書形</b>，就算在講過去的事也一樣：<span class='gd-jp'>日本へ来るまえに、英語を勉強しました。</span>（來日本之前學過英文）。不能說「来たまえに」。<br>・あとで前面<b>永遠是た形</b>，就算在講還沒發生的事也一樣：<span class='gd-jp'>食べたあとで、歯を磨きます。</span>（吃完之後要刷牙）。不能說「食べるあとで」。<br>・整句是過去還是現在，<b>看句尾</b>決定（磨きます／磨きました），前半句不用跟著變。<br>・名詞直接接會漏掉「の」：要說<span class='gd-jp'>授業のあとで</span>，不是「授業あとで」。<br>・<span class='gd-jp'>あとで</span>前面沒接東西、單獨出現時，是「待會、晚點」：<span class='gd-jp'>あとで電話します。</span>（我晚點打給你）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>てから跟あとで都是「A做完才B」，很多時候兩個都能用，差在語感：<br><span class='gd-jp'>お風呂に入ってから、ご飯を食べます。</span>（<b>先</b>洗完澡，<b>再</b>吃飯：強調順序，有「洗完澡才吃」的感覺）<br><span class='gd-jp'>お風呂に入ったあとで、ご飯を食べます。</span>（洗完澡之後吃飯：只是交代吃飯的時間點在後面）<br>要對方「一定要先做好A」的時候，用てから最自然：<br><span class='gd-jp'>電話してから来てください。</span>（請先打電話再過來）</div><div class='gd-warn'>判斷小訣竅：想說「先～再～」用<b>てから</b>；只是說「～之後」用<b>たあとで</b>；說「～之前」用<b>まえに</b>，而且前面一定是辭書形。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>てから後面接一段時間，就變成「自從～已經…」：<span class='gd-jp'>日本に来てから、もう三年です。</span>（來日本已經三年了）</div>",
  "n5-58": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ながら」就是中文的<b>「一邊～一邊～」</b>。不過日文有個習慣：<b>比較重要的那件事放在後面</b>。像「邊聽音樂邊唸書」，你主要是在唸書，音樂只是陪襯，所以日文說<span class='gd-jp'>音楽を聞きながら勉強します。</span></div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ます形，<b>把「ます」拿掉</b>，直接加「ながら」。三類動詞都一樣。<br><span class='gd-pair'><span class='gd-jp'>聞きます</span> → ます拿掉 → <span class='gd-jp'>聞きながら</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べながら</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見ながら</span></span><span class='gd-pair'><span class='gd-jp'>運転します</span> → <span class='gd-jp'>運転しながら</span></span><br>後面再接主要的動作。「ながら」本身<b>永遠不變</b>，要講過去、否定、要不要禮貌，全部交給最後那個動詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>歌を歌いながら、料理しました。</span>（我一邊唱歌一邊做了菜）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>同一時間做兩件事</span>手在做這個，同時也在做那個。</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビを見ながら、ご飯を食べます。</span>（邊看電視邊吃飯）</div><div class='gd-ex-line'>・<span class='gd-jp'>歩きながらスマホを見るのは危ないです。</span>（邊走路邊看手機很危險）</div><div class='gd-sec'><span class='gd-tag'>這段時間兩件事都在做</span>不一定是同一秒，也可以是這陣子兩件事並行，像「半工半讀」。</div><div class='gd-ex-line'>・<span class='gd-jp'>アルバイトをしながら、日本語を勉強しています。</span>（我一邊打工一邊學日文）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・要接<b>ます形拿掉ます</b>，不是原本的辭書形：<span class='gd-jp'>聞きながら</span>才對，不能說「聞くながら」；<span class='gd-jp'>食べながら</span>才對，不能說「食べるながら」。<br>・前後兩件事必須是<b>同一個人</b>在做。「媽媽煮飯的時候，我在看電視」是兩個人，不能用ながら，要改用「とき」：<span class='gd-jp'>母が料理をしているとき、私はテレビを見ていました。</span><br>・別照中文隨便對調。中文「一邊A一邊B」前後換一下差不多，日文<b>後面的才是主角</b>。<span class='gd-jp'>勉強しながら音楽を聞きます</span>聽起來變成「主要在聽音樂，順便唸書」。<br>・過去式、禮貌只改最後的動詞，ながら前面不要加ました：不能說「聞きましたながら」，要說<span class='gd-jp'>聞きながら勉強しました</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>て形連接</b>＝做完一件<b>再</b>做下一件，有先後順序。<br><b>ながら</b>＝兩件事<b>同時</b>進行。</div><div class='gd-ex-line'>・<span class='gd-jp'>ご飯を食べて、テレビを見ます。</span>（吃完飯，再看電視）</div><div class='gd-ex-line'>・<span class='gd-jp'>ご飯を食べながら、テレビを見ます。</span>（邊吃飯邊看電視）</div><div class='gd-sec'><b>〜たり〜たりします</b>＝舉例說說做了哪些事，不是同時做。</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は本を読んだり、映画を見たりします。</span>（週末會看看書、看看電影之類的）</div><div class='gd-warn'>判斷小訣竅：同時在做是ながら，做完再做是て形，隨便舉幾件做過的事是たり〜たり。</div>",
  "n5-56": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜たり〜たりします」就像中文的<b>「看看書、看看電影之類的」</b>。從一堆事情裡挑兩三件當例子講，意思是「我只是舉例，還有做別的」。它還有第二個用法：<b>「一下這樣、一下那樣」</b>，像中文的「忽冷忽熱」「下下停停」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>舉例</span>別人問你平常做什麼，你不用全部講完，挑幾件代表的講就好。</div><div class='gd-ex-line'>・<span class='gd-jp'>休みの日は、本を読んだり映画を見たりします。</span>（假日會看看書、看看電影）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は掃除したり、買い物に行ったりします。</span>（週末會打掃一下、去買個東西之類的）</div><div class='gd-sec'><span class='gd-tag'>一下這樣一下那樣</span>兩個相反的動作或狀態輪流出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、暑かったり寒かったりします。</span>（最近忽冷忽熱）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は雨が降ったりやんだりしています。</span>（今天的雨下下停停）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>三個步驟：<b>動詞先變成た形 → 後面加り → 最後補上します</b>。<br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んだ</span> → <span class='gd-jp'>読んだり</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったり</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span> → <span class='gd-jp'>見たり</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span> → <span class='gd-jp'>したり</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span> → <span class='gd-jp'>来たり</span></span><br>如果た形還不熟，可以想成<b>把て形的「て」換成「た」、「で」換成「だ」</b>：<br><span class='gd-pair'><span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んだ</span></span><span class='gd-pair'><span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べた</span></span></div><div class='gd-sec'><b>い形容詞</b>：把「い」拿掉，換成「かったり」。<br><span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑かったり</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かったり</span></span>（<span class='gd-jp'>いい</span>要變成<span class='gd-jp'>よかったり</span>）<br><b>名詞、な形容詞</b>：後面加「だったり」。</div><div class='gd-ex-line'>・<span class='gd-jp'>朝ごはんはパンだったりご飯だったりします。</span>（早餐有時候吃麵包，有時候吃飯）</div><div class='gd-sec'>過去式、禮貌程度，全部交給<b>最後那個する</b>去變：</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は友達と話したり、ゲームをしたりしました。</span>（昨天跟朋友聊聊天、打打電動）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は家で寝たり、テレビを見たりする。</span>（週末就在家睡睡覺、看看電視：跟朋友講的說法）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・要接<b>た形</b>，不是ます形：是<span class='gd-jp'>行ったり</span>，不是行きたり；是<span class='gd-jp'>読んだり</span>，不是読みたり。<br>・句子最後的<span class='gd-jp'>します</span>（或<span class='gd-jp'>する</span>）不要漏掉，少了它，句子聽起來就像話沒講完。<br>・過去式只改最後面：<span class='gd-jp'>行ったりしました</span>才對，不會說成行きましたり。<br>・兩個以上的動作，每一個後面都要加たり。口語偶爾會聽到第二個たり被省略，但考試和寫作要老老實實寫出來。只舉一件事也可以，例如<span class='gd-jp'>映画を見たりします</span>（會看看電影之類的）。<br>・たり<b>不代表先後順序</b>。想說「先做A再做B」，要用て形。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在講「昨天做了什麼」：<br><b>て</b>＝照順序講，而且就是這幾件：<span class='gd-jp'>昨日は本を読んで、映画を見ました。</span>（昨天看了書，然後去看了電影）<br><b>たり</b>＝挑幾件舉例，還有別的，不管順序：<span class='gd-jp'>昨日は本を読んだり、映画を見たりしました。</span>（昨天看看書、看看電影之類的）<br><b>や</b>＝也是舉例，但接的是<b>東西（名詞）</b>：<span class='gd-jp'>昨日は本や漫画を読みました。</span>（昨天看了書啊、漫畫之類的）</div><div class='gd-warn'>判斷小訣竅：照順序把事情講完用「て」；挑幾個<b>動作</b>舉例用「たり」；挑幾樣<b>東西</b>舉例用「や」。</div>",
  "n5-1": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「名詞＋です」就是中文的<b>「是～」</b>，「名詞＋じゃありません」就是<b>「不是～」</b>。<span class='gd-jp'>私は学生です。</span>就是「我是學生」。這是日文最基本的句子，自我介紹第一句就會用到。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>很簡單，名詞後面<b>直接加</b>，名詞本身完全不用變。<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生です</span></span>（是學生）<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生じゃありません</span></span>（不是學生）<br>句型就是「A<span class='gd-jp'>は</span>B<span class='gd-jp'>です</span>」＝A是B。</div><div class='gd-ex-line'>・<span class='gd-jp'>林です。よろしくお願いします。</span>（我姓林，請多指教）</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の傘です。</span>（這是我的傘）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは先生じゃありません。</span>（田中先生不是老師）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休みじゃありません。</span>（明天不是休假日）</div><div class='gd-sec'>後面加<span class='gd-jp'>か</span>就變成問句：<span class='gd-jp'>学生ですか。</span>（你是學生嗎？）</div><div class='gd-h'>「不是」的幾種說法</div><div class='gd-sec'>意思都一樣，差在場合：<br><span class='gd-tag'>最常用</span><span class='gd-jp'>学生じゃありません</span>：日常有禮貌的說法。<br><span class='gd-tag'>比較正式</span><span class='gd-jp'>学生ではありません</span>：寫文章、正式場合。「じゃ」就是「では」講快的樣子。<br><span class='gd-tag'>比較輕鬆</span><span class='gd-jp'>学生じゃないです</span>：一樣有禮貌，口氣比較軟，現在日本人講話很常用。</div><div class='gd-h'>跟朋友講的時候</div><div class='gd-sec'>跟家人、好朋友不用です，改成<b>だ／じゃない</b>：<br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だ</span></span><span class='gd-pair'><span class='gd-jp'>学生じゃありません</span> → <span class='gd-jp'>学生じゃない</span></span><br>不過實際聊天時「だ」常常省略，或後面加「よ」比較自然，不然聽起來有點硬：</div><div class='gd-ex-line'>・<span class='gd-jp'>うん、学生だよ。</span>（嗯，我是學生啊）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「AはB」的<span class='gd-jp'>は</span>要念<b>wa</b>，不是ha。<br>・<span class='gd-jp'>です</span>最後的「す」通常念得很輕，聽起來像「des」。<br>・です不一定翻成「是」：<span class='gd-jp'>今日は雨です。</span>是「今天下雨」，中文不會說「今天是雨」。<br>・動詞後面不能加です：<span class='gd-jp'>食べます</span>就好，不能說「食べるです」。<br>・不用每句都說<span class='gd-jp'>私は</span>，對方知道在講你自己時，日本人通常會省略。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>名詞、な形容詞的否定都用じゃありません，<b>い形容詞不一樣</b>，最容易混。<br><b>名詞</b>：<span class='gd-jp'>ここは駅じゃありません。</span>（這裡不是車站）<br><b>な形容詞</b>：<span class='gd-jp'>ここは静かじゃありません。</span>（這裡不安靜）<br><b>い形容詞</b>：<span class='gd-jp'>ここは高くないです。</span>（這裡不貴）<br>不能說「高いじゃありません」，要把い換成<b>くない</b>。</div><div class='gd-warn'>判斷小訣竅：名詞和な形容詞直接加「じゃありません」；い形容詞要把い換成「くないです」。注意<span class='gd-jp'>きれい</span>雖然是い結尾，其實是な形容詞，所以要說<span class='gd-jp'>きれいじゃありません</span>。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>過去的說法：<span class='gd-jp'>学生でした</span>（以前是學生）、<span class='gd-jp'>学生じゃありませんでした</span>（以前不是學生）。</div>",
  "n5-2": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ます」是日文的<b>禮貌模式</b>，對老師、店員、剛認識的人都用它；跟家人、好朋友才會用沒有ます的說法。要說「不（做）」，就把ます換成<b>ません</b>。剛開始學，<b>全部先用ます最安全</b>，不會失禮。</div><div class='gd-h'>一個形，管現在也管未來</div><div class='gd-sec'>日文沒有另外的「未來式」，平常的習慣和接下來要做的事都用「〜ます」，時間靠「毎日」「明日」「来週」這種詞來交代。</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日コーヒーを飲みます。</span>（我每天喝咖啡：習慣）</div><div class='gd-ex-line'>・<span class='gd-jp'>来週、京都へ行きます。</span>（我下週要去京都：未來）</div><div class='gd-ex-line'>・<span class='gd-jp'>田村先生はお酒を飲みません。</span>（田村老師不喝酒）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「い」段音，再加ます。<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → む換成み → <span class='gd-jp'>飲みます</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行きます</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買います</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ります</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加ます。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ます</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きます</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ます</span>（きます）</span><br>「勉強する」「出張する」這種「名詞＋する」的字也一樣：<span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強します</span></span></div><div class='gd-sec'>否定只要把ます換成ません，三類都一樣：<span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べません</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span>長得像第二類，其實是第一類：是<span class='gd-jp'>帰ります</span>，不是帰ます。<br>・「ません」是「不（做）」，不是「不能」：<span class='gd-jp'>お酒を飲みません</span>是「我不喝酒」，不是「我不能喝」。<br>・ます只能接在<b>動詞</b>後面。說「我是學生」要用<span class='gd-jp'>学生です</span>，不能說学生ます。<br>・ます的「す」通常念得很輕，聽起來像「mas」，聽到不用懷疑自己聽錯。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>台灣人很常把「我正在～」直接說成ます，但ます講的是<b>習慣</b>或<b>接下來要做</b>，「正在做」要用<b>ています</b>。<br><span class='gd-jp'>今、ご飯を食べます。</span>（我現在要吃飯了：還沒開始吃）<br><span class='gd-jp'>今、ご飯を食べています。</span>（我現在正在吃飯：已經在吃了）</div><div class='gd-warn'>判斷小訣竅：還沒開始、或每天都這樣做，用ます；手上正在做，用ています。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>講過去的事：<span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みました</span></span>（喝了）、<span class='gd-pair'><span class='gd-jp'>飲みません</span> → <span class='gd-jp'>飲みませんでした</span></span>（沒喝）。<br>想邀約別人，可以接著學<span class='gd-jp'>〜ませんか</span>和<span class='gd-jp'>〜ましょう</span>。</div>",
  "n5-3": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'><span class='gd-jp'>静か</span>（安靜）、<span class='gd-jp'>きれい</span>（漂亮）、<span class='gd-jp'>親切</span>這類形容詞，日文叫<b>な形容詞</b>。說「很安靜」就是<span class='gd-jp'>静かです</span>，說「不安靜」就是<span class='gd-jp'>静かじゃありません</span>。用法跟名詞句幾乎一樣，只多一條規則：<b>直接放在名詞前面時，要補一個「な」</b>。</div><div class='gd-h'>什麼是な形容詞</div><div class='gd-sec'>它們是用來形容狀態、感覺的詞，中文多半翻成「很～」。叫「な形容詞」，是因為接名詞時會多一個な。卡片上寫的「語幹」，就是單字表上看到的原本樣子，例如<span class='gd-jp'>静か</span>，後面什麼都不加。<br>先記住這些最常用的：<br><span class='gd-jp'>静か</span>（安靜）、<span class='gd-jp'>きれい</span>（漂亮、乾淨）、<span class='gd-jp'>元気</span>（有精神）、<span class='gd-jp'>有名</span>（有名）、<span class='gd-jp'>便利</span>（方便）、<span class='gd-jp'>暇</span>（有空）、<span class='gd-jp'>大変</span>（辛苦）、<span class='gd-jp'>好き</span>（喜歡）、<span class='gd-jp'>嫌い</span>（討厭）、<span class='gd-jp'>上手</span>（拿手）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>肯定</span>原本的樣子直接加<span class='gd-jp'>です</span>。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>この喫茶店は静かです。</span>（這間咖啡店很安靜）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の近くは便利です。</span>（車站附近很方便）</div><div class='gd-sec'><span class='gd-tag'>否定</span>原本的樣子直接加<span class='gd-jp'>じゃありません</span>，前面的字完全不用動。<br><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇じゃありません</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>今日は暇じゃありません。</span>（我今天沒空）</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は有名じゃありません。</span>（這個小鎮沒什麼名氣）</div><div class='gd-sec'>否定還有兩種說法，意思一樣：<span class='gd-jp'>ではありません</span>比較正式，課本、文章常見；<span class='gd-jp'>じゃないです</span>比較口語，但一樣有禮貌。</div><div class='gd-sec'><span class='gd-tag'>問問題</span>後面加<span class='gd-jp'>か</span>就好。</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は大変ですか。</span>（工作很辛苦嗎？）</div><div class='gd-h'>放在名詞前面：要加な</div><div class='gd-sec'>想說「安靜的小鎮」「親切的人」，就是在中間補一個<span class='gd-jp'>な</span>，你可以把它想成中文的「的」。<br><span class='gd-pair'><span class='gd-jp'>静か</span>＋<span class='gd-jp'>町</span> → <span class='gd-jp'>静かな町</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>静かな町です。</span>（是個安靜的小鎮）</div><div class='gd-ex-line'>・<span class='gd-jp'>京都はきれいな所です。</span>（京都是個漂亮的地方）</div><div class='gd-ex-line'>・<span class='gd-jp'>親切な人ですね。</span>（真是個親切的人呢）</div><div class='gd-sec'>記法很簡單：<b>後面接です，不加な；後面接名詞，才加な</b>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>嫌い</span>結尾有「い」，看起來像い形容詞，其實是な形容詞。否定是<span class='gd-jp'>きれいじゃありません</span>，不是「きれくないです」。<br>・です前面不要加な：是<span class='gd-jp'>静かです</span>，不是「静かなです」。<br>・名詞前面不能少な，也不要因為中文有「的」就放の：是<span class='gd-jp'>静かな町</span>，不是「静か町」，也不是「静かの町」。<br>・<span class='gd-jp'>好き</span>、<span class='gd-jp'>嫌い</span>的對象用<b>が</b>：<span class='gd-jp'>猫が好きです</span>（我喜歡貓）。中文「喜歡貓」很像動詞加受詞，所以很多人會寫成「猫を好きです」，初學先記用が就對了。<br>・直接說「嫌いです」有點衝。日本人常用<span class='gd-jp'>あまり好きじゃありません</span>（不太喜歡），聽起來柔和很多。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在講「這間店」，三種詞的否定長得不一樣：<br><b>い形容詞</b>：結尾的い要變成くない。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安くないです。</span>（這間店不便宜）</div><div class='gd-sec'><b>な形容詞</b>：本體不動，後面接じゃありません。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店はきれいじゃありません。</span>（這間店不乾淨）</div><div class='gd-sec'><b>名詞</b>：跟な形容詞一樣，後面接じゃありません。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここは銀行じゃありません。</span>（這裡不是銀行）</div><div class='gd-warn'>判斷小訣竅：背單字時就連な一起背，記成<span class='gd-jp'>きれいな</span>、<span class='gd-jp'>静かな</span>。會說成「～な＋名詞」的，否定就直接加じゃありません；只有い形容詞才會把い變成くない。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>過去式把です換成でした：<span class='gd-jp'>昨日は暇でした。</span>（昨天很閒）</div>",
  "n5-4": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>像「冷」「貴」「好吃」這種用來形容東西的詞，日文叫<b>い形容詞</b>，因為它們最後一個字都是「い」，例如<span class='gd-jp'>寒い</span>、<span class='gd-jp'>高い</span>、<span class='gd-jp'>おいしい</span>。<br>要有禮貌地說「很冷」，後面直接加<b>です</b>。要說「不冷」，就把最後的い換成<b>く</b>，再加<b>ないです</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>肯定</span>原本的樣子直接加です，最後的い不用動。<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いです</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いです</span></span></div><div class='gd-sec'><span class='gd-tag'>否定</span>把最後的い換成く，再加ないです。<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → い換成く → <span class='gd-jp'>寒く</span> → <span class='gd-jp'>寒くないです</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高くないです</span></span><span class='gd-pair'><span class='gd-jp'>おいしい</span> → <span class='gd-jp'>おいしくないです</span></span><span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きくないです</span></span></div><div class='gd-sec'>課本上也會看到<span class='gd-jp'>寒くありません</span>，意思一樣，聽起來稍微正式一點。日常講話用「くないです」就很夠了。</div><div class='gd-h'>實際說說看</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはおいしいです。</span>（這碗拉麵很好吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は広くないです。</span>（這個房間不大）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はあまり寒くないです。</span>（今天不太冷）</div><div class='gd-sec'>中文習慣說「<b>很</b>冷」，其實<span class='gd-jp'>寒いです</span>本身就是這個意思，不用硬加「とても」。真的很冷、想強調，才說<span class='gd-jp'>とても寒いです</span>。<br>另外，<span class='gd-jp'>あまり</span>後面接否定是「<b>不太</b>～」，比直接說「不～」委婉，日本人很常用。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>いい</span>是例外：否定是<b><span class='gd-jp'>よくないです</span></b>，不是いくないです。因為いい原本是從<span class='gd-jp'>よい</span>來的，變化時要用よ。<span class='gd-jp'>かっこいい</span>也一樣，否定是<span class='gd-jp'>かっこよくないです</span>。<br>・要說「不冷」，不能講寒いじゃないです。い形容詞的否定一定是把い換成く，不用じゃない。<br>・不要在中間多加だ：寒いだです是錯的。有禮貌就說<span class='gd-jp'>寒いです</span>，跟朋友講就只說<span class='gd-jp'>寒い</span>。<br>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>嫌い</span>、<span class='gd-jp'>有名</span>最後聽起來也有「い」，但它們是な形容詞，否定是<span class='gd-jp'>きれいじゃないです</span>，不是きれくないです。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是說「這個房間不～」，看前面是哪種詞，否定的做法就不一樣：<br><b>い形容詞</b>：把い換成く，加ないです<br>・<span class='gd-jp'>この部屋は明るくないです。</span>（這個房間不亮）<br><b>な形容詞</b>：後面加じゃないです<br>・<span class='gd-jp'>この部屋は静かじゃないです。</span>（這個房間不安靜）<br><b>名詞</b>：後面也是加じゃないです<br>・<span class='gd-jp'>ここは私の部屋じゃないです。</span>（這裡不是我的房間）</div><div class='gd-warn'>判斷小訣竅：原本最後是「い」的，就把い換成く，加ないです。な形容詞跟名詞則是直接加じゃないです。看到きれい、嫌い、有名要特別小心，它們是な形容詞。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>過去式：<span class='gd-pair'><span class='gd-jp'>寒いです</span> → <span class='gd-jp'>寒かったです</span></span>（之前很冷）<br>表示變化：<span class='gd-jp'>寒くなります</span>（會變冷），否定時用到的「く」在這裡也會再出現。</div>",
  "n5-5": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜です」是「是～」，「〜でした」就是<b>「（那時候）是～」</b>。中文講過去的事，加個「昨天」「以前」就好，動詞不用變；日文不行，<b>講過去就要把です換成でした</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>是</span>名詞後面直接加でした。<br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生でした</span></span><span class='gd-pair'><span class='gd-jp'>休みです</span> → <span class='gd-jp'>休みでした</span></span></div><div class='gd-sec'><span class='gd-tag'>不是</span>先用現在的「じゃありません」，後面再加でした。<br><span class='gd-pair'><span class='gd-jp'>学生じゃありません</span> → <span class='gd-jp'>学生じゃありませんでした</span></span><br>寫在文章裡比較正式的是<span class='gd-jp'>ではありませんでした</span>，意思一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は雨でした。</span>（昨天是雨天）</div><div class='gd-ex-line'>・<span class='gd-jp'>先週の月曜日は祝日でした。</span>（上週一是國定假日）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は休みじゃありませんでした。</span>（昨天不是休假）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>問過去</span>句尾加か就變成問句。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は休みでしたか。</span>（你昨天休假嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、休みでした。</span>（對，是休假）</div><div class='gd-ex-line'>・<span class='gd-jp'>いいえ、休みじゃありませんでした。</span>（不是，沒有休假）</div><div class='gd-sec'><span class='gd-tag'>朋友版</span>跟好朋友講，でした換成<b>だった</b>，じゃありませんでした換成<b>じゃなかった</b>。<br><span class='gd-pair'><span class='gd-jp'>雨でした</span> → <span class='gd-jp'>雨だった</span></span><span class='gd-pair'><span class='gd-jp'>休みじゃありませんでした</span> → <span class='gd-jp'>休みじゃなかった</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・照中文習慣，前面有「昨日」就以為夠了，說成<span class='gd-jp'>昨日は休みです</span>。日文要改成<span class='gd-jp'>休みでした</span>。<br>・「不是」的過去最容易接錯：<span class='gd-jp'>学生じゃないでした</span>、<span class='gd-jp'>学生じゃでした</span>都不對，要說<span class='gd-jp'>学生じゃありませんでした</span>。<br>・日常口語也很常聽到<span class='gd-jp'>学生じゃなかったです</span>，一樣有禮貌、也是對的，聽到不用嚇到。<br>・でした只能接在名詞（和な形容詞）後面。<span class='gd-jp'>寒い</span>、<span class='gd-jp'>高い</span>這種い形容詞不能直接加でした：<span class='gd-jp'>寒いでした</span>是錯的，要說<span class='gd-jp'>寒かったです</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「昨天」的事，前面的字不一樣，尾巴就不一樣：<br><b>名詞</b>＋でした：<span class='gd-jp'>昨日は雨でした。</span>（昨天是雨天）<br><b>動詞</b>的ます換成ました：<span class='gd-jp'>昨日は雨が降りました。</span>（昨天下雨了）<br><b>い形容詞</b>的い換成かったです：<span class='gd-jp'>昨日は寒かったです。</span>（昨天很冷）<br><b>な形容詞</b>跟名詞一樣加でした：<span class='gd-jp'>昨日は静かでした。</span>（昨天很安靜）</div><div class='gd-warn'>判斷小訣竅：前面是名詞或な形容詞，用でした；前面是動詞，用ました；前面是い形容詞（如寒い、高い），用かったです。<br>注意：<span class='gd-jp'>きれい</span>、<span class='gd-jp'>有名</span>、<span class='gd-jp'>嫌い</span>雖然字尾是い，但屬於な形容詞，要用でした，例如<span class='gd-jp'>きれいでした</span>，不是きれかったです。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>動詞的過去<span class='gd-jp'>〜ました・〜ませんでした</span>，和い形容詞的過去<span class='gd-jp'>〜かったです</span>，三個一起記，講過去的事就不會卡住。</div>",
  "n5-6": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ました」是「〜ます」的<b>過去版</b>，「〜ませんでした」是「〜ません」的過去版。中文說「我昨天去了」，加個「了」就好；日文要改動詞的尾巴：<span class='gd-pair'><span class='gd-jp'>行きます</span>（去）→ <span class='gd-jp'>行きました</span>（去了）</span>。它跟ます一樣是禮貌說法，對老師、店員講都不會失禮。</div><div class='gd-h'>怎麼變：會ます形就搞定</div><div class='gd-sec'>用「喝」當例子，四種樣子一次看：<br>現在、會做：<span class='gd-jp'>飲みます</span>（喝）<br>現在、不做：<span class='gd-jp'>飲みません</span>（不喝）<br>過去、做了：<span class='gd-jp'>飲みました</span>（喝了）<br>過去、沒做：<span class='gd-jp'>飲みませんでした</span>（沒喝）<br><br>規則只有兩條：<b>ます換成ました</b>；<b>ません後面加でした</b>。<br>因為都是從ます形開始變，三類動詞的規則完全一樣：<br><b>第一類（五段動詞）</b>：<span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きました</span></span><br><b>第二類（一段動詞）</b>：<span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べました</span></span><br><b>第三類（する・来る）</b>：<span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しました</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来ました</span>（きました）</span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>做了</span>講已經發生的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>先月、札幌へ行きました。</span>（上個月去了札幌）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、映画を見ました。</span>（昨天看了電影）</div><div class='gd-sec'><span class='gd-tag'>沒做</span>講過去那段時間沒做的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は朝ご飯を食べませんでした。</span>（今天早上沒吃早餐）</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題をしませんでした。</span>（我沒寫作業）</div><div class='gd-sec'><span class='gd-tag'>問別人</span>後面加か就變成問句。</div><div class='gd-ex-line'>・<span class='gd-jp'>週末、何をしましたか。</span>（週末做了什麼？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・過去的否定是「ません＋<b>でした</b>」，很多人會講成「食べませんました」，這是錯的。<br>・<span class='gd-jp'>来ました</span>念<b>きました</b>，不是こました。<br>・「ました」的「し」常常念得很輕，聽起來像「ma-shta」，聽到的時候不要以為少了一個音。<br>・「還沒吃」不要用ませんでした。朋友問<span class='gd-jp'>もう食べましたか。</span>（吃了嗎？），如果是還沒吃、等一下要吃，要回<span class='gd-jp'>いいえ、まだです。</span>（還沒）。<span class='gd-jp'>食べませんでした</span>的意思是「那時候沒吃」，事情已經過去了。<br>・<span class='gd-jp'>分かりました</span>的意思是「我懂了、好的」，講的是現在的狀態，不是過去的事。店員或同事回你這句，就是「了解」的意思。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>學到過去式，最容易把「ました」和「でした」混在一起。用「昨天的派對」當例子，一次看清楚：</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、パーティーに行きました。</span>（昨天去了派對：動詞用ました）</div><div class='gd-ex-line'>・<span class='gd-jp'>料理は和食でした。</span>（菜是日本料理：名詞用でした）</div><div class='gd-ex-line'>・<span class='gd-jp'>会場はきれいでした。</span>（會場很漂亮：な形容詞用でした）</div><div class='gd-ex-line'>・<span class='gd-jp'>とても楽しかったです。</span>（非常好玩：い形容詞用かったです）</div><div class='gd-sec'>常見的錯：<br>「学生ました」→ 要說<span class='gd-jp'>学生でした</span><br>「行きでした」→ 要說<span class='gd-jp'>行きました</span><br>「おいしいでした」→ 要說<span class='gd-jp'>おいしかったです</span></div><div class='gd-warn'>判斷小訣竅：前面是動詞，就用ました；前面是名詞或な形容詞，就用でした；前面是い形容詞，就用かったです。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>跟朋友講話時，過去式要換成不加ます的說法，叫「た形／なかった形」：<span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>行きませんでした</span> → <span class='gd-jp'>行かなかった</span></span>。</div>",
  "n5-7": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'><span class='gd-jp'>静かです</span>是「現在很安靜」。要講「<b>以前</b>很安靜」，就把<span class='gd-jp'>です</span>換成<span class='gd-jp'>でした</span>：<span class='gd-jp'>静かでした</span>。就像中文在後面補一個「了」或「那時候」，日文是把尾巴改成過去的樣子。這套變法跟名詞<b>一模一樣</b>（<span class='gd-jp'>学生でした</span>），學會一個就等於學會兩個。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>な形容詞就是放在名詞前面要加「な」的那種形容詞，像<span class='gd-jp'>静かな部屋</span>、<span class='gd-jp'>きれいな花</span>。<br>第一步：把「な」拿掉，剩下的部分叫「語幹」（就是本體）。<br><span class='gd-pair'><span class='gd-jp'>静かな</span> → な拿掉 → <span class='gd-jp'>静か</span></span><br>第二步：後面接上你要的尾巴。<br>現在：<span class='gd-jp'>静かです</span>（很安靜）／<span class='gd-jp'>静かじゃありません</span>（不安靜）<br>過去：<span class='gd-jp'>静かでした</span>（以前很安靜）／<span class='gd-jp'>静かじゃありませんでした</span>（以前不安靜）</div><div class='gd-sec'><span class='gd-tag'>過去肯定</span>那時候是那樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は暇でした。</span>（昨天很閒）</div><div class='gd-ex-line'>・<span class='gd-jp'>テストは簡単でした。</span>（考試很簡單）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものとき、野菜が嫌いでした。</span>（我小時候討厭蔬菜）</div><div class='gd-sec'><span class='gd-tag'>過去否定</span>那時候不是那樣。常跟<span class='gd-jp'>あまり</span>（不太）一起用。</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋はあまりきれいじゃありませんでした。</span>（房間不太乾淨）</div><div class='gd-ex-line'>・<span class='gd-jp'>あまり有名じゃありませんでした。</span>（那時候不太有名）</div><div class='gd-h'>其他常聽到的說法</div><div class='gd-sec'><span class='gd-tag'>比較正式</span><span class='gd-jp'>じゃ</span>換成<span class='gd-jp'>では</span>：<span class='gd-jp'>静かではありませんでした</span>，寫文章、正式場合用。<br><span class='gd-tag'>口語禮貌</span><span class='gd-jp'>静かじゃなかったです</span>，意思一樣，日常對話很常聽到。<br><span class='gd-tag'>朋友之間</span>把でした換成<span class='gd-jp'>だった</span>、否定用<span class='gd-jp'>じゃなかった</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、暇だった。</span>（昨天很閒）</div><div class='gd-ex-line'>・<span class='gd-jp'>全然大変じゃなかった。</span>（一點都不辛苦）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「な」要拿掉：說<span class='gd-jp'>静かでした</span>，不是「静かなでした」。<br>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>嫌い</span>、<span class='gd-jp'>有名</span>結尾雖然有「い」，但它們是<b>な形容詞</b>：是<span class='gd-jp'>きれいでした</span>，不是「きれいかったです」。<br>・過去否定不要自己拼成「静かじゃないでした」，正確是<span class='gd-jp'>静かじゃありませんでした</span>或<span class='gd-jp'>静かじゃなかったです</span>。<br>・<span class='gd-jp'>あまり</span>後面一定接否定：<span class='gd-jp'>あまり暇じゃありませんでした</span>，不能說「あまり暇でした」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>い形容詞的過去</b>變法完全不同，是把い換成<span class='gd-jp'>かった</span>再加です。同樣講昨天住的飯店：<br><span class='gd-jp'>ホテルは静かでした。</span>（飯店很安靜：な形容詞）<br><span class='gd-jp'>ホテルは高かったです。</span>（飯店很貴：い形容詞）<br>反過來，い形容詞也不能套でした：不能說「高いでした」。</div><div class='gd-sec'><b>になりました</b>是「<b>變成</b>～了」，講的是改變，不是單純過去的狀態：<br><span class='gd-jp'>町は静かでした。</span>（那時候這個城鎮很安靜）<br><span class='gd-jp'>町は静かになりました。</span>（這個城鎮變安靜了：以前不安靜）</div><div class='gd-warn'>判斷小訣竅：先看是不是な形容詞，是的話就「拿掉な＋でした」；中文想講「變得～了」，要用<span class='gd-jp'>になりました</span>。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著看い形容詞的過去<span class='gd-jp'>〜かったです</span>，兩種一起練，就不會再搞混。</div>",
  "n5-8": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>想說「昨天<b>很冷</b>」「拉麵<b>很好吃</b>」這種「之前覺得怎樣」，用的就是這個句型。中文只要加個「昨天」就好，日文的い形容詞（最後是「い」的形容詞，像<span class='gd-jp'>暑い</span>、<span class='gd-jp'>おいしい</span>）則是<b>形容詞本身要變身</b>：<span class='gd-pair'><span class='gd-jp'>暑いです</span> → <span class='gd-jp'>暑かったです</span></span>。</div><div class='gd-h'>怎麼變</div><div class='gd-sec'><span class='gd-tag'>過去・肯定</span>把最後的「い」拿掉，加「かったです」。<br><span class='gd-pair'><span class='gd-jp'>暑い</span> → い拿掉 → <span class='gd-jp'>暑かったです</span></span><br><span class='gd-pair'><span class='gd-jp'>おいしい</span> → <span class='gd-jp'>おいしかったです</span></span><span class='gd-pair'><span class='gd-jp'>楽しい</span> → <span class='gd-jp'>楽しかったです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は寒かったです。</span>（昨天很冷）</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはおいしかったです。</span>（這碗拉麵很好吃）</div><div class='gd-sec'><span class='gd-tag'>過去・否定</span>把「い」換成「く」，加「なかったです」。<br><span class='gd-pair'><span class='gd-jp'>難しい</span> → い換成く → <span class='gd-jp'>難しくなかったです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>テストは難しくなかったです。</span>（考試不難）</div><div class='gd-sec'>另一種說法<span class='gd-jp'>難しくありませんでした</span>意思一樣，聽起來更正式一點，兩個都對。</div><div class='gd-sec'><span class='gd-tag'>特別的一個</span><span class='gd-jp'>いい</span>（好）變化時要先變回<span class='gd-jp'>よい</span>再變，直接背：<br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よかったです</span></span>（很好）、<span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よくなかったです</span></span>（不好）</div><div class='gd-ex-line'>・<span class='gd-jp'>天気はよくなかったです。</span>（天氣不太好）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>朋友旅行回來，別人問你感想，就是這樣一問一答：</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行はどうでしたか。</span>（旅行怎麼樣？）</div><div class='gd-ex-line'>・<span class='gd-jp'>とても楽しかったです。</span>（非常好玩）</div><div class='gd-sec'>問句用<span class='gd-jp'>でした</span>，回答卻是<span class='gd-jp'>楽しかったです</span>，不要被問句帶著走，跟著說成「楽しいでした」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>不能說</b><span class='gd-jp'>暑いでした</span>。い形容詞的過去要靠「かった」，不是加でした。<br>・也不要說成<span class='gd-jp'>暑かったでした</span>。「かった」已經是過去了，後面的です只是讓句子有禮貌，不用再變成でした。<br>・「かった」中間有小っ，要停一拍：あつ<b>か</b>っ<b>た</b>，念成「あつかた」會聽起來怪怪的。<br>・<span class='gd-jp'>いい</span>不能變成「いかったです」「いくなかったです」，一律從<span class='gd-jp'>よ</span>開始變。<br>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>有名</span>最後雖然有「い」的音，卻是な形容詞，不能變成「きれかったです」，要說<span class='gd-jp'>きれいでした</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣講「上週的旅行」：<br><b>い形容詞</b>：<span class='gd-jp'>ホテルは高かったです。</span>（飯店很貴）<br><b>な形容詞</b>：<span class='gd-jp'>ホテルはきれいでした。</span>（飯店很漂亮）<br><b>名詞</b>：<span class='gd-jp'>天気は雨でした。</span>（天氣是下雨）<br>い形容詞是自己變身成「かった」，な形容詞和名詞則是把です換成でした。</div><div class='gd-warn'>判斷小訣竅：先看這個字查字典時是不是「い」結尾的い形容詞。是的話就用「〜かったです」；不是（像きれい、元気、雨）就用「〜でした」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把です拿掉就是朋友之間的說法：<span class='gd-jp'>昨日、寒かった。</span>（昨天好冷）。也可以接著學「〜くなります」，用來說「變得～」：<span class='gd-jp'>寒くなりました。</span>（變冷了）</div>",
  "n5-9": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ませんか」就是中文的<b>「要不要一起～？」</b>。字面上看起來像「不～嗎？」，但在邀約的時候，日本人是用它來客氣地問：「你願不願意～？」決定權交給對方，對方比較好拒絕，所以聽起來很有禮貌。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>邀請</span>約對方一起去哪裡、一起做什麼。</div><div class='gd-ex-line'>・<span class='gd-jp'>今度の日曜日、山登りに行きませんか。</span>（這個星期日要不要去爬山？）</div><div class='gd-ex-line'>・<span class='gd-jp'>一緒に昼ご飯を食べませんか。</span>（要不要一起吃午餐？）</div><div class='gd-sec'><span class='gd-tag'>請吃請喝、建議</span>拿東西請對方吃、喝，或建議對方做某件事，也很常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、食べませんか。</span>（要不要吃這個蛋糕？）</div><div class='gd-ex-line'>・<span class='gd-jp'>少し休みませんか。</span>（要不要休息一下？）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成ます形，再把「ます」換成「<b>ませんか</b>」就好。<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きませんか</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べませんか</span></span><br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しませんか</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来ませんか</span>（きませんか）</span><br>其實就是「ません」（不～）後面加一個問句的「か」。</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>〜でも〜ませんか</span>名詞後面加「でも」，意思是「～之類的」，讓邀請更隨意、不給壓力。</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーでも飲みませんか。</span>（要不要喝杯咖啡什麼的？）</div><div class='gd-sec'><span class='gd-tag'>怎麼回答</span>答應：<span class='gd-jp'>いいですね。</span>（好啊）、<span class='gd-jp'>ぜひ。</span>（一定要）<br>拒絕：<span class='gd-jp'>すみません、その日はちょっと…。</span>（不好意思，那天有點…）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・別被中文直覺騙了：在邀約的時候，<span class='gd-jp'>行きませんか</span>是「要不要去？」，不是「你不去嗎？」。<br>・拒絕的時候，直接說<span class='gd-jp'>いいえ、行きません。</span>（不，我不去）會很硬、很傷人。日本人習慣說「<span class='gd-jp'>ちょっと…</span>」，話講一半，對方就懂了。<br>・想說「要不要<b>我</b>幫你～」不能用ませんか。<span class='gd-jp'>持ちませんか</span>是叫對方拿；「我幫你拿吧？」要說<span class='gd-jp'>持ちましょうか</span>。<br>・跟好朋友不用這麼客氣，直接用普通形加上揚語調：<span class='gd-jp'>行かない？</span>（要不要去？）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境，看看約看電影的對話：<br><b>ませんか</b>＝還沒決定，先問對方意願：<span class='gd-jp'>一緒に映画を見ませんか。</span>（要不要一起看電影？）<br><b>ましょう</b>＝已經談好了，或是兩個人都想做，推一把：<span class='gd-jp'>いいですね。見ましょう。</span>（好啊，去看吧）<br><b>ましょうか</b>＝主動說要幫忙「我來～吧？」：<span class='gd-jp'>チケット、買いましょうか。</span>（票我來買吧？）</div><div class='gd-sec'>所以最常見的順序是：先用「ませんか」邀約，對方點頭後，再用「ましょう」一起決定。一開口就說「ましょう」，有點像沒問過對方就幫人決定了。</div><div class='gd-warn'>判斷小訣竅：還在問對方「要不要」用ませんか；已經說好「就這麼辦」用ましょう；要說「我來幫你」用ましょうか。</div>",
  "n5-10": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜なります」就是中文的<b>「變得～」「變成～」</b>。天氣從熱變冷、房間從亂變乾淨、小朋友長成大人，只要是<b>從一個狀態變到另一個狀態</b>，日文就用なります。</div><div class='gd-h'>怎麼接：先看前面是哪種詞</div><div class='gd-sec'><b>い形容詞</b>：把最後的「い」換成「く」，再加なります。<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → い換成く → <span class='gd-jp'>寒くなります</span></span><br><span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きくなります</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安くなります</span></span></div><div class='gd-sec'><b>な形容詞</b>：後面加「に」，再加なります。<br><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいになります</span></span><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気になります</span></span><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きになります</span></span></div><div class='gd-sec'><b>名詞</b>：跟な形容詞一樣，加「に」。<br><span class='gd-pair'><span class='gd-jp'>春</span> → <span class='gd-jp'>春になります</span></span><span class='gd-pair'><span class='gd-jp'>医者</span> → <span class='gd-jp'>医者になります</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>寒くなりましたね。</span>（變冷了耶）</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋がきれいになりました。</span>（房間變乾淨了）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本が好きになりました。</span>（我喜歡上日本了）</div><div class='gd-ex-line'>・<span class='gd-jp'>来月、二十歳になります。</span>（我下個月滿二十歲）</div><div class='gd-h'>なります跟なりました怎麼選</div><div class='gd-sec'>中文「變冷了」的那個「了」，日文要用<b>なりました</b>，意思是已經變了，現在就是這個樣子。<br><b>なります</b>則是「會變成～」「快要～」，講的是還沒發生、或每次都會這樣的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>もうすぐ夏になります。</span>（快要夏天了）</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲んで、よくなりました。</span>（吃了藥，好多了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>いい</span>是特例：要說<span class='gd-jp'>よくなります</span>，不能說いくなります。病好了、天氣轉好都講<span class='gd-jp'>よくなりました</span>。<br>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>きらい</span>、<span class='gd-jp'>有名</span>最後是「い」的音，但它們是な形容詞：是<span class='gd-jp'>きれいになります</span>，不是きれくなります。<br>・名詞和な形容詞的「に」不能漏掉：<span class='gd-jp'>先生になりました</span>，不是先生なりました。<br>・中文說「天氣變冷了」，很多人直接講<span class='gd-jp'>寒いです</span>。這只是「現在很冷」，沒有「變」的感覺；想強調變冷了，要說<span class='gd-jp'>寒くなりました</span>。<br>・「誰變了」前面用<span class='gd-jp'>が</span>（或<span class='gd-jp'>は</span>），不是を：<span class='gd-jp'>部屋がきれいになりました</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>下一課的「〜くします・〜にします」只差一個字，意思卻不一樣。同樣是房間變乾淨：<br><b>なります</b>＝說<b>東西變成</b>什麼樣子，重點在結果：<span class='gd-jp'>部屋がきれいになりました。</span>（房間變乾淨了）<br><b>します</b>＝說<b>某人把東西弄成</b>什麼樣子，重點在誰動手：<span class='gd-jp'>部屋をきれいにしました。</span>（我把房間打掃乾淨了）<br>再一組：<span class='gd-jp'>音が大きくなりました。</span>（聲音變大了）／<span class='gd-jp'>音を小さくしてください。</span>（請把聲音調小）</div><div class='gd-warn'>判斷小訣竅：中文是「變成～」就用<b>が＋なります</b>；中文是「把～弄成～」就用<b>を＋します</b>。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>動詞不能直接接なります。想說「變得會～了」，要用 N4 的「〜ようになります」：<span class='gd-jp'>日本語が話せるようになりました。</span>（我變得會講日文了）</div>",
  "n5-11": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜くします／〜にします」就是中文的<b>「把～弄成～」</b>。像「把聲音調小」「把房間整理乾淨」，重點是<b>有人動手</b>去改變，不是東西自己變的。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>い形容詞</b>：把最後的「い」拿掉，換成「く」，再加します。<br><span class='gd-pair'><span class='gd-jp'>短い</span> → い換成く → <span class='gd-jp'>短くします</span></span><br><span class='gd-pair'><span class='gd-jp'>小さい</span> → <span class='gd-jp'>小さくします</span></span><span class='gd-pair'><span class='gd-jp'>暖かい</span> → <span class='gd-jp'>暖かくします</span></span></div><div class='gd-sec'><b>な形容詞</b>：直接加「にします」。<br><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいにします</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かにします</span></span></div><div class='gd-sec'><b>名詞</b>：也是直接加「にします」。<br><span class='gd-pair'><span class='gd-jp'>子どもの部屋</span> → <span class='gd-jp'>子どもの部屋にします</span></span></div><div class='gd-sec'>被改變的東西後面用<b>を</b>，剛好對到中文的「把」：</div><div class='gd-ex-line'>・<span class='gd-jp'>音を小さくしてください。</span>（請把聲音調小）</div><div class='gd-ex-line'>・<span class='gd-jp'>机の上をきれいにします。</span>（把桌面整理乾淨）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋を子どもの部屋にします。</span>（要把這間房間改成小孩房）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>請別人改</span>後面接「てください」，請對方把某個東西弄成某個樣子。</div><div class='gd-ex-line'>・<span class='gd-jp'>静かにしてください。</span>（請安靜）</div><div class='gd-ex-line'>・<span class='gd-jp'>もう少し安くしてください。</span>（請再算便宜一點）</div><div class='gd-sec'><span class='gd-tag'>點餐・做選擇</span>名詞＋にします也很常拿來講「我要選～」「決定～」，在餐廳點東西特別常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>私はコーヒーにします。</span>（我要咖啡）</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行は京都にしました。</span>（旅行決定去京都了）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・い形容詞的「い」一定要先拿掉：是<span class='gd-jp'>短くします</span>，不是「短いくします」，也不是「短いにします」。<br>・<span class='gd-jp'>きれい</span>結尾雖然是い，但它是な形容詞：是<span class='gd-jp'>きれいにします</span>，不是「きれくします」。<br>・<span class='gd-jp'>いい</span>要變成<span class='gd-jp'>よく</span>：<span class='gd-jp'>この町をよくしたいです。</span>（我想讓這個城市變得更好），不是「いくします」。<br>・要改變的東西用<b>を</b>，不要寫成が。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>くなります／になります</b>＝東西<b>自己變成</b>那樣，用<b>が</b>：<br><span class='gd-jp'>部屋が暖かくなりました。</span>（房間變暖了：可能是出太陽了）<br><b>くします／にします</b>＝<b>有人動手</b>把它弄成那樣，用<b>を</b>：<br><span class='gd-jp'>部屋を暖かくしました。</span>（我把房間弄暖了：例如開了暖氣）</div><div class='gd-warn'>判斷小訣竅：中文能說「把～弄成～」就用<b>を＋します</b>；只能說「～變得～」就用<b>が＋なります</b>。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>名詞＋にします可以表示「決定選～」；如果決定的是要做某件事，以後會學到動詞＋ことにします：<span class='gd-jp'>日本へ行くことにしました。</span>（我決定去日本了）</div>",
  "n5-12": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ましょう」就是中文的<b>「我們～吧」</b>。像跟同學說「我們走吧」「我們休息一下吧」，日文就是<span class='gd-jp'>行きましょう</span>、<span class='gd-jp'>休みましょう</span>。它是禮貌的說法，對老師、同事、剛認識的人都可以用。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成「〜ます」，再把<b>ます換成ましょう</b>就好，不用管動詞是哪一類。<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きましょう</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べましょう</span></span><br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しましょう</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来ましょう</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>揪對方一起</span>大家要一起做某件事，常跟<span class='gd-jp'>一緒に</span>（一起）搭配。</div><div class='gd-ex-line'>・<span class='gd-jp'>一緒に帰りましょう。</span>（一起回家吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと休みましょう。</span>（稍微休息一下吧）</div><div class='gd-sec'><span class='gd-tag'>帶頭喊開始</span>老師上課、開會的人很常講。</div><div class='gd-ex-line'>・<span class='gd-jp'>じゃあ、始めましょう。</span>（那我們開始吧）</div><div class='gd-h'>後面加か：ましょうか</div><div class='gd-sec'><span class='gd-tag'>我來幫你吧？</span>主動說要幫對方做某件事，很貼心的說法。</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物を持ちましょうか。</span>（我幫你拿行李吧？）</div><div class='gd-sec'><span class='gd-tag'>一起商量</span>已經決定要一起做，再問細節，前面常有「何」「どこ」「何時」。</div><div class='gd-ex-line'>・<span class='gd-jp'>何時に会いましょうか。</span>（我們幾點見面呢？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・ます要<b>換掉</b>，不是加在後面：是<span class='gd-jp'>行きましょう</span>，不是「行きますましょう」。<br>・「ましょう」要念長音<b>ましょー</b>，不要念成短短的「ましょ」。<br>・它的意思裡<b>有包含你自己</b>，不是叫對方自己去做。想說「請你去～」要用「〜てください」。路上告示像<span class='gd-jp'>ゴミは持ち帰りましょう</span>（垃圾請帶回家）是比較溫和的特殊用法，自己講話時先別這樣用。<br>・第一次約對方、還不知道人家想不想去，直接說「行きましょう」有點像你已經幫他決定了，這時先用「〜ませんか」問比較有禮貌。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>用同一個「約看電影」的情境來看，這三個常常一前一後出現：<br><b>ませんか</b>＝先問對方要不要：<span class='gd-jp'>映画を見ませんか。</span>（要不要一起看電影？）<br><b>ましょう</b>＝答應了、一起往前推：<span class='gd-jp'>ええ、見ましょう。</span>（好啊，去看吧）<br><b>ましょうか</b>＝問對方意見：<span class='gd-jp'>何を見ましょうか。</span>（要看哪一部呢？）</div><div class='gd-warn'>判斷小訣竅：對方還沒答應用「ませんか」；已經說好、一起做用「ましょう」；想問對方意見，或主動說要幫忙，用「ましょうか」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>跟好朋友講不用這麼客氣，可以換成更隨興的說法：<span class='gd-pair'><span class='gd-jp'>行きましょう</span> → <span class='gd-jp'>行こう</span></span>，這個到 N4 學「意向形」就會教。</div>",
  "n5-13": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>日文同一句話有兩種講法。<b>丁寧體</b>是有「です・ます」的<b>禮貌版</b>，<b>普通體</b>是拿掉です・ます的<b>朋友版</b>。意思完全一樣，差在口氣。就像你跟主管傳訊息會寫「好的，我明天會到」，跟朋友只回「好，明天到」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>丁寧體</span>對老師、主管、店員、客人、第一次見面的人，還有比你年長又不熟的人。不知道該用哪個的時候，用丁寧體一定不會失禮。</div><div class='gd-sec'><span class='gd-tag'>普通體</span>對家人、好朋友、同學、比你小的人。寫日記、自言自語、自己做筆記也用普通體，因為沒有需要客氣的對象。</div><div class='gd-h'>同一句話，兩種講法</div><div class='gd-sec'>想問「明天要去嗎？」</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、行きますか。</span>（明天您會去嗎？：對老師）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、行きます。</span>（是的，我會去）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、行く？</span>（明天要去嗎？：對朋友）</div><div class='gd-ex-line'>・<span class='gd-jp'>うん、行く。</span>（嗯，要去）</div><div class='gd-sec'>注意朋友版的問句：<b>句尾的か不見了，改成語調往上揚</b>。回答的「はい」也換成「うん」。</div><div class='gd-h'>怎麼換：從禮貌版變朋友版</div><div class='gd-sec'><b>名詞、な形容詞</b>：把です換成だ。<br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だ</span></span><span class='gd-pair'><span class='gd-jp'>静かです</span> → <span class='gd-jp'>静かだ</span></span><br>否定、過去也跟著換：<br><span class='gd-pair'><span class='gd-jp'>学生じゃありません</span> → <span class='gd-jp'>学生じゃない</span></span><span class='gd-pair'><span class='gd-jp'>学生でした</span> → <span class='gd-jp'>学生だった</span></span></div><div class='gd-sec'><b>い形容詞</b>：直接把です拿掉就好，<b>不加だ</b>。<br><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高い</span></span><span class='gd-pair'><span class='gd-jp'>高くないです</span> → <span class='gd-jp'>高くない</span></span><span class='gd-pair'><span class='gd-jp'>高かったです</span> → <span class='gd-jp'>高かった</span></span></div><div class='gd-sec'><b>動詞</b>：把ます形換回辭書形，也就是字典裡查到的樣子。<br>第一類（五段動詞）：ます前面那個音換成同一行的「う」段音。<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → き換成く → <span class='gd-jp'>行く</span></span><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲む</span></span><br>第二類（一段動詞）：把ます拿掉，加る。<br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べる</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見る</span></span><br>第三類（する・来る）：直接背。<br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>する</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来る</span>（くる）</span><br>其他常見的：<span class='gd-pair'><span class='gd-jp'>行きません</span> → <span class='gd-jp'>行かない</span></span><span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>読んでいます</span> → <span class='gd-jp'>読んでいる</span></span><br>否定、過去的詳細變法，會在「辭書形・ない形」「た形」那幾課一步一步教。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・い形容詞不加だ：說<span class='gd-jp'>高い</span>就好，「高いだ」是錯的。<br>・朋友聊天時，單講「<span class='gd-jp'>雨だ。</span>」聽起來很硬，像在自言自語或宣布事情。平常多半會加よ、ね：<span class='gd-jp'>明日、雨だよ。</span>（明天會下雨喔）<br>・名詞、な形容詞的普通體問句要把だ拿掉：<span class='gd-jp'>学生？</span>（你是學生嗎？），不說「学生だ？」。<br>・普通體本身不是「沒禮貌」，而是「很熟」。對老師用普通體會失禮；反過來，跟好朋友一直講です・ます，對方會覺得你很見外，好像在生氣。<br>・對同一個人講話，初學者先固定用一種，不要一句ます、一句普通體，聽起來會很亂。<br>・<span class='gd-jp'>読んでいる</span>在口語裡常縮成<span class='gd-jp'>読んでる</span>，聽到時要知道是同一個意思。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>普通體不是只有聊天才用。很多文法前面固定要接普通體，就算整句話是禮貌的也一樣：<span class='gd-jp'>明日は雨だと思います。</span>（我覺得明天會下雨）<br>下一步可以看「普通形總整理」，把每種詞的現在、過去、肯定、否定一次整理好。</div>",
  "n5-14": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「不～」的禮貌說法有兩種：<span class='gd-jp'>食べません</span>和<span class='gd-jp'>食べないです</span>，意思都是「不吃」。差別有點像穿西裝跟穿襯衫：<b>ません比較正式</b>，<b>ないです比較輕鬆</b>。兩個都有禮貌，對老師、店員講都不會失禮。</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><span class='gd-jp'>ません</span>版很簡單，把ます換成ません就好：<span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みません</span></span><br><span class='gd-jp'>ないです</span>版是「ない形」（動詞的「不～」朋友版）後面再加<span class='gd-jp'>です</span>：</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，加ない，再加です。<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → む換成ま → <span class='gd-jp'>飲まないです</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かないです</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らないです</span></span><br>最後是「う」的要換成「わ」：<span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わないです</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把「る」拿掉，加ないです。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べないです</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ないです</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しないです</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ないです</span>（こないです）</span></div><div class='gd-h'>形容詞、名詞也一樣有兩種</div><div class='gd-sec'><b>い形容詞</b>：把最後的「い」換成「く」，再加ないです或ありません。<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒くないです</span></span>＝<span class='gd-jp'>寒くありません</span><br><b>な形容詞、名詞</b>：直接加じゃないです或じゃありません。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かじゃないです</span></span>＝<span class='gd-jp'>静かじゃありません</span><br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生じゃないです</span></span>＝<span class='gd-jp'>学生じゃありません</span><br>想要更正式，就把じゃ換成では：<span class='gd-jp'>学生ではありません</span>。</div><div class='gd-sec'>講過去的「沒有～」也是兩種：<span class='gd-jp'>食べませんでした</span>＝<span class='gd-jp'>食べなかったです</span>、<span class='gd-jp'>寒くありませんでした</span>＝<span class='gd-jp'>寒くなかったです</span>。</div><div class='gd-h'>什麼時候用哪個</div><div class='gd-sec'><span class='gd-tag'>正式場合</span>寫 Email、上班、面試、對長輩，用ません比較穩。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は会社に行きません。</span>（我明天不進公司）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は学生ではありません。</span>（我不是學生）</div><div class='gd-sec'><span class='gd-tag'>日常對話</span>跟店員、鄰居、不太熟的同學聊天，ないです很常聽到。形容詞的<span class='gd-jp'>くないです</span>、<span class='gd-jp'>じゃないです</span>，平常講話甚至比ありません還常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>肉はあまり食べないです。</span>（我不太吃肉）</div><div class='gd-ex-line'>・<span class='gd-jp'>この店、高くないですよ。</span>（這家店不貴喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はそんなに寒くないですね。</span>（今天沒那麼冷耶）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・兩種不能混在一起：沒有<span class='gd-jp'>食べないません</span>，也沒有<span class='gd-jp'>食べませんです</span>。<br>・<span class='gd-jp'>ある</span>的「沒有」很特別，直接變成<span class='gd-jp'>ない</span>，沒有あらない這種說法：<span class='gd-jp'>時間がありません</span>＝<span class='gd-jp'>時間がないです</span>（沒時間）。<br>・<span class='gd-jp'>いい</span>要變成<span class='gd-jp'>よくないです</span>，不是いくないです。<br>・<span class='gd-jp'>買う</span>是<span class='gd-jp'>買わない</span>，不是買あない。<br>・<span class='gd-jp'>来ない</span>念<b>こない</b>，不是きない。<br>・不是每個地方都能互換：<span class='gd-jp'>すみません</span>是固定的道歉說法，不會講成すまないです；約人的<span class='gd-jp'>一緒に行きませんか</span>（要不要一起去？）也用ません最自然、最禮貌。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>很多人學了ないです之後，講一講就把<span class='gd-jp'>です</span>弄丟了。同樣是「我今天不去」：<br>對老師：<span class='gd-jp'>今日は行きません。</span>／<span class='gd-jp'>今日は行かないです。</span>（都 OK）<br>對朋友：<span class='gd-jp'>今日は行かない。</span>（朋友版，對老師講就太隨便）</div><div class='gd-warn'>判斷小訣竅：句尾有<span class='gd-jp'>ます</span>（ません）或<span class='gd-jp'>です</span>就是禮貌版，兩個都沒有就是朋友版。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>想知道什麼時候可以拿掉です、直接講<span class='gd-jp'>行かない</span>，可以接著看「丁寧体與普通体」和「辞書形・ない形」。</div>",
  "n5-16": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「も」就是中文的<b>「也」</b>。不過位置跟中文不一樣：中文的「也」放在動詞前面（我<b>也</b>喝），日文的「も」要<b>直接貼在「也」的那個東西後面</b>（<span class='gd-jp'>私も</span>＝我也）。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>は・が・を</span>這三個要<b>拿掉，換成も</b>。<br><span class='gd-pair'><span class='gd-jp'>私は</span> → <span class='gd-jp'>私も</span></span><span class='gd-pair'><span class='gd-jp'>猫が</span> → <span class='gd-jp'>猫も</span></span><span class='gd-pair'><span class='gd-jp'>コーヒーを</span> → <span class='gd-jp'>コーヒーも</span></span></div><div class='gd-sec'><span class='gd-tag'>に・で・へ・と</span>這些要<b>留著</b>，在後面再加も。<br><span class='gd-pair'><span class='gd-jp'>大阪に</span> → <span class='gd-jp'>大阪にも</span></span><span class='gd-pair'><span class='gd-jp'>家で</span> → <span class='gd-jp'>家でも</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>大阪にも行きました。</span>（大阪也去了）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>也</span>前面講過一件事，再補一個一樣的。</div><div class='gd-ex-line'>・<span class='gd-jp'>A：私は学生です。B：私も学生です。</span>（A：我是學生。B：我也是學生）</div><div class='gd-ex-line'>・<span class='gd-jp'>A：コーヒーが好きです。B：私も。</span>（A：我喜歡咖啡。B：我也是）</div><div class='gd-sec'><span class='gd-tag'>AもBも</span>兩個都一樣，「A和B都～」。後面接否定就是「都不」。</div><div class='gd-ex-line'>・<span class='gd-jp'>パンもケーキも好きです。</span>（麵包和蛋糕都喜歡）</div><div class='gd-ex-line'>・<span class='gd-jp'>肉も魚も食べません。</span>（肉和魚都不吃）</div><div class='gd-sec'><span class='gd-tag'>疑問詞＋も＋否定</span>「什麼都不」「誰都不」「哪裡都不」，後面一定是否定。</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は何も食べませんでした。</span>（今天早上什麼都沒吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>教室には誰もいません。</span>（教室裡一個人都沒有）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末はどこにも行きませんでした。</span>（週末哪裡都沒去）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・沒有<span class='gd-jp'>はも</span>、<span class='gd-jp'>がも</span>、<span class='gd-jp'>をも</span>這種說法，は・が・を要直接換成も。<br>・も貼在誰後面，「也」就是指誰，意思會差很多：<br><span class='gd-jp'>私もコーヒーを飲みます。</span>（別人喝咖啡，<b>我也</b>喝）<br><span class='gd-jp'>私はコーヒーも飲みます。</span>（我喝茶，<b>咖啡也</b>喝）<br>中文都講「我也喝咖啡」，日文要先想清楚「也」的是人還是咖啡。<br>・<span class='gd-jp'>何も</span>、<span class='gd-jp'>誰も</span>後面接否定。想說「什麼都喜歡」不能講何も好きです，要用別的說法（像<span class='gd-jp'>何でも好きです</span>，之後會學）。<br>・「哪裡都沒去」要講<span class='gd-jp'>どこにも</span>，に不要漏掉。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>AとB</b>＝單純列出兩樣東西：<span class='gd-jp'>パンとケーキが好きです。</span>（我喜歡麵包和蛋糕）<br><b>AもBも</b>＝強調「兩樣<b>都</b>」：<span class='gd-jp'>パンもケーキも好きです。</span>（麵包也好、蛋糕也好，都喜歡）<br>接法也不一樣：と只放在中間一次，も是<b>每一個後面都要放</b>。</div><div class='gd-warn'>判斷小訣竅：只是列出東西用と，想強調「兩個都～」就用〜も〜も。</div>",
  "n5-17": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「の」就是中文的<b>「的」</b>。它把兩個名詞黏在一起，前面那個用來說明後面那個：<span class='gd-jp'>私の本</span>＝我的書。順序跟中文一樣，前面講「誰的、哪裡的」，後面才是東西本身。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞A＋の＋名詞B＝「A的B」。B 才是主角，A 是在補充說明「是哪一個B」。<br><span class='gd-pair'><span class='gd-jp'>弟</span>＋<span class='gd-jp'>車</span> → <span class='gd-jp'>弟の車</span></span>（弟弟的車）<br><span class='gd-pair'><span class='gd-jp'>数学</span>＋<span class='gd-jp'>教科書</span> → <span class='gd-jp'>数学の教科書</span></span>（數學課本）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>誰的東西</span>說東西是誰的。</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の本です。</span>（這是我的書）</div><div class='gd-sec'><span class='gd-tag'>屬於哪裡</span>說一個人是哪間公司、哪間學校的，自我介紹、打電話很常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>さくら銀行の山田です。</span>（我是櫻花銀行的山田）</div><div class='gd-sec'><span class='gd-tag'>什麼內容</span>說這個東西是關於什麼的。</div><div class='gd-ex-line'>・<span class='gd-jp'>数学の教科書を忘れました。</span>（我忘了帶數學課本）</div><div class='gd-sec'><span class='gd-tag'>哪裡的</span>說東西或人來自哪裡、在哪裡。</div><div class='gd-ex-line'>・<span class='gd-jp'>台湾のお茶はおいしいです。</span>（台灣的茶很好喝）</div><div class='gd-h'>後面的名詞可以省略</div><div class='gd-sec'>大家都知道在講什麼東西的時候，B 可以不說，只講「A の」。<span class='gd-jp'>私の</span>就是「我的」。</div><div class='gd-ex-line'>・<span class='gd-jp'>「これは誰の傘ですか。」「私のです。」</span>（「這是誰的傘？」「是我的。」）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>中文常把「的」省掉，日文不能省。</b>中文說「我媽媽」「我朋友」「日文老師」都沒有「的」，日文要說<span class='gd-jp'>私の母</span>、<span class='gd-jp'>私の友達</span>、<span class='gd-jp'>日本語の先生</span>。說成「私母」「日本語先生」就錯了。<br>・<b>好幾個「的」連在一起也照樣接。</b>「我朋友的車」中文只講一個「的」，日文兩個都要：<span class='gd-jp'>私の友達の車</span>。<br>・<b>「這本書」是<span class='gd-jp'>この本</span>，不是「これの本」。</b><span class='gd-jp'>この</span>本身就是「這個」的意思，後面直接接名詞就好，不用再加の。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>中文不管前面是什麼，都說「的」：「日本的車」「新的車」「漂亮的車」。日文要看前面是哪一種詞：<br><b>名詞</b>（人、東西、地方）要加の：<span class='gd-jp'>日本の車</span>（日本的車）<br><b>い形容詞</b>（像<span class='gd-jp'>新しい</span>、<span class='gd-jp'>おいしい</span>）直接接，不加の：<span class='gd-jp'>新しい車</span>（新的車），不是「新しいの車」<br><b>な形容詞</b>（像<span class='gd-jp'>きれい</span>、<span class='gd-jp'>静か</span>）要加な：<span class='gd-jp'>きれいな車</span>（漂亮的車），不是「きれいの車」</div><div class='gd-warn'>判斷小訣竅：前面是「誰、什麼東西、哪裡」這種名詞，才用の；前面是在形容「怎麼樣」的形容詞，就不要用の。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「の」還有另一個身分：接在動詞後面，把一個動作變成「這件事」，像<span class='gd-jp'>本を読むのが好きです。</span>（我喜歡看書）。這個之後在「形式名詞の」會學到，跟這裡的「的」是不同用法。</div>",
  "n5-18": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「か」就是日文的<b>「嗎？」</b>。句子最後面加一個か，就從「直述句」變成「問句」：<span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生ですか</span></span>，「是學生」變成「是學生嗎？」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>禮貌說法很簡單：句子最後是<b>です</b>或<b>ます</b>，後面直接加か就好，前面什麼都不用改。<br><span class='gd-pair'><span class='gd-jp'>日本人です</span> → <span class='gd-jp'>日本人ですか</span></span><br><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高いですか</span></span><br><span class='gd-pair'><span class='gd-jp'>静かです</span> → <span class='gd-jp'>静かですか</span></span><br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きますか</span></span><br><span class='gd-pair'><span class='gd-jp'>食べました</span> → <span class='gd-jp'>食べましたか</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>問是不是</span>對方回答「はい」或「いいえ」就可以的問題。</div><div class='gd-ex-line'>・<span class='gd-jp'>これは日本の本ですか。</span>（這是日本的書嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメン、おいしいですか。</span>（這碗拉麵好吃嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、学校へ行きますか。</span>（你明天要去學校嗎？）</div><div class='gd-sec'>回答的時候，名詞句常用<span class='gd-jp'>はい、そうです。</span>（對，是的）或<span class='gd-jp'>いいえ、違います。</span>（不，不是）；動詞、形容詞就把原本的詞再說一次：<span class='gd-jp'>はい、行きます。</span>（會，我會去）／<span class='gd-jp'>いいえ、行きません。</span>（不，我不去）。</div><div class='gd-sec'><span class='gd-tag'>配疑問詞</span>句子裡有「什麼、哪裡、什麼時候」這種詞，一樣要加か。</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、駅はどこですか。</span>（不好意思，車站在哪裡？）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、何を食べましたか。</span>（你昨天吃了什麼？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>有疑問詞也要加か</b>：中文說「那是什麼？」，不會說「那是什麼嗎？」，所以很多人會漏掉か。但日文禮貌說法還是要加か，要說<span class='gd-jp'>何ですか</span>，不能只說「何です」。<br>・<b>語調要上揚</b>：「ですか」的か要往上提。像<span class='gd-jp'>そうですか</span>，往上揚是「是這樣嗎？」，往下降變成「喔～這樣啊」，表示你聽懂了，意思不一樣。<br>・<b>跟朋友講話通常不加か</b>：直接用沒有です、ます的說法，句尾語調往上揚就是問句：<span class='gd-jp'>明日、行く？</span>（明天要去嗎？）、<span class='gd-jp'>これ、おいしい？</span>（這個好吃嗎？）。普通說法直接加か（像「行くか」）聽起來很衝、很粗，初學者先不要用。<br>・名詞問句跟朋友講是<span class='gd-jp'>学生？</span>，不要說成「学生だか」，這樣不是問句。<br>・<b>標點</b>：課本和正式文章裡，か後面習慣打「。」，因為か已經表示在問了；LINE 訊息、漫畫裡常看到「？」，兩種都會看到。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ますか</b>＝單純問對方會不會、要不要做：<br><div class='gd-ex-line'>・<span class='gd-jp'>明日、パーティーに行きますか。</span>（你明天會去派對嗎？）</div><b>ませんか</b>＝<b>邀請對方</b>一起做：<br><div class='gd-ex-line'>・<span class='gd-jp'>明日、一緒にパーティーに行きませんか。</span>（明天要不要一起去派對？）</div>兩句只差一點點，但第一句是在打聽對方的計畫，第二句是在揪人。</div><div class='gd-warn'>判斷小訣竅：只是想知道對方要不要做，用「ますか」；想約對方一起做，用「ませんか」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把「何、どこ、いつ、だれ」這些疑問詞學起來，就能問各種問題；再學「〜ませんか」，就可以開口約人了。</div>",
  "n5-19": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「に」放在時間後面，意思就像中文的「<b>在</b>7點」「<b>在</b>3月」，把事情釘在某一個時間點上。中文常常把「在」省掉，直接說「我7點起床」，但日文只要是<b>有數字的時間</b>，就一定要加に：<span class='gd-jp'>7時に起きます。</span>（我7點起床）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>時間的詞後面直接加に就好。<br><span class='gd-pair'><span class='gd-jp'>7時</span> → <span class='gd-jp'>7時に</span></span><span class='gd-pair'><span class='gd-jp'>3月</span> → <span class='gd-jp'>3月に</span></span><span class='gd-pair'><span class='gd-jp'>2025年</span> → <span class='gd-jp'>2025年に</span></span></div><div class='gd-h'>什麼時候加、什麼時候不加</div><div class='gd-sec'>這是這個文法真正要記的地方。時間詞分成三種：</div><div class='gd-sec'><span class='gd-tag'>一定要加</span>有數字的時間：幾點、幾分、幾月、幾年、幾號。</div><div class='gd-ex-line'>・<span class='gd-jp'>朝6時に散歩します。</span>（早上6點去散步）</div><div class='gd-ex-line'>・<span class='gd-jp'>3月に日本へ行きます。</span>（3月要去日本）</div><div class='gd-sec'>沒有數字、但是很明確的特定日子也要加，像<span class='gd-jp'>誕生日</span>、<span class='gd-jp'>クリスマス</span>、<span class='gd-jp'>夏休み</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>誕生日にケーキを食べます。</span>（生日那天吃蛋糕）</div><div class='gd-sec'><span class='gd-tag'>加不加都可以</span>星期幾。加了比較清楚，初學者<b>先加上去最保險</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>金曜日に歓迎会があります。</span>（星期五有歡迎會）</div><div class='gd-ex-line'>・<span class='gd-jp'>日曜日に休みます。</span>（星期日休息）</div><div class='gd-sec'><span class='gd-tag'>不能加</span>①以「現在」為基準的時間：<span class='gd-jp'>今日</span>、<span class='gd-jp'>明日</span>、<span class='gd-jp'>昨日</span>、<span class='gd-jp'>今週</span>、<span class='gd-jp'>来年</span>、<span class='gd-jp'>今</span>。<br>判斷方法：這種詞今天講跟下禮拜講，指的日子會不一樣，它是跟著「現在」在跑的，就不加に。<br>②表示「每～」的時間：<span class='gd-jp'>毎日</span>、<span class='gd-jp'>毎朝</span>、<span class='gd-jp'>毎週</span>。這種詞講的是固定反覆、多久一次，不是某一個時間點，所以也不加に。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、映画を見ます。</span>（明天要看電影）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝コーヒーを飲みます。</span>（每天早上都喝咖啡）</div><div class='gd-sec'>兩種時間放在一起也很常見：</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝7時に起きます。</span>（每天早上7點起床）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日の3時に会いましょう。</span>（明天3點見吧）</div><div class='gd-warn'>一句話裡同時有兩種時間，就各自照規則來：以現在為基準的時間（<span class='gd-jp'>明日</span>…）、「每～」的時間（<span class='gd-jp'>毎朝</span>…）不加，有數字的時間（<span class='gd-jp'>7時</span>、<span class='gd-jp'>3時</span>…）要加。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・照中文直覺把に漏掉：說成「7時起きます」是錯的，要說<span class='gd-jp'>7時に起きます</span>。<br>・反過來加太多：「明日に行きます」「毎日に勉強します」都不對，<span class='gd-jp'>明日</span>、<span class='gd-jp'>毎日</span>後面直接接下去。<br>・問時間時，<span class='gd-jp'>何時</span>要加に，<span class='gd-jp'>いつ</span>不加：<span class='gd-jp'>何時に起きますか。</span>（你幾點起床？）、<span class='gd-jp'>いつ日本へ行きますか。</span>（你什麼時候去日本？）<br>・「時」跟「時間」不一樣：<span class='gd-jp'>2時に勉強します</span>是「兩點讀書」；<span class='gd-jp'>2時間勉強します</span>是「讀兩個小時」。講<b>多久</b>的時間長度不加に。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「7點」，後面放的助詞不同，意思就不同：<br><b>に</b>＝就在那個時間點：<span class='gd-jp'>7時に起きます。</span>（7點起床）<br><b>から</b>＝從那個時間開始，後面持續下去：<span class='gd-jp'>7時から勉強します。</span>（從7點開始讀書）<br><b>まで</b>＝一直到那個時間為止：<span class='gd-jp'>7時まで寝ます。</span>（睡到7點）</div><div class='gd-warn'>判斷小訣竅：中文是「在幾點」用に，「從幾點」用から，「到幾點」用まで。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>に的工作不只標時間，它也能標東西在哪裡（n5-33 存在位置）：<span class='gd-jp'>部屋に猫がいます。</span>（房間裡有貓）。同一個に，看前面是時間還是地點來判斷就好。</div>",
  "n5-20": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「へ」就是中文的<b>「往～」「朝～」</b>。放在地點後面，告訴對方你要往哪裡移動：<span class='gd-jp'>日本へ行きます</span>就是「往日本去」，也就是「去日本」。它雖然寫成へ，但當助詞時要<b>念「e」</b>，不念「he」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>地點＋へ＋移動的動詞（<span class='gd-jp'>行きます</span>、<span class='gd-jp'>来ます</span>、<span class='gd-jp'>帰ります</span>這類）。<br><span class='gd-pair'><span class='gd-jp'>学校</span> → <span class='gd-jp'>学校へ行きます</span></span>（去學校）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、京都へ行きます。</span>（明天去京都）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは去年日本へ来ました。</span>（田中先生去年來日本）</div><div class='gd-ex-line'>・<span class='gd-jp'>6時にうちへ帰ります。</span>（六點回家）</div><div class='gd-sec'>問別人要去哪裡，就把地點換成<span class='gd-jp'>どこ</span>：</div><div class='gd-ex-line'>・<span class='gd-jp'>週末、どこへ行きますか。</span>（週末要去哪裡？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・念法：助詞的へ念「e」，跟<span class='gd-jp'>は</span>當助詞念「wa」是同一種情況。但<b>寫的時候一定寫へ</b>，不能寫成え。<br>・後面要接「移動」的動詞。中文說「去圖書館讀書」很順，但「在圖書館讀書」這個動作的地點要用<span class='gd-jp'>で</span>：<span class='gd-jp'>図書館で勉強します</span>，不能說<span class='gd-jp'>図書館へ勉強します</span>。<br>・時間不能用へ。要說「明天去」是<span class='gd-jp'>明日、行きます</span>，不是明日へ。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><span class='gd-tag'>へ和に</span>講「去、來、回」哪裡的時候，兩個大多可以互換，意思一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>東京へ行きます。</span>（去東京）</div><div class='gd-ex-line'>・<span class='gd-jp'>東京に行きます。</span>（去東京）</div><div class='gd-sec'>硬要說差別：<b>へ</b>的感覺是「朝那個方向」，<b>に</b>的感覺是「到那個點」。日常對話裡に用得比較多。如果重點是「抵達」，例如<span class='gd-jp'>着きます</span>（到達），一般都用に：</div><div class='gd-ex-line'>・<span class='gd-jp'>駅に着きました。</span>（到車站了）</div><div class='gd-sec'><span class='gd-tag'>へ和で</span>へ是「往哪裡去」，で是「在哪裡做事」。</div><div class='gd-ex-line'>・<span class='gd-jp'>図書館へ行きます。</span>（去圖書館）</div><div class='gd-ex-line'>・<span class='gd-jp'>図書館で勉強します。</span>（在圖書館讀書）</div><div class='gd-warn'>判斷小訣竅：後面是「行く、来る、帰る」這種移動的動詞，用へ或に都可以；「在哪裡做事」用で。時間不能用へ：7時、月曜日這種具體時間點要加に，明日、来週這類時間詞則不加助詞。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>搭配<span class='gd-jp'>から</span>（從）和<span class='gd-jp'>まで</span>（到），就能把移動的起點、終點講完整；再學「で（交通工具）」，就能說<span class='gd-jp'>電車で会社へ行きます</span>（搭電車去公司）。</div>",
  "n5-21": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「で」放在交通工具後面，就是中文的<b>「搭～」「坐～」「騎～」「開～」</b>。中文要看交通工具換動詞，日文不管坐什麼，全部都是「交通工具＋で」，後面接<span class='gd-jp'>行きます</span>、<span class='gd-jp'>来ます</span>、<span class='gd-jp'>帰ります</span>就好。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>交通工具＋で＋行きます／来ます／帰ります。前面直接放名詞，不用變化。</div><div class='gd-ex-line'>・<span class='gd-jp'>電車で会社に行きます。</span>（我搭電車去公司）</div><div class='gd-ex-line'>・<span class='gd-jp'>自転車で学校へ行きます。</span>（我騎腳踏車去學校）</div><div class='gd-ex-line'>・<span class='gd-jp'>バスで帰ります。</span>（我坐公車回家）</div><div class='gd-ex-line'>・<span class='gd-jp'>飛行機で来ました。</span>（我是坐飛機來的）</div><div class='gd-sec'>你會發現：中文的「搭、騎、坐」，日文全部是同一個「で」。<span class='gd-jp'>車で行きます</span>也一樣，可能是自己開車，也可能是坐別人的車，日文不特別分。</div><div class='gd-h'>想問「怎麼來的？」</div><div class='gd-sec'>把交通工具換成「何」就好：</div><div class='gd-ex-line'>・<span class='gd-jp'>何で来ましたか。</span>（你是怎麼來的？）</div><div class='gd-ex-line'>・<span class='gd-jp'>タクシーで来ました。</span>（坐計程車來的）</div><div class='gd-sec'>這裡的「何で」念<b>なにで</b>。念成なんで，很容易被聽成「為什麼來？」。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>走路不用で</b>。不要說「足で行きます」，要說<span class='gd-jp'>歩いて行きます</span>（走路去）。這句先整句背起來就好。<br>・「坐上公車」這個動作要用「に」：<span class='gd-jp'>バスに乗ります</span>（搭上公車）。很多人會講成「バスで乗ります」，這是錯的。<br>・順序可以換：<span class='gd-jp'>電車で東京へ行きます</span>跟<span class='gd-jp'>東京へ電車で行きます</span>都對，只要「で」緊跟在交通工具後面就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>で（交通工具）</b>＝用什麼「移動」：<span class='gd-jp'>バスで駅へ行きます。</span>（坐公車去車站）<br><b>に＋乗ります</b>＝「上」哪台車：<span class='gd-jp'>駅でバスに乗ります。</span>（在車站搭上公車）<br><b>で（動作地點）</b>＝在哪裡做事：上面那句的<span class='gd-jp'>駅で</span>就是「在車站」，前面放的是地點，不是交通工具。</div><div class='gd-warn'>判斷小訣竅：後面是「去、來、回」，交通工具後面就用で；後面是「乗ります」，就用に；前面是地點而不是交通工具，那個で是「在～」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>這個「で」其實是「用～」的意思，不只交通工具，用筷子、用日文也都是它：<span class='gd-jp'>はしで食べます。</span>（用筷子吃）。這就是下一張「助詞で（手段・工具）」。</div>",
  "n5-22": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「と」就是中文的<b>「跟～」「和～」</b>。想說「我跟朋友看電影」，就在「朋友」後面加と：<span class='gd-jp'>友達と映画を見ます</span>。と前面放的是<b>跟你一起做這件事的人</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>很簡單：<b>人＋と＋要做的事</b>。想強調「一起」，可以在と後面加<span class='gd-jp'>一緒に</span>（一起），意思一樣，只是「一起」的感覺更明顯。<br><span class='gd-pair'><span class='gd-jp'>友達と</span> → <span class='gd-jp'>友達と一緒に</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>友達と映画を見ました。</span>（我跟朋友看了電影）</div><div class='gd-ex-line'>・<span class='gd-jp'>母と一緒に料理を作ります。</span>（我跟媽媽一起做菜）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝、犬と散歩します。</span>（我每天早上跟狗散步）</div><div class='gd-sec'>問「跟誰」就用<span class='gd-jp'>誰と</span>，回答可以直接說「人＋とです」。</div><div class='gd-ex-line'>・<span class='gd-jp'>誰と行きますか。</span>（你跟誰去？）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達とです。</span>（跟朋友）</div><div class='gd-sec'>如果要把「我」也講出來，主角用は，一起的人用と：<span class='gd-jp'>私は友達と京都へ行きます。</span>（我跟朋友去京都）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・自己一個人做，要說<span class='gd-jp'>一人で</span>，不是一人と。講人數或一整群人也用で：<span class='gd-jp'>二人で</span>、<span class='gd-jp'>家族で</span>、<span class='gd-jp'>みんなで</span>。<br>・一緒に是可加可不加的配角，光有と就已經是「跟誰一起」了。反過來，只說一緒に、不說跟誰，是因為對象大家都知道：<span class='gd-jp'>一緒に帰りましょう。</span>（一起回去吧）<br>・<span class='gd-jp'>結婚する</span>這種一定要兩個人才能做的事，也用と，而且通常不加一緒に：<span class='gd-jp'>田中さんと結婚しました。</span>（我跟田中先生結婚了）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>と還有另一個用法：把兩樣東西連起來，像中文的「A和B」（並列）。看這兩句：<br><span class='gd-jp'>母とケーキを食べました。</span>（我跟媽媽吃了蛋糕）→ 媽媽是<b>一起吃的人</b><br><span class='gd-jp'>パンとケーキを食べました。</span>（我吃了麵包和蛋糕）→ 麵包和蛋糕都是<b>被吃的東西</b></div><div class='gd-warn'>判斷小訣竅：と前面是「一起動手的人」，就是這裡學的「跟誰一起」；と前後是兩樣並排的東西，就是「A和B」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>搭配「〜ませんか」就能約人：<span class='gd-jp'>週末、私と映画を見ませんか。</span>（週末要不要跟我去看電影？）</div>",
  "n5-23": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「を」是貼在名詞後面的小標籤，意思是<b>「這個東西就是動作要處理的對象」</b>。中文說「吃麵包」，看順序就知道吃的是麵包；日文動詞放在句子最後，所以要靠「を」標出<b>吃的是什麼、看的是什麼</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋を＋動詞。日文的順序是「東西先講，動作最後」：<br><span class='gd-pair'><span class='gd-jp'>パン</span> → <span class='gd-jp'>パンを食べます</span></span>（吃麵包）</div><div class='gd-ex-line'>・<span class='gd-jp'>水を飲みます。</span>（喝水）</div><div class='gd-ex-line'>・<span class='gd-jp'>映画を見ます。</span>（看電影）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日日本語を勉強します。</span>（我每天學日文）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>動作的對象</span>最主要、最常用的就是這個：吃什麼、喝什麼、買什麼、做什麼。初學先把這個練熟。</div><div class='gd-ex-line'>・<span class='gd-jp'>コンビニで傘を買いました。</span>（在便利商店買了傘）</div><div class='gd-sec'><span class='gd-tag'>走過的地方</span>搭配「走、散步、過（橋、馬路）」這類移動的動詞，表示<b>從那個地方走過、穿過</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>公園を散歩します。</span>（在公園散步）</div><div class='gd-ex-line'>・<span class='gd-jp'>橋を渡ります。</span>（過橋）</div><div class='gd-sec'><span class='gd-tag'>離開的地方</span>搭配「出、下（車）」這類動詞，表示<b>從那裡離開</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>8時に家を出ます。</span>（8 點出門）</div><div class='gd-ex-line'>・<span class='gd-jp'>次の駅で電車を降ります。</span>（在下一站下電車）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「を」念 <b>o</b>，跟「お」一樣，不要念成 wo。不過電腦、手機打字要打 <b>wo</b> 才打得出來。<br>・念起來一樣，寫的時候還是要寫「を」，不能寫成「お」。<br>・「喜歡、懂、想要」不用を：課本標準說法是<span class='gd-jp'>猫が好きです</span>、<span class='gd-jp'>英語がわかります</span>，不要說成猫を好きです。<br>・中文說「見朋友」「搭電車」，日文要用に：<span class='gd-jp'>友達に会います</span>、<span class='gd-jp'>電車に乗ります</span>。但「下車」是<span class='gd-jp'>電車を降ります</span>，上車用に、下車用を，要分開記。<br>・<b>同一個動詞不要帶兩個を</b>：<span class='gd-jp'>日本語を勉強をします</span>不自然（勉強します只能有一個を），要說<span class='gd-jp'>日本語を勉強します</span>或<span class='gd-jp'>日本語の勉強をします</span>。不同動詞各帶一個を沒問題，例如<span class='gd-jp'>本を読んで、ご飯を食べます。</span>（看書，然後吃飯）<br>・朋友聊天常把を省掉：<span class='gd-jp'>ご飯、食べた？</span>（吃飯了沒？）。這是口語，自己寫句子時還是先把を放好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>を vs が</b>：同樣講日文，動作用を，感覺、能力用が。<br><span class='gd-jp'>日本語を勉強します。</span>（學日文：動作）<br><span class='gd-jp'>日本語が好きです。</span>（喜歡日文：感覺）<br><span class='gd-jp'>日本語がわかります。</span>（懂日文：能力）</div><div class='gd-sec'><b>を vs で</b>：同樣在橋那邊，「過橋」用を，「在橋上做別的事」用で。<br><span class='gd-jp'>橋を渡ります。</span>（過橋：從橋上走過去）<br><span class='gd-jp'>橋で写真を撮ります。</span>（在橋上拍照：橋只是做事的地點，拍的東西「写真」才用を）</div><div class='gd-warn'>判斷小訣竅：問自己「動作是不是直接做在這個東西上」，是就用を；「喜歡、懂、想要」用が；只是交代「在哪裡做事」用で。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>有些動詞成對出現，一個用を、一個用が：<span class='gd-jp'>ドアを開けます</span>（我把門打開）、<span class='gd-jp'>ドアが開きます</span>（門開了）。這就是「自動詞・他動詞」，學會を之後接著看會很順。</div>",
  "n5-24": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「で」就是中文的<b>「在（哪裡）做（什麼）」</b>。把地點想成一個舞台，「で」是在告訴對方：這個動作是在這個舞台上演的。<br><span class='gd-jp'>カフェで仕事をします。</span>（在咖啡店工作）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>地點後面直接加「で」，再接你做的動作。<br><span class='gd-pair'><span class='gd-jp'>図書館</span> → <span class='gd-jp'>図書館で勉強します</span></span>（在圖書館唸書）<br><span class='gd-pair'><span class='gd-jp'>家</span> → <span class='gd-jp'>家で晩ご飯を食べます</span></span>（在家吃晚餐）<br>地點不管是大是小都可以：國家、城市、店、房間、甚至「這裡」。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>在某處做事</span>吃、喝、買、看、唸書、工作、玩、等人……只要是「做」的動作，地點後面就用で。</div><div class='gd-ex-line'>・<span class='gd-jp'>駅で友達を待ちます。</span>（在車站等朋友）</div><div class='gd-ex-line'>・<span class='gd-jp'>デパートで靴を買いました。</span>（在百貨公司買了鞋子）</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真を撮ってもいいですか。</span>（可以在這裡拍照嗎？）</div><div class='gd-sec'><span class='gd-tag'>問在哪裡做</span>用「どこで」來問。</div><div class='gd-ex-line'>・<span class='gd-jp'>そのかばん、どこで買いましたか。</span>（那個包包在哪裡買的？）</div><div class='gd-ex-line'>・<span class='gd-jp'>どこで昼ご飯を食べますか。</span>（要在哪裡吃午餐？）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>「で」和「に」：同一個地點，看後面的動詞</b><br>中文都說「在圖書館」，日文卻要看你是「待在那裡」還是「在那裡做事」。<br><span class='gd-jp'>図書館にいます。</span>（我在圖書館：人在那裡，用に）<br><span class='gd-jp'>図書館で勉強します。</span>（我在圖書館唸書：在那裡做事，用で）<br>後面是<b>いる、ある</b>（有、在）這種「存在」的詞，就用に；後面是<b>做某個動作</b>，就用で。</div><div class='gd-sec'><b>「で」和「へ」：要去那裡，還是已經在那裡</b><br><span class='gd-jp'>図書館へ行きます。</span>（去圖書館：往那邊移動，用へ）<br><span class='gd-jp'>図書館で本を読みます。</span>（在圖書館看書：到了那裡做事，用で）</div><div class='gd-sec'><b>另一個「で」：交通工具、工具</b><br>「で」還有別的工作，前面放的是東西，不是地點。<br><span class='gd-jp'>バスで行きます。</span>（搭公車去：交通工具）<br><span class='gd-jp'>公園で遊びます。</span>（在公園玩：地點）<br>看前面那個字是「地方」還是「工具」就分得出來。</div><div class='gd-warn'>判斷小訣竅：<b>人或東西「在」那裡 → に；往那裡「去」→ へ；在那裡「做」事 → で。</b></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・中文的「在」不能一律翻成で。「我在家」是<span class='gd-jp'>家にいます</span>，不是家でいます。<br>・「住在東京」要用に：<span class='gd-jp'>東京に住んでいます</span>，不是東京で住んでいます。「住」是待在那裡，不是在那裡做一件事。這是台灣人最常錯的一個。<br>・「工作」用で沒問題：<span class='gd-jp'>銀行で働いています</span>（在銀行工作）。不要因為住む用に，就連働く也改成に。<br>・行く、来る、帰る這種「移動」的動詞，目的地不用で：要說<span class='gd-jp'>日本へ行きます</span>，不能說日本で行きます。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把「で」跟「を」放在一起，就能講完整的一句話：<b>地點＋で＋東西＋を＋動作</b>。<br><span class='gd-jp'>コンビニでお茶を買いました。</span>（在便利商店買了茶）<br>接著再去看「に」（存在位置），兩個一起比較，に和で就不會再搞混。</div>",
  "n5-25": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「から」就是中文的<b>「從」</b>。從幾點、從哪裡、從誰那裡，都用它。常跟「まで」（到）一起出現，<span class='gd-jp'>AからBまで</span>就是「從 A 到 B」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>很簡單：<b>名詞後面直接加から</b>，不用變化。<br><span class='gd-pair'><span class='gd-jp'>9時</span> → <span class='gd-jp'>9時から</span></span>（從9點）<span class='gd-pair'><span class='gd-jp'>駅</span> → <span class='gd-jp'>駅から</span></span>（從車站）<span class='gd-pair'><span class='gd-jp'>友達</span> → <span class='gd-jp'>友達から</span></span>（從朋友那裡）</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>時間的起點</span>從某個時間開始。</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は9時からです。</span>（工作9點開始）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日から夏休みです。</span>（明天開始放暑假）</div><div class='gd-sec'><span class='gd-tag'>地點的起點</span>從某個地方出發、從哪裡來。</div><div class='gd-ex-line'>・<span class='gd-jp'>どこから来ましたか。</span>（你從哪裡來的？）</div><div class='gd-ex-line'>・<span class='gd-jp'>台湾から来ました。</span>（我從台灣來的）</div><div class='gd-sec'><span class='gd-tag'>從誰那裡</span>東西、消息是誰給的。</div><div class='gd-ex-line'>・<span class='gd-jp'>友達から電話がありました。</span>（朋友打電話來）</div><div class='gd-h'>最常聽到的樣子：AからBまで</div><div class='gd-sec'>講範圍時，「から」和「まで」常常一起用，時間、地點都可以。</div><div class='gd-ex-line'>・<span class='gd-jp'>月曜日から金曜日まで働きます。</span>（星期一到星期五上班）</div><div class='gd-ex-line'>・<span class='gd-jp'>家から駅まで歩きます。</span>（從家裡走到車站）</div><div class='gd-ex-line'>・<span class='gd-jp'>何時から何時までですか。</span>（從幾點到幾點？）</div><div class='gd-sec'>最後這句問店家營業時間、活動時間超好用，去日本一定用得到。不需要範圍的時候，單獨用「から」也完全沒問題。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>位置跟中文相反</b>：中文「從」放在前面，日文「から」放在名詞<b>後面</b>。「從車站」是<span class='gd-jp'>駅から</span>，不是から駅。<br>・中文說「明天<b>開始</b>放假」，日文<span class='gd-jp'>明日から夏休みです</span>就夠了，「から」本身已經有「從～開始」的意思，不用硬把「開始」翻出來。<br>・講「幾點做某件事」要用「に」，不是「から」，下面會細講。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>① 起點的から vs 時間點的に</b><br><span class='gd-jp'>9時に起きます。</span>（9點起床：就那一個時間點）<br><span class='gd-jp'>9時から勉強します。</span>（從9點開始念書：之後持續一段時間）<br>「起床」是一下就完成的動作，說成9時から起きます會很怪。</div><div class='gd-warn'>判斷小訣竅：只講「在幾點做」用に；要講「從那時開始，之後一直持續」用から。</div><div class='gd-sec'><b>② 起點的から vs 理由的から</b><br>N5 還會學到另一個「から」，意思是「因為」，兩個長得一模一樣，要看<b>前面接什麼</b>。<br>起點：<b>名詞直接加から</b>，例如<span class='gd-jp'>駅から</span>（從車站）。<br>理由：前面是<b>一整句話</b>。名詞要先加だ或です（<span class='gd-jp'>雨だから</span>、<span class='gd-jp'>雨ですから</span>），或是動詞、い形容詞的普通形或禮貌形（<span class='gd-jp'>行くから</span>、<span class='gd-jp'>行きますから</span>、<span class='gd-jp'>高いから</span>、<span class='gd-jp'>高いですから</span>）。<br>同一個「明天考試」比比看：<br><span class='gd-jp'>明日からテストです。</span>（明天開始考試）<br><span class='gd-jp'>明日テストだから、勉強します。</span>（因為明天要考試，所以要念書）</div><div class='gd-warn'>判斷小訣竅：から前面只有時間、地點、人這種名詞，就是「從」；前面是だ／です，或動詞、形容詞的普通形、禮貌形（<span class='gd-jp'>行くから</span>、<span class='gd-jp'>行きますから</span>、<span class='gd-jp'>高いから</span>），就是「因為」。（「動詞て形＋から」是另一個文法，意思是「做完～之後」，不要混在一起。）</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>搭檔「まで」（到）可以一起學。之後還會學到「動詞て形＋から」＝做完～之後再～：<span class='gd-jp'>ご飯を食べてから、出かけます。</span>（吃完飯再出門）</div>",
  "n5-26": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「まで」就是中文的<b>「到～」「到～為止」</b>，標出<b>終點</b>在哪裡。可以是時間的終點（到 5 點），也可以是地點的終點（到車站）。它很常跟「から」（從～）湊成一對：<span class='gd-jp'>から</span>是起點，<span class='gd-jp'>まで</span>是終點。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>時間</span>某件事一直做，做到那個時間點才停。</div><div class='gd-ex-line'>・<span class='gd-jp'>5時まで待ちます。</span>（我等到 5 點）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は11時まで寝ました。</span>（昨天我睡到 11 點）</div><div class='gd-sec'><span class='gd-tag'>地點</span>移動到哪裡為止。</div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで歩きます。</span>（我走路到車站）</div><div class='gd-ex-line'>・<span class='gd-jp'>空港までバスで行きます。</span>（我搭公車到機場）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>很簡單，名詞後面直接加まで，不用變化。<br><span class='gd-pair'><span class='gd-jp'>6時</span> → <span class='gd-jp'>6時まで</span></span><span class='gd-pair'><span class='gd-jp'>金曜日</span> → <span class='gd-jp'>金曜日まで</span></span><span class='gd-pair'><span class='gd-jp'>東京</span> → <span class='gd-jp'>東京まで</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>から～まで</span>從哪裡到哪裡、從幾點到幾點，一次講清楚範圍。</div><div class='gd-ex-line'>・<span class='gd-jp'>9時から5時まで働きます。</span>（我從 9 點工作到 5 點）</div><div class='gd-ex-line'>・<span class='gd-jp'>東京から大阪まで新幹線で行きます。</span>（從東京搭新幹線到大阪）</div><div class='gd-sec'><span class='gd-tag'>～までです</span>後面直接接です，講營業時間、上課時間超常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は夜10時までです。</span>（這家店開到晚上 10 點）</div><div class='gd-sec'><span class='gd-tag'>いつまで・どこまで</span>問「到什麼時候」「到哪裡」。</div><div class='gd-ex-line'>・<span class='gd-jp'>いつまで日本にいますか。</span>（你會在日本待到什麼時候？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・まで的意思是動作<b>一直持續</b>到那個點。中文說「5 點到」（5 點抵達），不能直接翻成「5時まで来てください」，那樣意思會變得很怪。要說「5 點來」，用<span class='gd-jp'>5時に来てください</span>。<br>・「金曜日まで休みです」通常<b>包含</b>星期五，星期五也放假。<br>・まで只標終點，不會自己帶出「去」的意思，後面還是要有動詞，像<span class='gd-jp'>駅まで歩きます</span>、<span class='gd-jp'>駅まで行きます</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>に（時間點）</b>＝在那個時間點<b>發生一次</b>：<span class='gd-jp'>11時に寝ました。</span>（我 11 點睡覺的）<br><b>まで</b>＝<b>一直做到</b>那個時間：<span class='gd-jp'>11時まで寝ました。</span>（我一路睡到 11 點）<br>只差一個字，一個是 11 點上床，一個是 11 點才起床。</div><div class='gd-sec'><b>までに</b>＝在那個時間<b>之前完成</b>（期限）：<span class='gd-jp'>5時までに帰ります。</span>（我 5 點以前會回來）<br><b>まで</b>＝一直持續到那個時間：<span class='gd-jp'>5時まで待ちます。</span>（我一直等到 5 點）</div><div class='gd-warn'>判斷小訣竅：「一直～到幾點」用まで；「幾點以前要做完」用までに；「幾點做那件事」用に。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>まで後面加に，變成<span class='gd-jp'>までに</span>，用來講期限：<span class='gd-jp'>金曜日までに出してください。</span>（請在星期五以前交出來）</div>",
  "n5-27": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這個「と」就是中文的<b>「和」「跟」</b>，把東西一個一個列出來。而且它有個意思：<b>我列的就是全部，沒有別的了</b>。像你跟朋友說「我買了麵包和牛奶」，就是只買這兩樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>パンと牛乳を買いました。</span>（我買了麵包和牛奶）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋と＋名詞，<b>兩邊都要是名詞</b>。列完之後，最後再接這一組在句子裡需要的助詞（を、が、は…）。<br><span class='gd-pair'><span class='gd-jp'>鍵</span>＋<span class='gd-jp'>財布</span> → <span class='gd-jp'>鍵と財布を持ってきました</span></span>（帶了鑰匙和錢包來）<br>三個以上就每個中間都放と：</div><div class='gd-ex-line'>・<span class='gd-jp'>月曜日と水曜日と金曜日に授業があります。</span>（星期一、三、五有課）</div><div class='gd-ex-line'>・<span class='gd-jp'>父と母は台北に住んでいます。</span>（我爸媽住在台北）</div><div class='gd-sec'>點餐也超常用：</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーとケーキをお願いします。</span>（麻煩給我咖啡和蛋糕）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>助詞只放在最後一個名詞後面</b>。是<span class='gd-jp'>鍵と財布を持ってきました</span>，不要說成「鍵を財布を持ってきました」或「鍵をと財布を持ってきました」。<br>・と<b>只能連名詞</b>。中文的「和」很萬用，「便宜和好吃」「吃飯和看電視」都講得通，但日文不能用と把形容詞或動作連起來，那要用之後會學的て形。<br>・と是「就這些」。如果還有其他東西沒講完，要改用や。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><span class='gd-tag'>と vs や</span>同樣在講包包裡帶了什麼：<br><span class='gd-jp'>鍵と財布を持ってきました。</span>（帶了鑰匙和錢包：就這兩樣）<br><span class='gd-jp'>鍵や財布を持ってきました。</span>（帶了鑰匙、錢包之類的：還有別的）</div><div class='gd-sec'><span class='gd-tag'>和 vs 一起</span>と還有另一個用法，是「跟誰一起」做某件事。<br><b>並列的と</b>：把A和B綁成一組，後面再接は、が、を等助詞，一起當句子的一部分。<br><span class='gd-jp'>友達と私は映画を見ました。</span>（朋友和我看了電影：「友達と私」是一組，後面接は）<br><b>一起的と</b>：「人＋と」，說明是跟誰做後面的動作。後面就算出現名詞，那個名詞也是另一個成分，不跟と前面的人綁在一起。<br><span class='gd-jp'>友達と映画を見ました。</span>（我跟朋友看了電影：「友達と」說明跟誰看，「映画を」是看的東西，不是「朋友和電影」）<br>想強調「一起」時，常會說成<span class='gd-jp'>友達と一緒に映画を見ました</span>。</div><div class='gd-warn'>判斷小訣竅：把と前面那個名詞單獨放回句子試試看。<span class='gd-jp'>鍵を持ってきました</span>、<span class='gd-jp'>財布を持ってきました</span>都說得通，就是「A和B」；「友達と映画を見ました」換成「友達を見ました」意思就不對了，那這個と就是「跟誰一起」。</div>",
  "n5-28": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「や」就像中文的<b>「像是A啦、B啦（之類的）」</b>。東西很多，你只挑幾個代表講出來，同時讓對方知道<b>還有別的，沒有全部列完</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名詞＋<b>や</b>＋名詞，最後常加「<b>など</b>」（等等）。後面該接的助詞（を、が、に…）照樣接在最後面。<br><span class='gd-pair'><span class='gd-jp'>牛乳</span>＋<span class='gd-jp'>卵</span> → <span class='gd-jp'>牛乳や卵</span></span><br><span class='gd-pair'><span class='gd-jp'>牛乳や卵</span> → <span class='gd-jp'>牛乳や卵など</span></span>（加了など，「還有別的」的感覺更明顯）</div><div class='gd-ex-line'>・<span class='gd-jp'>冷蔵庫に牛乳や卵があります。</span>（冰箱裡有牛奶、雞蛋之類的）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は掃除や洗濯をします。</span>（週末會打掃、洗衣服之類的）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本で寿司やラーメンなどを食べました。</span>（在日本吃了壽司、拉麵等等）</div><div class='gd-sec'>要舉三個也可以，中間每個都放や：</div><div class='gd-ex-line'>・<span class='gd-jp'>机の上にペンやノートや辞書などがあります。</span>（桌上有筆、筆記本、字典等等）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>「と」也是把名詞連起來，但意思差很多。同樣在講包包裡有什麼：<br><b>と</b>＝<b>全部就這些</b>：<span class='gd-jp'>かばんに財布と鍵があります。</span>（包包裡有錢包和鑰匙，就這兩樣）<br><b>や</b>＝<b>舉例，還有別的</b>：<span class='gd-jp'>かばんに財布や鍵があります。</span>（包包裡有錢包、鑰匙之類的，還有其他東西）</div><div class='gd-warn'>判斷小訣竅：講得出「就這些」用と；只是舉幾個例子、後面心裡還有「…之類的」就用や。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・や<b>只能連名詞</b>。動作要舉例，不能說「食べるや飲む」，要用「〜たり〜たりします」：<span class='gd-jp'>食べたり飲んだりします</span>（吃吃喝喝之類的）。<br>・最後一個名詞後面<b>不要再放や</b>。不說「ペンやノートや」就結束，想表示「等等」就加など：<span class='gd-jp'>ペンやノートなど</span>。<br>・中文的「和」也有「跟誰一起」的意思，但や沒有。「我和朋友去」是<span class='gd-jp'>友達と行きます</span>，不能說友達や行きます。<br>・不用等到東西很多才用や，只舉兩個也完全OK，重點是「沒有全部列完」的感覺。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>動作的舉例版是「〜たり〜たりします」：<span class='gd-jp'>休みの日は映画を見たり、買い物をしたりします。</span>（放假時會看看電影、逛逛街之類的）</div>",
  "n5-29": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這個「で」就是中文的<b>「用～」</b>。用筷子吃、用日文講、用電話聯絡，日文都是在那個東西後面加「で」：<span class='gd-jp'>はしで食べます</span>（用筷子吃）。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>工具</span>手上拿來做事的東西。</div><div class='gd-ex-line'>・<span class='gd-jp'>はしで食べます。</span>（用筷子吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>ボールペンで書いてください。</span>（請用原子筆寫）</div><div class='gd-sec'><span class='gd-tag'>語言</span>用哪一種語言講、寫。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語で話しましょう。</span>（我們用日文聊吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>これは英語で何と言いますか。</span>（這個用英文怎麼說？）</div><div class='gd-sec'><span class='gd-tag'>方法</span>透過什麼方式做到。</div><div class='gd-ex-line'>・<span class='gd-jp'>母と電話で話しました。</span>（我跟媽媽講了電話）</div><div class='gd-ex-line'>・<span class='gd-jp'>ネットでチケットを買いました。</span>（我在網路上買了票）</div><div class='gd-sec'><span class='gd-tag'>材料</span>用什麼做出來的，而且做好後看得出原來的材料。</div><div class='gd-ex-line'>・<span class='gd-jp'>紙で花を作りました。</span>（我用紙做了花）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>很簡單，<b>名詞後面直接加「で」</b>，不用變化。<br><span class='gd-pair'><span class='gd-jp'>スプーン</span> → <span class='gd-jp'>スプーンで</span></span><span class='gd-pair'><span class='gd-jp'>英語</span> → <span class='gd-jp'>英語で</span></span><br>要做的事照常用「を」接在動詞前面：<span class='gd-jp'>スプーンでスープを飲みます。</span>（用湯匙喝湯）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・中文的「用」放在前面，日文的「で」放在<b>後面</b>。中文說「用筷子」，日文說「はしで」，順序剛好反過來。<br>・初學者常把工具當成受詞，講成「はしを食べます」，意思會變成「吃筷子」。工具後面要用<b>で</b>。<br>・問「用什麼」要說<span class='gd-jp'>何で</span>，念<b>なにで</b>：<span class='gd-jp'>何で書きますか。</span>（要用什麼寫？）念成なんで，口語裡常常會被聽成「為什麼」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>で（地點）</b>：在哪裡做：<span class='gd-jp'>教室で書きます。</span>（在教室寫）<br><b>で（工具）</b>：用什麼做：<span class='gd-jp'>ペンで書きます。</span>（用筆寫）<br>兩個可以放在同一句：<span class='gd-jp'>教室でペンで書きます。</span>（在教室用筆寫）<br>另外，<span class='gd-jp'>バスで行きます</span>（搭公車去）的「で」，其實也是「用什麼方法」的意思，跟這張卡是同一個概念。</div><div class='gd-warn'>判斷小訣竅：前面是「一個地方」，就是「在～」；前面是「拿來用的東西、語言、方法」，就是「用～」。</div><div class='gd-sec'><b>日本語を話します</b>：會講日文，日文是你會的東西。<br><b>日本語で話します</b>：用日文來講，日文是溝通工具。</div><div class='gd-ex-line'>・<span class='gd-jp'>私は日本語を話します。</span>（我會講日文）</div><div class='gd-ex-line'>・<span class='gd-jp'>店員と日本語で話しました。</span>（我跟店員用日文講了話）</div><div class='gd-warn'>判斷小訣竅：要說「我會講什麼語言」用を；要說「這次用什麼語言溝通」用で。</div>",
  "n5-30": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「に」接在<b>人</b>後面，表示這個動作是<b>對誰</b>做的。中文會說「打電話<b>給</b>朋友」「<b>問</b>老師」「<b>跟</b>媽媽說」，每次用的字都不一樣；日文比較單純，通通在那個人後面加一個「に」就好。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>基本順序是：<b>人＋に</b>　<b>東西＋を</b>　<b>動詞</b>。<br>先說對誰，再說什麼東西，最後放動作：<br><span class='gd-jp'>母に</span>（給媽媽）＋<span class='gd-jp'>花を</span>（花）＋<span class='gd-jp'>あげます</span>（送）→ <span class='gd-jp'>母に花をあげます。</span><br>如果動作沒有「東西」，就直接「人＋に＋動詞」：<span class='gd-jp'>友達に電話します。</span>（打電話給朋友）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>把東西給某人</span>送、借出去、給人看。</div><div class='gd-ex-line'>・<span class='gd-jp'>母に花をあげます。</span>（送花給媽媽）</div><div class='gd-ex-line'>・<span class='gd-jp'>妹に本を貸しました。</span>（我把書借給妹妹了）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達に写真を見せます。</span>（給朋友看照片）</div><div class='gd-sec'><span class='gd-tag'>對某人說、聯絡</span>打電話、寫信、問問題。</div><div class='gd-ex-line'>・<span class='gd-jp'>友達に電話します。</span>（打電話給朋友）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生に聞きます。</span>（問老師）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんに手紙を書きました。</span>（我寫了信給田中先生）</div><div class='gd-sec'><span class='gd-tag'>教某人</span></div><div class='gd-ex-line'>・<span class='gd-jp'>弟に英語を教えます。</span>（教弟弟英文）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・中文說「問老師」「見朋友」，人直接放在動詞後面，很多人就順手用を。<span class='gd-jp'>先生を聞きます</span>是錯的，要說<span class='gd-jp'>先生に聞きます</span>；<span class='gd-jp'>友達を会います</span>也是錯的，要說<span class='gd-jp'>友達に会います</span>。不過也有動詞是用を接人，例如<span class='gd-jp'>友達を待ちます</span>（等朋友），所以每個動詞要跟著例句一起記，不要只靠中文去猜。<br>・に後面的人<b>不一定是收到東西的人</b>。遇到「借（進來）」「學」這類動作，に的那個人反而是東西的來源：<span class='gd-jp'>友達に本を借りました。</span>（我跟朋友借了書）、<span class='gd-jp'>先生に日本語を習います。</span>（跟老師學日文）。<br>・「に」還有其他用法，像時間（<span class='gd-jp'>7時に</span>）、地點（<span class='gd-jp'>東京に</span>）。看前面接的是什麼：前面是<b>人</b>，通常就是這張卡的用法。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>中文的「跟」很容易讓人在<b>に</b>和<b>と</b>之間搞混：<br><span class='gd-jp'>友達に話します。</span>（把事情告訴朋友：我講、他聽，是<b>單向</b>的）<br><span class='gd-jp'>友達と話します。</span>（跟朋友聊天：兩個人你一句我一句，是<b>一起</b>做）<br>同樣是「跟朋友說話」，用に就是我對他說，用と就是我們一起聊。</div><div class='gd-warn'>判斷小訣竅：中文的「跟」如果能換成「和～一起」，就用と；只能換成「給」「對」「向」，就用に。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「誰給誰東西」的說法，例如<span class='gd-jp'>あげます</span>、<span class='gd-jp'>もらいます</span>、<span class='gd-jp'>くれます</span>，會一直用到這個「に」，可以接著學授受動詞。</div>",
  "n5-32": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文說「我喜歡狗」「我懂韓文」，狗、韓文都是被喜歡、被懂的東西，你的直覺會想用<span class='gd-jp'>を</span>。但日文裡，<b>喜歡、討厭、很會、不太會、懂、會、想要</b>這幾個詞，前面的東西要用<b>が</b>。把它當成固定搭配記起來就對了。</div><div class='gd-h'>哪些詞前面要用が</div><div class='gd-sec'><span class='gd-tag'>喜歡・討厭</span><span class='gd-jp'>好き</span>（喜歡）、<span class='gd-jp'>嫌い</span>（討厭）</div><div class='gd-ex-line'>・<span class='gd-jp'>チョコレートが好きです。</span>（我喜歡巧克力）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は野菜が嫌いです。</span>（我討厭蔬菜）</div><div class='gd-sec'><span class='gd-tag'>很會・不太會</span><span class='gd-jp'>上手</span>（很會、很厲害）、<span class='gd-jp'>下手</span>（不太會）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは歌が上手です。</span>（田中先生很會唱歌）</div><div class='gd-sec'><span class='gd-tag'>懂・會</span><span class='gd-jp'>わかります</span>（懂）、<span class='gd-jp'>できます</span>（會）</div><div class='gd-ex-line'>・<span class='gd-jp'>韓国語がわかります。</span>（我懂韓文）</div><div class='gd-ex-line'>・<span class='gd-jp'>テニスができます。</span>（我會打網球）</div><div class='gd-sec'><span class='gd-tag'>想要</span><span class='gd-jp'>ほしい</span>（想要）</div><div class='gd-ex-line'>・<span class='gd-jp'>新しいかばんがほしいです。</span>（我想要新包包）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>東西（名詞）＋が＋上面那些詞。<br>要說「是誰」喜歡，就在最前面放「人＋は」：<span class='gd-jp'>私は犬が好きです。</span>（我喜歡狗）<br>這句裡<span class='gd-jp'>は</span>是在說「現在講的是我」，<span class='gd-jp'>が</span>是在說「喜歡的是狗」，兩個各管各的。<br>想問對方喜歡什麼，把東西換成<span class='gd-jp'>何</span>就好：<span class='gd-jp'>何が好きですか。</span>（你喜歡什麼？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・不要照中文直覺用を：說<span class='gd-jp'>韓国語がわかります</span>，不是韓国語をわかります。喜歡也一樣，先記<span class='gd-jp'>犬が好きです</span>就對了。<br>・<span class='gd-jp'>好き</span>、<span class='gd-jp'>嫌い</span>、<span class='gd-jp'>上手</span>、<span class='gd-jp'>下手</span>不是動詞，後面接<span class='gd-jp'>です</span>，不能加ます。<br>・說「不喜歡」的時候，日本人很常把が換成は：<span class='gd-jp'>魚は好きじゃありません。</span>（魚我就不喜歡）。有「別的還好，這個不行」的感覺，很自然。<br>・<span class='gd-jp'>上手</span>是拿來誇別人的。自己說「我很會～」聽起來像在自誇，講自己時日本人通常不這樣用。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>最容易跟<b>を</b>（受詞）搞混。看同一個東西放在不同的詞前面：<br><span class='gd-jp'>日本語を勉強します。</span>（我讀日文）：「讀」是你去做的動作，用を。<br><span class='gd-jp'>日本語がわかります。</span>（我懂日文）：「懂」是你本身的能力，用が。<br><span class='gd-jp'>料理を作ります。</span>（我做菜）：動作，用を。<br><span class='gd-jp'>料理が上手です。</span>（很會做菜）：本事，用が。</div><div class='gd-warn'>判斷小訣竅：是「去做」的動作（吃、讀、做、買），用を；是心裡的感覺或身上的本事（喜歡、討厭、很會、懂、會、想要），用が。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'><span class='gd-jp'>ほしい</span>這個用法，可以接著看「<span class='gd-jp'>〜が欲しいです・〜たいです</span>」，學怎麼說「想要～、想做～」。</div>",
  "n5-33": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這個「に」就是中文的<b>「在」</b>，用來告訴對方人或東西<b>在哪裡</b>。中文說「冰箱裡有牛奶」，日文就在「冰箱裡」後面加上に，最後用あります或います收尾。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>句型：<b>地點＋に＋人／東西＋が＋あります／います</b></div><div class='gd-ex-line'>・<span class='gd-jp'>冷蔵庫に牛乳があります。</span>（冰箱裡有牛奶）</div><div class='gd-ex-line'>・<span class='gd-jp'>教室に先生がいます。</span>（教室裡有老師）</div><div class='gd-sec'><b>用あります還是います？</b>看那個東西會不會自己動：人、動物用<span class='gd-jp'>います</span>；東西、植物用<span class='gd-jp'>あります</span>。</div><div class='gd-h'>位置怎麼講</div><div class='gd-sec'>中文說「桌上」「箱子裡」「車站前面」，日文習慣用「の」把位置接上去，後面再加に：<br><span class='gd-jp'>机の上に</span>（桌上）、<span class='gd-jp'>箱の中に</span>（箱子裡）、<span class='gd-jp'>駅の前に</span>（車站前）、<span class='gd-jp'>机の下に</span>（桌子底下）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の前にコンビニがあります。</span>（車站前面有便利商店）</div><div class='gd-h'>最常聽到的兩種樣子</div><div class='gd-sec'><span class='gd-tag'>那裡有什麼</span>地點放前面，要講的東西用が。</div><div class='gd-ex-line'>・<span class='gd-jp'>公園に子供がいます。</span>（公園裡有小孩）</div><div class='gd-sec'><span class='gd-tag'>它在哪裡</span>想講「某個東西在哪」，把東西放前面用は，に一樣跟著地點。</div><div class='gd-ex-line'>・<span class='gd-jp'>猫は机の下にいます。</span>（貓在桌子底下）</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこにありますか。</span>（廁所在哪裡？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・這裡的あります／います，是指人或東西「存在」在那裡。如果あります是活動、事件「舉行」（例：<span class='gd-jp'>パーティーがあります</span>），地點要用で：<span class='gd-jp'>明日、学校で試験があります。</span>（明天學校有考試）<br>・中文都講「在」，但「在公園玩」是做動作，要用で：<span class='gd-jp'>公園で遊びます</span>，不是公園に遊びます。<br>・人和動物不能用あります：是<span class='gd-jp'>先生がいます</span>，不是先生があります。<br>・「住在哪裡」的地點也用に：<span class='gd-jp'>姉は大阪に住んでいます。</span>（我姊姊住在大阪）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>最容易混的是<b>で（動作地點）</b>。同樣是公園，看句子在講什麼：<br><span class='gd-jp'>公園に子供がいます。</span>（公園裡有小孩：只說小孩在那裡）<br><span class='gd-jp'>公園で子供が遊んでいます。</span>（小孩在公園玩：在那裡做動作）<br><span class='gd-jp'>公園でお祭りがあります。</span>（公園有祭典：活動在那裡舉行）</div><div class='gd-warn'>判斷小訣竅：先看句子最後。表示人或東西「在那裡」的あります／います（還有住んでいます）用に；吃、玩、買、工作這種動作，或是活動「舉行」的あります（例：<span class='gd-jp'>ホテルでパーティーがあります</span>），用で。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「存在表現」會教「什麼都沒有」「一個人都沒有」的說法：<span class='gd-jp'>部屋に誰もいません。</span>（房間裡一個人都沒有）</div>",
  "n5-35": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>把「が」放在一句話的最後面，意思就是中文的<b>「……，但是……」</b>。先講一件事，再接一件跟預期不一樣的事。像「這家店很貴，但是很好吃」，日文就是<span class='gd-jp'>この店は高いですが、おいしいです。</span></div><div class='gd-h'>怎麼接</div><div class='gd-sec'>前面那句話要<b>整句講完</b>，在 N5 通常是用「です」或「ます」結尾。講完再加が，打個逗號，接後面那句。<br><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高いですが、</span></span><br><span class='gd-pair'><span class='gd-jp'>雨です</span> → <span class='gd-jp'>雨ですが、</span></span><br><span class='gd-pair'><span class='gd-jp'>行きたいです</span> → <span class='gd-jp'>行きたいですが、</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強しました</span> → <span class='gd-jp'>勉強しましたが、</span></span><br>前半句用「です・ます」，後半句也用「です・ます」，整句的禮貌程度要一致。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>轉折</span>前後兩件事的方向相反，或結果跟你預期的不一樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語は難しいですが、おもしろいです。</span>（日文很難，但是很有趣）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は雨でしたが、出かけました。</span>（昨天下雨，但我還是出門了）</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲みましたが、まだ頭が痛いです。</span>（藥吃了，但頭還是很痛）</div><div class='gd-sec'><span class='gd-tag'>開場白</span>要請別人幫忙、問問題之前，先說一句「すみませんが」或「失礼ですが」墊一下。這時候的が沒有「但是」的意思，只是讓語氣比較客氣，很像中文的「不好意思，請問……」。</div><div class='gd-ex-line'>・<span class='gd-jp'>すみませんが、駅はどこですか。</span>（不好意思，請問車站在哪裡？）</div><div class='gd-ex-line'>・<span class='gd-jp'>失礼ですが、お名前は？</span>（不好意思，請問您貴姓？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・中文的「雖然」放在句子<b>最前面</b>，日文的が卻是放在<b>前半句的最後面</b>。不要想在句首找一個字來對應「雖然」。<br>・同一句話裡可能會出現兩個が：<span class='gd-jp'>雨が降っていますが、行きます。</span>（雖然在下雨，但我還是要去）。第一個が接在名詞「雨」後面，是標出主語的が；第二個接在整句「降っています」後面，才是「但是」。判斷方法很簡單：看が前面是<b>一個名詞</b>，還是<b>一句已經講完的話</b>。<br>・用了が就不用再加でも，說<span class='gd-jp'>高いですが、おいしいです。</span>就夠了。<br>・跟朋友聊天時說「高いが、おいしい」，也就是不加です・ます直接接が，聽起來會很硬，像在寫文章。朋友之間用けど比較自然。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「很貴，但是很好吃」，有三種常見說法：<br><b>が</b>：<span class='gd-jp'>高いですが、おいしいです。</span>比較正式，跟客人、長輩說話，或是寫信都適合。<br><b>けど</b>：<span class='gd-jp'>高いけど、おいしい。</span>這是口語說法，日常聊天最常聽到。加上です也可以：<span class='gd-jp'>高いですけど、おいしいです。</span><br><b>でも</b>：<span class='gd-jp'>高いです。でも、おいしいです。</span>前一句先用句號結束，下一句開頭才說でも。</div><div class='gd-warn'>判斷小訣竅：接在句子後面、想講得正式一點，用が；跟朋友聊天，用けど；前一句已經講完了、要在新的一句開頭轉折，用でも。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>接著看「けど」，它的意思跟が一樣，但更口語，跟朋友講話時幾乎都用它。</div>",
  "n5-36": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「けど」差不多就是中文的「～，不過…」。它有兩種用法：一是<b>前後意思相反</b>，像「雖然小，但是好用」；二是<b>先起個頭</b>，把話題帶出來，像中文「不好意思，我想問一下……」。日本人平常講話一直在用。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>前後相反</span>前面講一件事，後面講跟它相反、出乎意料的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>小さいけど、使いやすいです。</span>（雖然小，但是很好用）</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いけど、おいしいです。</span>（這家店很便宜，不過很好吃）</div><div class='gd-sec'><span class='gd-tag'>先起個頭</span>先交代一下背景，再提問題、邀約或拜託。這時候けど<b>沒有「但是」的意思</b>，比較像「是這樣的……」。後面那句也常常乾脆不講，讓對方自己接。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日映画を見に行くけど、一緒に行かない？</span>（我明天要去看電影，要不要一起去？）</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、駅に行きたいんですけど…</span>（不好意思，我想去車站……）</div><div class='gd-ex-line'>・<span class='gd-jp'>もしもし、田中ですけど…</span>（喂，我是田中……）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>けど是黏在<b>前一句的最後面</b>，前面要先是一句完整的話。<br><b>跟朋友講（不用です・ます）</b>：<br>動詞、い形容詞直接加：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くけど</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いけど</span></span><br>名詞、な形容詞要先加「だ」：<span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生だけど</span></span><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいだけど</span></span></div><div class='gd-sec'><b>有禮貌的講法</b>：前面用です・ます，再加けど。<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きますけど</span></span><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高いですけど</span></span><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生ですけど</span></span><br>「<span class='gd-jp'>〜たいんですけど…</span>」整句當固定說法背起來，問路、拜託、到櫃台開口都用得到。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞忘了加だ：<span class='gd-jp'>学生けど</span>×，要說<span class='gd-jp'>学生だけど</span>；<span class='gd-jp'>静かけど</span>×，要說<span class='gd-jp'>静かだけど</span>。反過來，い形容詞<b>不要</b>加だ：<span class='gd-jp'>高いだけど</span>×，直接說<span class='gd-jp'>高いけど</span>。<br>・中文的「但是」放在後一句的開頭，日文的けど是黏在<b>前一句的尾巴</b>。想在第二句開頭說「可是」，要用<span class='gd-jp'>でも</span>（下面會比較）。<br>・句子停在「〜けど…」不是話沒講完，而是日本人<b>客氣、不把話說死</b>的講法。翻成中文不要硬翻「但是」。<br>・けど是講話用的，聊天、跟店員說話都很自然；寫報告、正式場合換成「が」比較穩。<br>・<span class='gd-jp'>けれど</span>、<span class='gd-jp'>けれども</span>意思一樣，越長越正式。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一件事：衣服很貴，還是買了。<br><b>けど</b>＝平常講話的口氣：<span class='gd-jp'>高いけど、買いました。</span><br><b>が</b>＝比較正式，書面或正式場合：<span class='gd-jp'>高いですが、買いました。</span><br><b>でも</b>＝先把第一句講完，第二句開頭才說「不過」：<span class='gd-jp'>高いです。でも、買いました。</span></div><div class='gd-sec'>先起個頭的用法也一樣，對上司、長輩想更客氣，就把けど換成が：<span class='gd-jp'>ちょっと聞きたいんですが…</span>（我想請教一下……）</div><div class='gd-warn'>判斷小訣竅：平常講話用けど；正式、寫文章用が；想拆成兩句、第二句開頭說「可是」就用でも。</div>",
  "n5-37": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這個「に」用來說明<b>你去／來／回去是為了做什麼</b>。中文說「去買東西」「來玩」，日文是把要做的事放前面，後面接「に行きます」「に来ます」：<span class='gd-jp'>買いに行きます</span>（去買）、<span class='gd-jp'>遊びに来ます</span>（來玩）。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>動詞</span>先把動詞變成ます形，把「ます」拿掉，再加「に」。<br><span class='gd-pair'><span class='gd-jp'>買います</span> → 把ます拿掉 → <span class='gd-jp'>買いに行きます</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べに行きます</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見に行きます</span></span><span class='gd-pair'><span class='gd-jp'>会います</span> → <span class='gd-jp'>会いに行きます</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>お土産を買いに行きます。</span>（去買伴手禮）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末、友達に会いに行きます。</span>（週末要去見朋友）</div><div class='gd-ex-line'>・<span class='gd-jp'>昼ごはんを食べに家へ帰ります。</span>（回家吃午餐）</div><div class='gd-ex-line'>・<span class='gd-jp'>書類を届けに来ました。</span>（我是來送文件的）</div><div class='gd-sec'><span class='gd-tag'>名詞</span>像<span class='gd-jp'>買い物</span>、<span class='gd-jp'>散歩</span>、<span class='gd-jp'>旅行</span>、<span class='gd-jp'>食事</span>這種本身就是「一個動作」的名詞，可以直接加「に」。</div><div class='gd-ex-line'>・<span class='gd-jp'>デパートへ買い物に行きます。</span>（去百貨公司買東西）</div><div class='gd-ex-line'>・<span class='gd-jp'>公園へ散歩に行きませんか。</span>（要不要去公園散步？）</div><div class='gd-h'>一句話裡同時有地點和目的</div><div class='gd-sec'>順序通常是：<b>地點＋へ　→　目的＋に　→　行きます</b>。<br><span class='gd-jp'>図書館へ本を借りに行きます。</span>（去圖書館借書）<br>地點後面用「へ」，就不會跟目的的「に」連著出現兩個に，聽起來比較清楚。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・前面要用<b>ます形拿掉ます</b>，不能直接放辭書形：是<span class='gd-jp'>買いに行きます</span>，不是「買うに行きます」。<br>・後面只能接<b>移動的動詞</b>，最常見的是<span class='gd-jp'>行きます</span>、<span class='gd-jp'>来ます</span>、<span class='gd-jp'>帰ります</span>。像「為了學日文而看書」這種跟移動無關的句子，不能用這個に。<br>・中文是「去＋買」，日文是「買い＋に行く」，<b>順序跟中文相反</b>，別講成「行きに買います」。<br>・原本動詞前面的「を」照樣留著：<span class='gd-jp'>お土産を買いに行きます</span>。<br>・<span class='gd-jp'>遊びに来てください。</span>（來玩喔）是日本人很常講的邀請，可以整句記起來。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「に行きます」，<b>に前面放什麼</b>決定意思：<br><b>地點＋に</b>＝去<b>哪裡</b>：<span class='gd-jp'>デパートに行きます。</span>（去百貨公司）<br><b>動作＋に</b>＝去<b>做什麼</b>：<span class='gd-jp'>買い物に行きます。</span>（去買東西）<br>兩個合起來：<span class='gd-jp'>デパートへ買い物に行きます。</span>（去百貨公司買東西）</div><div class='gd-warn'>判斷小訣竅：に前面是「地方」就是去哪裡；に前面是「拿掉ます的動詞」或「買い物、散歩」這類動作，就是去幹嘛。</div>",
  "n5-39": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「ね」很像中文的<b>「～呢」「～對吧」</b>：講的是<b>對方也知道、也感受得到</b>的事，找他一起有同感，或跟他確認一下。<br>「よ」很像中文的<b>「～喔」</b>：講的是<b>對方還不知道</b>的事，你要告訴他、提醒他。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>ね：一起有同感</span>兩個人都看到、吃到、感覺到同一件事，說出來找共鳴。</div><div class='gd-ex-line'>・<span class='gd-jp'>いい天気ですね。</span>（天氣真好呢）</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしいですね。</span>（這個蛋糕好好吃呢）</div><div class='gd-sec'><span class='gd-tag'>ね：確認一下</span>你大概知道，但想跟對方確認沒記錯。店員跟你確認點餐也是這樣用。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休みですね。</span>（明天放假，對吧？）</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒー二つですね。</span>（兩杯咖啡，對嗎？）</div><div class='gd-sec'><span class='gd-tag'>よ：告訴對方</span>你知道、對方不知道的事，像推薦、分享消息。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店、安いですよ。</span>（這家店很便宜喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>この番組、面白いですよ。</span>（這個節目很有趣喔）</div><div class='gd-sec'><span class='gd-tag'>よ：提醒</span>對方沒注意到的事，叫他注意。</div><div class='gd-ex-line'>・<span class='gd-jp'>もう始まりますよ。</span>（已經要開始了喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>電車が来ましたよ。</span>（電車來了喔）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>很簡單，句子講完，<b>直接放在最後面</b>就好。<br>禮貌的說法：<span class='gd-pair'><span class='gd-jp'>おいしいです</span> → <span class='gd-jp'>おいしいですね</span></span><span class='gd-pair'><span class='gd-jp'>始まります</span> → <span class='gd-jp'>始まりますよ</span></span><br>跟朋友講的說法也一樣，直接加：<span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>いいね</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くよ</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨だね</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>對方不可能知道的事，不要加ね</b>。自我介紹說「私は台湾人ですね」，聽起來像在問對方「我是台灣人對吧？」，很怪。直接說<span class='gd-jp'>私は台湾人です。</span>就好。<br>・<b>よ的口氣比較強</b>。對老師、主管糾正事情時加よ，例如「それは違いますよ」，會有點像在教對方。對長輩講話時，よ少用一點比較安全。<br>・ね的語調：<b>尾巴往上揚</b>是在確認「對吧？」；<b>平平或往下</b>是在感嘆「真～呢」。<br>・台灣人講話很愛加「喔」「呢」，但日文不用每句都加。普通在描述事情，什麼都不加也很自然，每句都ね、よ反而會很吵。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是「外面在下雨」，看對方知不知道來選：<br><b>ね</b>＝對方也看到了，一起感嘆：<span class='gd-jp'>雨ですね。</span>（下雨了呢）<br><b>よ</b>＝對方在屋裡沒發現，你告訴他：<span class='gd-jp'>雨ですよ。</span>（外面下雨了喔）<br><b>か</b>＝你自己完全不知道，在問人：<span class='gd-jp'>雨ですか。</span>（在下雨嗎？）</div><div class='gd-sec'>「ね」跟「か」都可以當問句，差在你心裡有沒有答案：<br><span class='gd-jp'>明日は休みですか。</span>（明天放假嗎？：不知道，問問看）<br><span class='gd-jp'>明日は休みですね。</span>（明天放假，對吧？：大概知道，確認一下）</div><div class='gd-warn'>判斷小訣竅：對方也知道→ね；對方不知道、你要告訴他→よ；你自己不知道→か。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>兩個可以連在一起變成「よね」，順序固定是よ在前，不能說「ねよ」。意思是「我記得是這樣，沒錯吧？」：<span class='gd-jp'>テストは明日ですよね。</span>（考試是明天沒錯吧？）</div>",
  "n5-40": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>日文助詞跟中文的「在」「跟」很像，<b>一個字常常有好幾種意思</b>。前面已經學過を、に、で、は、か最基本的用法，這張把它們<b>其他常見的用法</b>整理在一起。看到助詞時，不要只記一個意思，要看前後接什麼字來判斷。</div><div class='gd-h'>を：離開、經過</div><div class='gd-sec'><span class='gd-tag'>離開的地方</span>從某個地方出來、下車、畢業，那個地方用を。常跟<span class='gd-jp'>出る</span>、<span class='gd-jp'>降りる</span>、<span class='gd-jp'>卒業する</span>一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>7時に家を出ます。</span>（我7點出門）</div><div class='gd-ex-line'>・<span class='gd-jp'>次の駅で電車を降ります。</span>（我在下一站下電車）</div><div class='gd-sec'><span class='gd-tag'>經過的地方</span>走、跑、散步、過橋這種「會移動」的動作，經過的路線或範圍用を。</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝、公園を散歩します。</span>（我每天早上在公園散步）</div><div class='gd-ex-line'>・<span class='gd-jp'>この橋を渡ってください。</span>（請過這座橋）</div><div class='gd-h'>に：頻率、落在哪裡、變成</div><div class='gd-sec'><span class='gd-tag'>頻率</span>一段時間＋に＋次數＝每多久幾次。</div><div class='gd-ex-line'>・<span class='gd-jp'>1日に3回、薬を飲みます。</span>（一天吃三次藥）</div><div class='gd-ex-line'>・<span class='gd-jp'>週に1回、プールへ行きます。</span>（我一週去一次游泳池）</div><div class='gd-sec'><span class='gd-tag'>東西落在哪裡</span>寫上去、坐上去、放進去，東西最後「碰到、留在」的地方用に。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに名前を書いてください。</span>（請在這裡寫名字）</div><div class='gd-ex-line'>・<span class='gd-jp'>椅子に座ります。</span>（坐到椅子上）</div><div class='gd-sec'><span class='gd-tag'>變成</span>名詞＋になる＝變成～。</div><div class='gd-ex-line'>・<span class='gd-jp'>将来、先生になりたいです。</span>（我將來想當老師）</div><div class='gd-h'>で：範圍、總共</div><div class='gd-sec'><span class='gd-tag'>範圍</span>「在～裡面最～」，那個範圍用で。</div><div class='gd-ex-line'>・<span class='gd-jp'>兄はクラスでいちばん背が高いです。</span>（我哥哥是班上最高的）</div><div class='gd-sec'><span class='gd-tag'>總共</span>數量＋で＝加起來、合計。買東西超常用。</div><div class='gd-ex-line'>・<span class='gd-jp'>全部でいくらですか。</span>（全部多少錢？）</div><div class='gd-ex-line'>・<span class='gd-jp'>りんごは3つで500円です。</span>（蘋果三個500日圓）</div><div class='gd-h'>は：拿來對比</div><div class='gd-sec'><span class='gd-tag'>對比</span>兩件事放在一起比，各用一個は，意思是「A是這樣，B可不是」。</div><div class='gd-ex-line'>・<span class='gd-jp'>寿司は好きですが、刺身は苦手です。</span>（我喜歡壽司，但生魚片不太行）</div><div class='gd-sec'>只說一半，也會有「其他的另當別論」的味道：</div><div class='gd-ex-line'>・<span class='gd-jp'>お酒は飲みません。</span>（酒我是不喝的）</div><div class='gd-h'>か：二選一</div><div class='gd-sec'><span class='gd-tag'>選擇</span>AかB＝A或B，從裡面挑一個。</div><div class='gd-ex-line'>・<span class='gd-jp'>月曜日か火曜日に来てください。</span>（請星期一或星期二來）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・上車用に，下車用を：<span class='gd-jp'>電車に乗ります</span>、<span class='gd-jp'>電車を降ります</span>。很多人兩個都用同一個助詞。<br>・を的「經過」要配會移動的動作。在公園玩、吃便當這種待在原地做的事，要用で：<span class='gd-jp'>公園で遊びます</span>。<br>・中文說「在這裡寫」，直覺會用で。但寫在紙上、坐在椅子上，東西是「落到」那裡，用に：<span class='gd-jp'>ここに書いてください</span>。<br>・對比的は一樣念 wa，不念 ha。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>か、と、や都能把兩個東西連在一起，意思差很多。同樣是買飲料：<br><span class='gd-jp'>コーヒーと紅茶を買いました。</span>（買了咖啡和紅茶：兩個都買）<br><span class='gd-jp'>コーヒーや紅茶を買いました。</span>（買了咖啡、紅茶之類的：還有別的）<br><span class='gd-jp'>コーヒーか紅茶を買います。</span>（要買咖啡或紅茶：只挑一個）</div><div class='gd-warn'>判斷小訣竅：全部都有用と，舉幾個例子用や，只選一個用か。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>範圍的で可以變成問「哪個最～」：<span class='gd-jp'>果物の中で何がいちばん好きですか。</span>（水果裡你最喜歡什麼？）</div>",
  "n5-41": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「ます形」就是動詞換上<b>禮貌外套</b>的樣子。字典裡查到的是<span class='gd-jp'>飲む</span>，但對老師、店員、剛認識的人要說<span class='gd-jp'>飲みます</span>。這一課只練一件事：<b>拿到任何一個動詞，都會把它變成〜ます</b>。</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><span class='gd-tag'>第一步</span><b>先把第三類（する・来る）挑出來</b>，只有兩個，直接背：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ます</span>（きます）</span><br>「名詞＋する」也算這一類：<span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強します</span></span></div><div class='gd-sec'><span class='gd-tag'>第二步</span><b>剩下的，判斷是第一類還是第二類</b>：<br>・最後一個字<b>不是る</b>（像<span class='gd-jp'>書く</span>、<span class='gd-jp'>飲む</span>、<span class='gd-jp'>会う</span>、<span class='gd-jp'>待つ</span>）：一定是第一類。<br>・最後是る，<b>る前面的音是 a、u、o 結尾</b>（像<span class='gd-jp'>分かる</span>的か、<span class='gd-jp'>作る</span>的く、<span class='gd-jp'>乗る</span>的の）：一定是第一類（する、来る已經在第一步挑掉了，不算在這裡）。<br>・最後是る，<b>る前面的音是 i、e 結尾</b>（像<span class='gd-jp'>見る</span>的み、<span class='gd-jp'>食べる</span>的べ、<span class='gd-jp'>起きる</span>的き）：大部分是第二類。但有幾個例外其實是第一類，要背：<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span>、<span class='gd-jp'>切る</span>。</div><div class='gd-sec'><b>第一類（五段動詞）</b>：最後一個音換成同一行的「い」段音，再加ます。<br>對照五十音表，從う段往前移一格到い段就對了（直排的表是往上一格，橫排的表是往左一格）：う→い、く→き、ぐ→ぎ、す→し、つ→ち、ぬ→に、ぶ→び、む→み、る→り。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く換成き → <span class='gd-jp'>書きます</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲みます</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会います</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待ちます</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話します</span></span><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳ぎます</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊びます</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ります</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加ます。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ます</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きます</span></span><span class='gd-pair'><span class='gd-jp'>着る</span> → <span class='gd-jp'>着ます</span></span></div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>每天的習慣、明天要做的事，都用同一個ます形講。</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝パンを食べます。</span>（我每天早上吃麵包）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日、日本語を勉強します。</span>（我每天學日文）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、友達が家に来ます。</span>（明天朋友要來我家）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・不能直接在字典的樣子後面加ます：<span class='gd-jp'>飲むます</span>、<span class='gd-jp'>行くます</span>都是錯的，要先把最後一個音換掉。<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span>、<span class='gd-jp'>切る</span>長得像第二類，其實是第一類：是<span class='gd-jp'>帰ります</span>，不是帰ます。<br>・<span class='gd-jp'>来ます</span>念<b>きます</b>，不是くます，也不是来ります；<span class='gd-jp'>する</span>也不會變成すります。<br>・「ます」的「す」常常念得很輕，聽起來像 mas，這是正常的發音，不是你聽錯。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把ます拿掉剩下的部分（<span class='gd-jp'>飲み</span>、<span class='gd-jp'>食べ</span>、<span class='gd-jp'>し</span>）會一直用到，後面換個尾巴就是新句型：<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みました</span></span>（喝了）<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みましょう</span></span>（喝吧）<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みたいです</span></span>（我想喝）</div>",
  "n5-42": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>て形是動詞的<b>「接頭」</b>，就像樂高上那個可以再接東西的凸點。中文說「起床，<b>然後</b>洗臉」，日文就把「起床」變成て形，後面再接下一個動作。很多重要句型也都要先把動詞變成て形才接得上，例如「請～」「正在～」，所以它被叫做<b>最重要的變化</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>串動作</span>把好幾個動作照順序連起來。</div><div class='gd-ex-line'>・<span class='gd-jp'>朝起きて、顔を洗います。</span>（早上起床，然後洗臉）</div><div class='gd-sec'><span class='gd-tag'>接句型</span>後面接其他字，變成新的意思。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに名前を書いてください。</span>（請在這裡寫名字）</div><div class='gd-ex-line'>・<span class='gd-jp'>今、ご飯を食べています。</span>（我現在正在吃飯）</div><div class='gd-sec'><span class='gd-tag'>朋友間拜託</span>跟朋友講話時，只說て形就是隨口拜託對方「～一下」。</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと待って。</span>（等一下）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第二類（一段動詞）</b>：最簡單，把「る」拿掉，加「て」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見て</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きて</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て</span>（きて）</span><br><span class='gd-jp'>勉強する</span>這種「名詞＋する」也一樣：<span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強して</span></span></div><div class='gd-sec'><b>第一類（五段動詞）</b>：要看<b>最後一個字</b>是什麼，分成五組。<br><b>う・つ・る → って</b><br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買って</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰って</span></span><br><b>む・ぶ・ぬ → んで</b>（注意是有點點的で）<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span></span><span class='gd-pair'><span class='gd-jp'>死ぬ</span> → <span class='gd-jp'>死んで</span></span><br><b>く → いて</b><br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞いて</span></span><br><b>ぐ → いで</b><br><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急いで</span></span><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いで</span></span><br><b>す → して</b><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話して</span></span><span class='gd-pair'><span class='gd-jp'>貸す</span> → <span class='gd-jp'>貸して</span></span><br><b>唯一的例外</b>：<span class='gd-jp'>行く</span>照規則應該是「行いて」，但實際上是<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span></span>。</div><div class='gd-sec'>小口訣，念熟就好：<b>うつる って、むぶぬ んで、く いて、ぐ いで、す して，行く是行って</b>。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span>長得像第二類，其實是第一類：是<span class='gd-jp'>帰って</span>，不是帰て。<br>・<span class='gd-jp'>行って</span>是例外，但<span class='gd-jp'>書いて</span>、<span class='gd-jp'>聞いて</span>這些く結尾的還是照規則走，不要全部改成って。<br>・ぐ要變成<b>いで</b>、む・ぶ・ぬ要變成<b>んで</b>，常有人寫成泳いて、飲んて，濁音點點別漏掉。<br>・小小的「っ」要停一拍：<span class='gd-jp'>来て</span>（きて，來）跟<span class='gd-jp'>切って</span>（きって，切）只差這一拍，意思完全不同。<br>・<span class='gd-jp'>来て</span>念<b>きて</b>，不是こて或くて。<br>・て形本身沒有過去、現在，看<b>最後一個動詞</b>決定：<span class='gd-jp'>シャワーを浴びて、寝ました。</span>（洗了澡，然後睡了）</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>て形熟了，<b>た形（過去的普通說法）幾乎是送的</b>：規則完全一樣，只要把て換成た、で換成だ。<br><span class='gd-pair'><span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span></span><br>接著可以學「～てください」（請～）、「～ています」（正在～）、「～てから」（～之後），全部都靠這張卡的變化。</div>",
  "n5-43": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>辭書形就是「〜ます」的<b>朋友版</b>，也是字典裡查到的樣子；ない形就是「〜ません」的<b>朋友版</b>。跟老師說<span class='gd-jp'>行きます</span>／<span class='gd-jp'>行きません</span>，跟朋友就說<span class='gd-jp'>行く</span>／<span class='gd-jp'>行かない</span>，意思一樣，只是比較隨興。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>跟朋友家人聊天</span>跟ます一樣，現在的習慣、還沒發生的事都用它。問句只要把尾音拉高就好。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、何時に起きる？</span>（明天幾點起床？）</div><div class='gd-ex-line'>・<span class='gd-jp'>7時に起きる。</span>（7 點起床）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は学校に行かない。</span>（我今天不去學校）</div><div class='gd-ex-line'>・<span class='gd-jp'>私はお酒を飲まない。</span>（我不喝酒）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>先從ます形變回辭書形</b><br><b>第一類（五段動詞）</b>：ます前面那個音，換成同一行的「う」段音。<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → み換成む → <span class='gd-jp'>飲む</span></span><span class='gd-pair'><span class='gd-jp'>書きます</span> → <span class='gd-jp'>書く</span></span><span class='gd-pair'><span class='gd-jp'>歌います</span> → <span class='gd-jp'>歌う</span></span><span class='gd-pair'><span class='gd-jp'>帰ります</span> → <span class='gd-jp'>帰る</span></span><br><b>第二類（一段動詞）</b>：把ます換成る。<br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べる</span></span><span class='gd-pair'><span class='gd-jp'>起きます</span> → <span class='gd-jp'>起きる</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見る</span></span><br><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>する</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来る</span>（くる）</span></div><div class='gd-sec'><b>再從辭書形變成ない形</b><br><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，再加ない。<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く換成か → <span class='gd-jp'>書かない</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まない</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たない</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らない</span></span><br>最後是「う」的，<b>換成「わ」</b>，不是「あ」：<br><span class='gd-pair'><span class='gd-jp'>買う</span> → う換成わ → <span class='gd-jp'>買わない</span></span><span class='gd-pair'><span class='gd-jp'>歌う</span> → <span class='gd-jp'>歌わない</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span></span><br><b>第二類（一段動詞）</b>：把る拿掉，加ない。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きない</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ない</span></span><br><b>第三類（直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない）</span><br>「名詞＋する」也一樣：<span class='gd-pair'><span class='gd-jp'>電話する</span> → <span class='gd-jp'>電話しない</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「う」結尾的不能變成「あない」：是<span class='gd-jp'>買わない</span>，不是買あない。<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span>長得像第二類，其實是第一類：是<span class='gd-jp'>帰らない</span>，不是帰ない。<br>・来る有三種念法要分清楚：<span class='gd-jp'>来る</span>念くる、<span class='gd-jp'>来ます</span>念きます、<span class='gd-jp'>来ない</span>念こない。<br>・<span class='gd-jp'>ある</span>（有、在）的否定是<span class='gd-jp'>ない</span>，不是あらない：<span class='gd-jp'>お金がない。</span>（沒有錢）<br>・ない形是「不（做）」，不是「不能」：<span class='gd-jp'>食べない</span>是「我不吃」，不是「我不能吃」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一句「我明天不來」，看你在跟誰講：<br>對老師、主管：<span class='gd-jp'>明日は来ません。</span><br>對朋友、家人：<span class='gd-jp'>明日は来ない。</span><br>意思完全一樣，差在禮貌程度。對長輩用<span class='gd-jp'>来ない</span>會讓人覺得你沒大沒小；對好朋友一直用<span class='gd-jp'>来ません</span>則會顯得很有距離。</div><div class='gd-warn'>判斷小訣竅：<span class='gd-jp'>ます</span>對上辭書形，<span class='gd-jp'>ません</span>對上ない形。先想對方是誰，再決定用哪一組。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>辭書形、ない形後面還能接很多文法，例如請別人不要做：<span class='gd-jp'>ここで写真を撮らないでください。</span>（請不要在這裡拍照）。下一步可以學過去的說法：<span class='gd-jp'>行った</span>／<span class='gd-jp'>行かなかった</span>。</div>",
  "n5-44": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>た形就是「〜ました」的<b>朋友版</b>，なかった形就是「〜ませんでした」的<b>朋友版</b>。跟老師說「<span class='gd-jp'>昨日、映画を見ました</span>」，跟朋友就說「<span class='gd-jp'>昨日、映画を見た</span>」，意思都是「昨天看了電影」，只是比較輕鬆。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>跟熟人聊過去</span>朋友、家人之間講已經發生的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、渋谷で友達に会った。</span>（昨天在澀谷跟朋友碰面了）</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は何も食べなかった。</span>（今天早上什麼都沒吃）</div><div class='gd-sec'><span class='gd-tag'>自言自語、寫日記</span>沒有對象需要講禮貌的時候。</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、傘を忘れた。</span>（啊，忘記帶傘了）</div><div class='gd-sec'><span class='gd-tag'>接其他文法</span>後面很多文法都要先變成た形才能接，所以這個一定要會。</div><div class='gd-h'>怎麼變た形：先看動詞是哪一類</div><div class='gd-sec'><b>已經會て形的話最輕鬆</b>：把て形的「て」換成「た」、「で」換成「だ」就好。<br><span class='gd-pair'><span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べた</span></span></div><div class='gd-sec'><b>第一類（五段動詞）</b>：看最後一個音是什麼，照下面變。<br>う・つ・る結尾 → った：<span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会った</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待った</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰った</span></span><br>ぬ・む・ぶ結尾 → んだ：<span class='gd-pair'><span class='gd-jp'>死ぬ</span> → <span class='gd-jp'>死んだ</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んだ</span></span><br>く結尾 → いた：<span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いた</span></span><br>ぐ結尾 → いだ：<span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いだ</span></span><br>す結尾 → した：<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話した</span></span><br>唯一的例外：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span></span>（雖然是く結尾，但不是行いた）</div><div class='gd-sec'><b>第二類（一段動詞）</b>：把最後的「る」拿掉，加「た」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きた</span></span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span>（きた）</span></div><div class='gd-h'>怎麼變なかった形</div><div class='gd-sec'>先變成ない形，再把「ない」換成「なかった」。三類都是同一招。<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まない</span> → <span class='gd-jp'>飲まなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span> → <span class='gd-jp'>会わなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span> → <span class='gd-jp'>しなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない） → <span class='gd-jp'>来なかった</span>（こなかった）</span></div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はどこにも行かなかった。</span>（昨天哪裡都沒去）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>行く</span>的た形是<span class='gd-jp'>行った</span>，不是行いた。<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>知る</span>長得像第二類，其實是第一類：是<span class='gd-jp'>帰った</span>、<span class='gd-jp'>走った</span>，不是帰た、走た。<br>・<span class='gd-jp'>来た</span>念<b>きた</b>，<span class='gd-jp'>来なかった</span>念<b>こなかった</b>，同一個字念法不一樣。<br>・<span class='gd-jp'>ある</span>的否定直接是<span class='gd-jp'>ない</span>（沒有「あらない」），過去就是<span class='gd-jp'>なかった</span>：<span class='gd-jp'>時間がなかった。</span>（那時沒時間）<br>・中文的「還沒吃」不是<span class='gd-jp'>食べなかった</span>。なかった是講「那時候沒做」，事情已經過了；「到現在還沒做」要說<span class='gd-jp'>まだ食べていない</span>。<br>・た形、なかった形是朋友之間的說法。對長輩講過去的事，句尾一律用「〜ました」或「〜ませんでした」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>た形 vs ました</b>：意思完全一樣，差在對誰講。<br><span class='gd-jp'>昨日、映画を見ました。</span>（對老師：我昨天看了電影）<br><span class='gd-jp'>昨日、映画を見た。</span>（對朋友：我昨天看了電影）<br>否定也一樣：<span class='gd-jp'>行きませんでした</span>跟<span class='gd-jp'>行かなかった</span>都是「沒去」，前者有禮貌，後者比較隨興。</div><div class='gd-sec'><b>た vs て</b>：只差一個音，功能完全不同。「た」是把話講完、表示已經做了；「て」是話還沒講完，後面要接下去，或拿來拜託人。<br><span class='gd-jp'>ご飯を食べた。</span>（吃飯了）<br><span class='gd-jp'>ご飯を食べて、すぐ寝た。</span>（吃完飯就馬上睡了）</div><div class='gd-warn'>判斷小訣竅：句子到這裡結束、事情已經發生 → た；後面還要接話 → て；對長輩、客人 → 換回ました、ませんでした。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>た形後面加「り」，就是「〜たり〜たりします」（做做這個、做做那個）：<span class='gd-jp'>週末は映画を見たり、買い物をしたりします。</span>（週末會看看電影、買買東西）<br>た形加「あとで」＝做完～之後：<span class='gd-jp'>ご飯を食べたあとで、散歩します。</span>（吃完飯之後去散步）</div>",
  "n5-45": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>普通形就是把「です・ます」拿掉的<b>朋友版說法</b>，也是很多句型前面要接的基本形。每個詞都有四種樣子，剛好對應中文的「去／不去／去了／沒去」：<b>現在肯定、現在否定、過去肯定、過去否定</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>跟熟人講話</span>家人、朋友之間不用ます，直接講普通形。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、映画を見た。</span>（我昨天看了電影）</div><div class='gd-sec'><span class='gd-tag'>接句型</span>就算整句很有禮貌，中間也常要先換成普通形，再接後面的句型。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降ると思います。</span>（我覺得明天會下雨）</div><div class='gd-h'>怎麼變：先看動詞是哪一類</div><div class='gd-sec'><b>第一類（五段動詞）</b><br>否定：最後一個音換成同一行的「あ」段音，再加ない。<span class='gd-pair'><span class='gd-jp'>行く</span> → く換成か → <span class='gd-jp'>行かない</span></span><br>過去：跟て形的變法一樣，只是把て換成た。<span class='gd-pair'><span class='gd-jp'>行って</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span></span><br>過去否定：把ない的「い」換成「かった」。<span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなかった</span></span><br>整組看一次：<span class='gd-jp'>買う／買わない／買った／買わなかった</span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：最簡單，把「る」拿掉，加ない、た、なかった。<br><span class='gd-jp'>食べる／食べない／食べた／食べなかった</span><br><span class='gd-jp'>見る／見ない／見た／見なかった</span></div><div class='gd-sec'><b>第三類（只有兩個，直接背）</b><br><span class='gd-jp'>する／しない／した／しなかった</span><br><span class='gd-jp'>来る／来ない／来た／来なかった</span>（くる／こない／きた／こなかった）<br><span class='gd-jp'>勉強する</span>這種「名詞＋する」，就照する變：<span class='gd-jp'>勉強しない</span>、<span class='gd-jp'>勉強した</span>、<span class='gd-jp'>勉強しなかった</span>。</div><div class='gd-h'>形容詞和名詞怎麼變</div><div class='gd-sec'><b>い形容詞</b>：否定把最後的い換成くない，過去把い換成かった。<br><span class='gd-jp'>高い／高くない／高かった／高くなかった</span></div><div class='gd-sec'><b>な形容詞</b>：後面接だ、じゃない、だった、じゃなかった。<br><span class='gd-jp'>静かだ／静かじゃない／静かだった／静かじゃなかった</span></div><div class='gd-sec'><b>名詞</b>：跟な形容詞的變法一模一樣。<br><span class='gd-jp'>学生だ／学生じゃない／学生だった／学生じゃなかった</span></div><div class='gd-warn'>小發現：不管動詞、形容詞還是名詞，否定最後都是「ない」，而且都用同一招變過去：<span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なかった</span></span>。記住這招，第四種（過去否定）幾乎不用另外背。</div><div class='gd-h'>跟ます・です對照著記</div><div class='gd-sec'><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行く</span></span><span class='gd-pair'><span class='gd-jp'>行きません</span> → <span class='gd-jp'>行かない</span></span><br><span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>行きませんでした</span> → <span class='gd-jp'>行かなかった</span></span><br>い形容詞最輕鬆，把です拿掉就好：<span class='gd-pair'><span class='gd-jp'>高かったです</span> → <span class='gd-jp'>高かった</span></span><br>な形容詞和名詞是把です換成だ：<span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だ</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・用う結尾的第一類動詞，否定要變成「わ」：<span class='gd-jp'>買わない</span>，不是買あない。<br>・<span class='gd-jp'>ある</span>的否定是<span class='gd-jp'>ない</span>，不是あらない。<br>・<span class='gd-jp'>行く</span>的過去是<span class='gd-jp'>行った</span>，不是行いた。<br>・<span class='gd-jp'>いい</span>一變化就要換成よ開頭：<span class='gd-jp'>よくない</span>、<span class='gd-jp'>よかった</span>、<span class='gd-jp'>よくなかった</span>。<br>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>有名</span>看起來像い形容詞，其實是な形容詞：要說<span class='gd-jp'>きれいじゃない</span>，不是きれくない。<br>・い形容詞後面不能加だ：說<span class='gd-jp'>高い</span>就好，不要說高いだ。<br>・名詞、な形容詞直接用「だ」結尾，口氣有點硬。朋友聊天常把だ省掉，或後面加よ，例如<span class='gd-jp'>学生だよ</span>。<br>・用普通形問朋友問題時，通常不加か，句尾語調往上揚就好：<span class='gd-jp'>明日、来る？</span>（你明天會來嗎？）</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>普通形接句型時，名詞和な形容詞的「だ」要特別注意：有時候留著，有時候要拿掉，有時候要換成な。<br><span class='gd-jp'>静かだと思う。</span>（我覺得很安靜：だ留著）<br><span class='gd-jp'>静かでしょう。</span>（應該很安靜吧：だ拿掉）<br><span class='gd-jp'>学生なの？</span>（你是學生喔？：だ換成な）<br>這些會在「～でしょう」和形式名詞「の」那幾課一個一個講。</div>",
  "n5-46": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文說「高<b>的</b>山」「漂亮<b>的</b>花」，形容詞跟名詞中間要夾一個「的」。日文的做法分兩種：<b>い形容詞直接黏在名詞前面</b>，<b>な形容詞中間要夾一個「な」</b>。這個「な」的位置，就很像中文的「的」。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>い形容詞</b>（字尾是い的那種）：什麼都不用改，直接放在名詞前面。<br><span class='gd-pair'><span class='gd-jp'>高い</span>＋<span class='gd-jp'>山</span> → <span class='gd-jp'>高い山</span></span>（高山）<br><span class='gd-pair'><span class='gd-jp'>新しい</span>＋<span class='gd-jp'>靴</span> → <span class='gd-jp'>新しい靴</span></span>（新鞋子）</div><div class='gd-sec'><b>な形容詞</b>：後面先加「な」，再接名詞。<br><span class='gd-pair'><span class='gd-jp'>きれい</span>＋な＋<span class='gd-jp'>花</span> → <span class='gd-jp'>きれいな花</span></span>（漂亮的花）<br><span class='gd-pair'><span class='gd-jp'>静か</span>＋な＋<span class='gd-jp'>部屋</span> → <span class='gd-jp'>静かな部屋</span></span>（安靜的房間）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-ex-line'>・<span class='gd-jp'>新しい靴を買いました。</span>（我買了新鞋子）</div><div class='gd-ex-line'>・<span class='gd-jp'>これはおいしいケーキですね。</span>（這是很好吃的蛋糕耶）</div><div class='gd-ex-line'>・<span class='gd-jp'>静かな部屋がいいです。</span>（我想要安靜的房間）</div><div class='gd-ex-line'>・<span class='gd-jp'>好きな食べ物は何ですか。</span>（你喜歡的食物是什麼？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>きらい</span>字尾雖然是い，其實是<b>な形容詞</b>，要說<span class='gd-jp'>きれいな花</span>、<span class='gd-jp'>きらいな食べ物</span>，不是きれい花。<br>・受中文「的」影響，很多人會在中間塞「の」：「高いの山」「静かの部屋」都是錯的。い形容詞什麼都不加，な形容詞加「な」。<br>・「很多人」不能直接說「多い人」，要說<span class='gd-jp'>たくさんの人</span>。<br>・你可能會看到<span class='gd-jp'>大きな家</span>、<span class='gd-jp'>小さな店</span>，這不是寫錯，是<span class='gd-jp'>大きい</span>、<span class='gd-jp'>小さい</span>另外有的說法，只能放在名詞前面用。<span class='gd-jp'>大きい家</span>、<span class='gd-jp'>大きな家</span>都對。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><span class='gd-tag'>放句尾 vs 放名詞前</span>な形容詞的「な」<b>只有在後面接名詞時才出現</b>，放在句尾直接接です。<br><span class='gd-jp'>この部屋は静かです。</span>（這個房間很安靜）<br><span class='gd-jp'>静かな部屋です。</span>（是一間安靜的房間）<br>不能說「この部屋は静かなです」。</div><div class='gd-sec'><span class='gd-tag'>名詞＋の</span>如果放在前面的是<b>名詞</b>，中間用的是「の」，不是「な」。<br><span class='gd-jp'>日本の車</span>（日本的車：名詞＋の）<br><span class='gd-jp'>新しい車</span>（新的車：い形容詞直接接）<br><span class='gd-jp'>きれいな車</span>（漂亮的車：な形容詞＋な）</div><div class='gd-warn'>判斷小訣竅：先問自己前面那個字是什麼。い形容詞直接黏，な形容詞夾な，名詞夾の。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>形容詞也可以拿來修飾動詞，例如<span class='gd-jp'>早く起きます</span>（早早起床），這是「形容詞的副詞用法」。</div>",
  "n5-47": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文要說一個動作「怎麼做」，會加「地」或「得」：「早早地起床」「打掃得很乾淨」。日文也一樣，只要把形容詞的<b>尾巴改一下</b>，就能放在動詞前面，說明這個動作是怎麼做的。</div><div class='gd-h'>怎麼變：先看形容詞是哪一種</div><div class='gd-sec'><b>い形容詞（結尾是「い」的形容詞）</b>：把最後的「い」換成「く」。<br><span class='gd-pair'><span class='gd-jp'>早い</span> → い換成く → <span class='gd-jp'>早く</span></span><br><span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きく</span></span><span class='gd-pair'><span class='gd-jp'>楽しい</span> → <span class='gd-jp'>楽しく</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>明日は早く起きます。</span>（明天要早起）</div><div class='gd-ex-line'>・<span class='gd-jp'>名前を大きく書いてください。</span>（名字請寫大一點）</div><div class='gd-sec'><b>な形容詞（接名詞時要加「な」的形容詞）</b>：直接加「に」。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → 加に → <span class='gd-jp'>静かに</span></span><br><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいに</span></span><span class='gd-pair'><span class='gd-jp'>上手</span> → <span class='gd-jp'>上手に</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>部屋をきれいに掃除しました。</span>（我把房間打掃得很乾淨）</div><div class='gd-ex-line'>・<span class='gd-jp'>図書館では静かに話してください。</span>（在圖書館請小聲講話）</div><div class='gd-sec'><b>例外要背</b>：<span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よく</span></span>，不是いく。以いい結尾的詞也一樣，例如<span class='gd-pair'><span class='gd-jp'>かっこいい</span> → <span class='gd-jp'>かっこよく</span></span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はよく寝ました。</span>（昨天睡得很好）</div><div class='gd-ex-line'>・<span class='gd-jp'>かっこよく踊りたいです。</span>（我想跳得很帥）</div><div class='gd-h'>中文的「得」要倒過來講</div><div class='gd-sec'>中文常說「跳得很好」「寫得很漂亮」，形容的部分在動詞<b>後面</b>。日文剛好相反，<b>先說怎麼做，再說動作</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは上手に踊ります。</span>（田中先生舞跳得很好）</div><div class='gd-ex-line'>・<span class='gd-jp'>字をきれいに書きます。</span>（把字寫得很漂亮）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>有名</span>結尾雖然有い，其實是な形容詞：要說<span class='gd-jp'>きれいに</span>，不是きれく。<br>・形容詞原本的樣子不能直接放在動詞前面：不能說早い起きます，要說<span class='gd-jp'>早く起きます</span>；不能說静かな話します，要說<span class='gd-jp'>静かに話します</span>。<br>・<span class='gd-jp'>よく</span>除了「好好地」，也很常當「常常」用：<span class='gd-jp'>よく行きます</span>是「常常去」。要看前後文判斷。<br>・<span class='gd-jp'>早く</span>和<span class='gd-jp'>速く</span>都念はやく，但「早く」是時間早，「速く」是速度快：<span class='gd-jp'>早く起きます</span>（早起）、<span class='gd-jp'>速く走ります</span>（跑得快）。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>上一課學的<b>形容詞修飾名詞</b>，跟這課很容易混。差別只看<b>後面接什麼</b>：<br>接名詞（人、東西）：い形容詞不變，な形容詞加「な」。<br>接動詞（動作）：い形容詞改「く」，な形容詞加「に」。</div><div class='gd-ex-line'>・<span class='gd-jp'>静かな人です。</span>（是個安靜的人）</div><div class='gd-ex-line'>・<span class='gd-jp'>静かに話します。</span>（小聲地說話）</div><div class='gd-ex-line'>・<span class='gd-jp'>早い電車に乗ります。</span>（搭比較早的電車）</div><div class='gd-ex-line'>・<span class='gd-jp'>早く来てください。</span>（請早點來）</div><div class='gd-warn'>判斷小訣竅：後面接「東西」用「〜い／〜な」，後面接「動作」用「〜く／〜に」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>同樣的く／に，後面接<span class='gd-jp'>なります</span>是「變得～」，接<span class='gd-jp'>します</span>是「把它弄成～」：<span class='gd-jp'>寒くなりました。</span>（變冷了）、<span class='gd-jp'>静かにしてください。</span>（請安靜）</div>",
  "n5-48": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文會說「<b>上週借的</b>書」「<b>弟弟在讀的</b>學校」，把一整段話放在名詞前面，說明是哪一個。日文也一樣<b>放在名詞前面</b>，順序跟中文幾乎一樣，差別只有一個：<b>中間那個「的」不用翻出來</b>。<br><span class='gd-jp'>先週借りた本</span>（上週借的書）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>形容名詞的那段話要用<b>普通形</b>，就是朋友之間講話、沒有ます和です的樣子，然後直接黏在名詞前面。<br><span class='gd-pair'><span class='gd-jp'>本を借りました</span> → <span class='gd-jp'>借りた</span></span> → <span class='gd-jp'>先週借りた本</span></div><div class='gd-sec'><span class='gd-tag'>動詞</span>用哪個形，意思就跟著變：<br><span class='gd-jp'>見る映画</span>（要看的電影）<br><span class='gd-jp'>見ない映画</span>（不看的電影）<br><span class='gd-jp'>見た映画</span>（看過的電影）<br><span class='gd-jp'>見なかった映画</span>（沒看的電影）<br><span class='gd-jp'>見ている映画</span>（正在看的電影）</div><div class='gd-sec'><span class='gd-tag'>い形容詞結尾</span>直接接。<br><span class='gd-jp'>髪が長い人</span>（頭髮長的人）</div><div class='gd-sec'><span class='gd-tag'>な形容詞結尾</span>現在肯定時，だ要改成<b>な</b>。<br><span class='gd-pair'><span class='gd-jp'>交通が便利だ</span> → <span class='gd-jp'>交通が便利な町</span></span>（交通方便的城鎮）<br>不是「便利だ町」。</div><div class='gd-sec'><span class='gd-tag'>名詞結尾</span>現在肯定時，だ要改成<b>の</b>，不是な。<br><span class='gd-pair'><span class='gd-jp'>母が日本人だ</span> → <span class='gd-jp'>母が日本人の友達</span></span>（媽媽是日本人的朋友）<br>不是「日本人だ友達」，也不是「日本人な友達」。</div><div class='gd-sec'>過去或否定的時候就不用改，直接接：<br><span class='gd-jp'>静かじゃない部屋</span>（不安靜的房間）<br><span class='gd-jp'>昔、先生だった人</span>（以前當老師的人）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'>整串「○○的名詞」可以當成一個大名詞，放進句子裡用。要講得有禮貌，<b>只要句尾用です・ます</b>，前面那段維持普通形就好。</div><div class='gd-ex-line'>・<span class='gd-jp'>これは母が作ったケーキです。</span>（這是我媽媽做的蛋糕）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日見た映画はおもしろかったです。</span>（昨天看的電影很好看）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本で行きたい所はどこですか。</span>（你在日本想去的地方是哪裡？）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の近くにある店で会いましょう。</span>（我們在車站附近的那家店見面吧）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・中文有「的」，就忍不住加の：「借りたの本」是錯的，要說<span class='gd-jp'>借りた本</span>。<br>・裡面不要用ます：「買いました本」是錯的，要說<span class='gd-jp'>買った本</span>。禮貌交給句尾的です・ます。<br>・那段話裡「誰做的」要用<b>が</b>，不能用は：「私は作った料理」不對，要說<span class='gd-jp'>私が作った料理</span>（我做的菜）。你也可能看到<span class='gd-jp'>私の作った料理</span>，が換成の，意思一樣。<br>・な形容詞改成<b>な</b>（<span class='gd-jp'>静かな部屋</span>），名詞改成<b>の</b>（<span class='gd-jp'>医者の父</span>，當醫生的爸爸），不要混在一起。<br>・<span class='gd-jp'>見た映画</span>是「看過的」，<span class='gd-jp'>見る映画</span>是「要看的、平常會看的」，時間要選對。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在講書，前面是什麼詞，決定要不要加の：<br><span class='gd-jp'>私の本</span>（我的書）：前面是名詞，要加の<br><span class='gd-jp'>私が買った本</span>（我買的書）：前面是動詞，直接接<br><span class='gd-jp'>新しい本</span>（新的書）：前面是い形容詞，直接接</div><div class='gd-warn'>判斷小訣竅：緊貼在名詞前面的那個字是名詞，才加の；是動詞或い形容詞，就直接接，中文的「的」不用管它。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「〜とき」（～的時候）用的就是同一套接法：<span class='gd-jp'>日本へ行くとき</span>（去日本的時候）、<span class='gd-jp'>子どものとき</span>（小時候）。</div>",
  "n5-49": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「の」可以把一個動作<b>包成「一件事」</b>，就像中文說「拍照<b>這件事</b>」。中文可以直接講「我喜歡游泳」，動詞直接拿來用；日文不行，動詞後面要先加「の」，變成「游泳這件事」，後面才能接<span class='gd-jp'>は</span>、<span class='gd-jp'>が</span>、<span class='gd-jp'>を</span>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>動詞用<b>普通形</b>（就是字典上的樣子，例如<span class='gd-jp'>泳ぐ</span>、<span class='gd-jp'>撮る</span>；不是把ます拿掉後的<span class='gd-jp'>泳ぎ</span>、<span class='gd-jp'>撮り</span>），直接加「の」。<br><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳ぐの</span></span>（游泳這件事）<br><span class='gd-pair'><span class='gd-jp'>写真を撮る</span> → <span class='gd-jp'>写真を撮るの</span></span>（拍照這件事）<br>要說「不做某件事」，就用ない形加の：<span class='gd-pair'><span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べないの</span></span>（不吃這件事）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>のが好き・上手</span>說喜不喜歡、擅不擅長做某件事。後面是<span class='gd-jp'>好き</span>、<span class='gd-jp'>嫌い</span>、<span class='gd-jp'>上手</span>、<span class='gd-jp'>下手</span>時，用「が」。</div><div class='gd-ex-line'>・<span class='gd-jp'>小説を読むのが好きです。</span>（我喜歡看小說）</div><div class='gd-ex-line'>・<span class='gd-jp'>母は料理を作るのが上手です。</span>（我媽很會做菜）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は歌うのが下手です。</span>（我很不會唱歌）</div><div class='gd-sec'><span class='gd-tag'>のは＋感想</span>先說一件事，再說你覺得它怎麼樣。</div><div class='gd-ex-line'>・<span class='gd-jp'>写真を撮るのは楽しいです。</span>（拍照很好玩）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語を話すのは難しいです。</span>（講日文很難）</div><div class='gd-ex-line'>・<span class='gd-jp'>朝ご飯を食べないのは体によくないです。</span>（不吃早餐對身體不好）</div><div class='gd-sec'><span class='gd-tag'>のを＋動作</span>把「那件事」當成動作的對象。</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題を出すのを忘れました。</span>（我忘了交作業）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんが来るのを待っています。</span>（我在等田中來）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・照中文習慣直接把動詞放進去：<span class='gd-jp'>泳ぐが好きです</span>是錯的，要說<span class='gd-jp'>泳ぐのが好きです</span>。<br>・の前面不能用ます形：不能說「泳ぎますのが好きです」，禮貌放在句尾的<span class='gd-jp'>です</span>就好。<br>・本來就是名詞的，不用再加の：<span class='gd-jp'>音楽が好きです</span>（我喜歡音樂），不要說成「音楽のが好きです」。<br>・<span class='gd-jp'>好き</span>、<span class='gd-jp'>上手</span>前面用「が」，不要因為中文「喜歡<b>做</b>～」就用成「を」。<br>・跟<span class='gd-jp'>私の本</span>（我的書）那個「の」不一樣：那個前面是名詞，意思是「的」；這裡前面是動詞，意思是「這件事」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>「こと」也可以把動作變成「一件事」，很多時候兩個都能用：<br><span class='gd-jp'>本を読むのが好きです。</span>／<span class='gd-jp'>本を読むことが好きです。</span>（都是「我喜歡看書」，こと聽起來比較正式一點）<br><br>但有些地方只能用其中一個：<br><b>看到、聽到的畫面，只能用の</b>：<span class='gd-jp'>田中さんが走っているのを見ました。</span>（我看到田中在跑步）<br><b>「A是～」這種句尾，要用こと</b>：<span class='gd-jp'>私の趣味は写真を撮ることです。</span>（我的興趣是拍照），不說「撮るのです」。</div><div class='gd-warn'>判斷小訣竅：親眼看到、親耳聽到用の；「～是做某件事」放在句尾用こと；說喜歡、說好不好玩時兩個都行，平常講話用の最順。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把「こと」學熟，下一步就能學<span class='gd-jp'>〜ことができる</span>＝會做～、能做～：<span class='gd-jp'>私は泳ぐことができます。</span>（我會游泳）</div>",
  "n5-50": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文什麼都用「有」：桌上有書、房間有貓。日文要多分一步：<b>東西、植物</b>用<span class='gd-jp'>あります</span>，<b>人和動物</b>用<span class='gd-jp'>います</span>。看那個東西是不是活的、會不會自己動，就知道要用哪一個。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>地點＋<span class='gd-jp'>に</span>＋東西或人＋<span class='gd-jp'>が</span>＋<span class='gd-jp'>あります</span>／<span class='gd-jp'>います</span><br><span class='gd-jp'>に</span>像中文的「在」，標出地點；<span class='gd-jp'>が</span>標出「有的是什麼」。</div><div class='gd-ex-line'>・<span class='gd-jp'>引き出しにハサミがあります。</span>（抽屜裡有剪刀）</div><div class='gd-ex-line'>・<span class='gd-jp'>教室に生徒がいます。</span>（教室裡有學生）</div><div class='gd-h'>あります還是います</div><div class='gd-sec'><span class='gd-tag'>あります</span>東西、植物、建築物。樹雖然是活的，但不會走動，所以用<span class='gd-jp'>あります</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>机の上に本があります。</span>（桌上有書）</div><div class='gd-ex-line'>・<span class='gd-jp'>庭に大きい木があります。</span>（院子裡有一棵大樹）</div><div class='gd-sec'><span class='gd-tag'>います</span>人、動物，連魚和蟲也算。</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋に猫がいます。</span>（房間裡有貓）</div><div class='gd-ex-line'>・<span class='gd-jp'>川に魚がいます。</span>（河裡有魚）</div><div class='gd-h'>最常聽到的樣子</div><div class='gd-sec'><span class='gd-tag'>～在哪裡</span>想說某個東西「在」哪裡，就把它放前面、用<span class='gd-jp'>は</span>，地點一樣用<span class='gd-jp'>に</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>ハサミは引き出しにあります。</span>（剪刀在抽屜裡）</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこにありますか。</span>（廁所在哪裡？）</div><div class='gd-sec'><span class='gd-tag'>沒有</span>把ます換成ません：<span class='gd-pair'><span class='gd-jp'>あります</span> → <span class='gd-jp'>ありません</span></span><span class='gd-pair'><span class='gd-jp'>います</span> → <span class='gd-jp'>いません</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>教室に誰もいません。</span>（教室裡一個人都沒有）</div><div class='gd-sec'><span class='gd-tag'>我有～</span>家人、時間這種「有」，日文也常用這兩個字。</div><div class='gd-ex-line'>・<span class='gd-jp'>姉が一人います。</span>（我有一個姊姊）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、時間がありますか。</span>（你明天有空嗎？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・人一定用<span class='gd-jp'>います</span>：說「有老師」是<span class='gd-jp'>先生がいます</span>，講成「先生があります」是錯的。家人也一樣：<span class='gd-jp'>妹がいます</span>。<br>・植物用<span class='gd-jp'>あります</span>；魚、蟲再小，活的就用<span class='gd-jp'>います</span>。<br>・東西、人、動物「在某處」，地點用<span class='gd-jp'>に</span>：是<span class='gd-jp'>部屋に猫がいます</span>，不是部屋で猫がいます。<br>・<b>例外</b>：如果「有」的是活動、事件（<span class='gd-jp'>テスト</span>、<span class='gd-jp'>パーティー</span>、<span class='gd-jp'>会議</span>…），意思是「在那裡舉行」，地點要用<span class='gd-jp'>で</span>：<span class='gd-jp'>あした学校でテストがあります。</span>（明天學校有考試）<br>・「什麼都沒有」「一個人都沒有」的<span class='gd-jp'>何も</span>、<span class='gd-jp'>誰も</span>，後面一定接否定的<span class='gd-jp'>ありません</span>／<span class='gd-jp'>いません</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在公園，看後面接什麼：<br><b>存在</b>用<span class='gd-jp'>に</span>：<span class='gd-jp'>公園に犬がいます。</span>（公園裡有狗）<br><b>做動作</b>用<span class='gd-jp'>で</span>：<span class='gd-jp'>公園で犬と遊びます。</span>（在公園跟狗玩）<br><b>活動舉行</b>用<span class='gd-jp'>で</span>：<span class='gd-jp'>公園でお祭りがあります。</span>（公園有祭典）</div><div class='gd-warn'>判斷小訣竅：後面是<span class='gd-jp'>あります</span>／<span class='gd-jp'>います</span>，而且是東西、人、動物存在，就用<span class='gd-jp'>に</span>；後面是動作，或「有」的是活動、事件，就用<span class='gd-jp'>で</span>。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>加上數量：<span class='gd-jp'>猫が二匹います。</span>（有兩隻貓）<br>另外，「正在～」的<span class='gd-jp'>～ています</span>，裡面那個<span class='gd-jp'>います</span>就是今天學的這個字。</div>",
  "n5-52": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜ています」差不多就是中文的<b>「正在～」「～著」「已經～了（現在還是那樣）」「最近都有在～」</b>。重點是它講的不是一個點，而是<b>一段持續中的狀態</b>：動作正在進行、結果還留著，或是這陣子一直在做。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>先把動詞變成て形，後面加<b>います</b>就好。て形怎麼變，可以回去複習「て形」那一課。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べています</span></span><br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んでいます</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>しています</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て</span> → <span class='gd-jp'>来ています</span>（きています）</span></div><div class='gd-h'>三種意思</div><div class='gd-sec'><span class='gd-tag'>正在做</span>這一刻動作正在進行，常跟「今」一起出現。</div><div class='gd-ex-line'>・<span class='gd-jp'>今、洗濯しています。</span>（我現在正在洗衣服）</div><div class='gd-ex-line'>・<span class='gd-jp'>弟はテレビを見ています。</span>（弟弟正在看電視）</div><div class='gd-sec'><span class='gd-tag'>結果還留著</span>有些動作是<b>一下子就完成</b>的，例如結婚、（門、窗）打開（<span class='gd-jp'>開く</span>）、搬去住。這種動詞加ています，意思不是「正在」，而是「做完了，現在還是那個狀態」。要描述東西現在的狀態，用的是<span class='gd-jp'>開く</span>這種自動詞：說<span class='gd-jp'>窓が開いています</span>，不要說成<span class='gd-jp'>窓を開けています</span>（這樣聽起來比較像「有人正在開窗」）。</div><div class='gd-ex-line'>・<span class='gd-jp'>窓が開いています。</span>（窗戶開著）</div><div class='gd-ex-line'>・<span class='gd-jp'>京都に住んでいます。</span>（我住在京都）</div><div class='gd-ex-line'>・<span class='gd-jp'>姉は結婚しています。</span>（我姊姊已婚）</div><div class='gd-sec'><span class='gd-tag'>這陣子都有在做</span>最近、目前這段時間一直持續在做的事，像工作、近況、最近養成的習慣。</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝走っています。</span>（我每天早上都有在跑步）</div><div class='gd-ex-line'>・<span class='gd-jp'>父は銀行で働いています。</span>（我爸在銀行上班）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>結婚しています</span>是「已婚」，不是「正在辦婚禮」。同樣的，<span class='gd-jp'>住んでいます</span>是「住在」，要說現在住哪裡一定用這個；<span class='gd-jp'>京都に住みます</span>反而變成「（之後）要住京都」。<br>・「知道」要說<span class='gd-jp'>知っています</span>，但「不知道」是<span class='gd-jp'>知りません</span>，不是知っていません。<br>・別人問<span class='gd-jp'>もう食べましたか</span>，要回「還沒」是<span class='gd-jp'>まだ食べていません</span>，不要說成まだ食べませんでした。<br>・<span class='gd-jp'>来ています</span>的来念<b>き</b>。<br>・朋友之間常把い吃掉，<span class='gd-jp'>食べています</span>會說成<span class='gd-jp'>食べてる</span>，聽到不要愣住。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ます</b>和<b>ています</b>最常被搞混，看同一個動作的差別：<br><span class='gd-jp'>本を読みます。</span>（我會看書：平常的習慣，或等一下要看）<br><span class='gd-jp'>本を読んでいます。</span>（我正在看書）<br><br><span class='gd-jp'>来月結婚します。</span>（我下個月要結婚）<br><span class='gd-jp'>もう結婚しています。</span>（我已經結婚了）<br><br>兩個都能講習慣，但感覺不一樣：<br><span class='gd-jp'>毎日コーヒーを飲みます。</span>（我每天喝咖啡：一般的習慣、事實）<br><span class='gd-jp'>最近、毎朝走っています。</span>（我最近每天早上都有在跑：這陣子持續在做）</div><div class='gd-warn'>判斷小訣竅：講這一刻正在做、已經～／～著，或「最近、現在都有在做」，用ています；講一般性的習慣或接下來要做，用ます。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>學「自動詞・他動詞」時，你會常看到<span class='gd-jp'>ドアが閉まっています</span>（門關著）這種「結果還留著」的說法，到時候對照著看會更清楚。</div>",
  "n5-53": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文要講一串事情很簡單，「我早上起床、刷牙、出門」，用逗號串起來就好。日文不能這樣直接串，前面的動詞要先變成<b>て形</b>，意思就像「…然後…」。<b>最後一個動詞</b>才決定是現在還是過去、有沒有禮貌。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞</b>：直接用て形（怎麼變請看「て形」那一課）。<br><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きて</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span></span></div><div class='gd-sec'><b>い形容詞</b>：把最後的「い」換成「くて」。<br><span class='gd-pair'><span class='gd-jp'>安い</span> → い換成くて → <span class='gd-jp'>安くて</span></span><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よくて</span></span>（這個例外要背）</div><div class='gd-sec'><b>な形容詞、名詞</b>：後面直接加「で」。<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かで</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生で</span></span></div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>照順序講</span>一件做完再做下一件，照發生的順序講出來。</div><div class='gd-ex-line'>・<span class='gd-jp'>朝起きて、歯を磨いて、出かけます。</span>（早上起床、刷牙，然後出門）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は家に帰って、すぐ寝ました。</span>（昨天回到家就馬上睡了）</div><div class='gd-sec'><span class='gd-tag'>講好幾個特點</span>形容一個人或東西，一次講兩個特點，像中文的「又～又～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安くて、おいしいです。</span>（這家店又便宜又好吃）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は台湾人で、大学生です。</span>（我是台灣人，是大學生）</div><div class='gd-sec'><span class='gd-tag'>用什麼方式做</span>前面的動作是後面那件事的「方式」或「樣子」。</div><div class='gd-ex-line'>・<span class='gd-jp'>歩いて駅へ行きます。</span>（走路去車站）</div><div class='gd-ex-line'>・<span class='gd-jp'>傘を持って出かけます。</span>（帶著傘出門）</div><div class='gd-sec'><span class='gd-tag'>原因</span>前面是原因，後面多半是心情、狀態，或是「沒辦法～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>ニュースを聞いて、びっくりしました。</span>（聽到新聞，嚇了一跳）</div><div class='gd-ex-line'>・<span class='gd-jp'>頭が痛くて、何もできませんでした。</span>（頭很痛，什麼都沒辦法做）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・時間跟禮貌<b>只看最後一個動詞</b>：<span class='gd-jp'>昨日、デパートへ行って、靴を買いました。</span>（昨天去百貨公司買了鞋子）前面的<span class='gd-jp'>行って</span>不用改成過去，「過去」交給最後的<span class='gd-jp'>買いました</span>。<br>・い形容詞是<span class='gd-jp'>安くて</span>，不是「安いて」；<span class='gd-jp'>いい</span>要變<span class='gd-jp'>よくて</span>。な形容詞是<span class='gd-jp'>静かで</span>，不是「静かくて」。<br>・一次講兩個特點，最好兩個方向一樣（都是優點或都是缺點）。像「便宜但不好吃」這種一好一壞的，要改用<span class='gd-jp'>が</span>：<span class='gd-jp'>この店は安いですが、おいしくないです。</span>（這家店很便宜，但是不好吃）<br>・表示原因的て，後面<b>不能</b>接「～吧」「請～」「我想～」。要說「在下雨，我們搭計程車去吧」，就改用<span class='gd-jp'>から</span>：<span class='gd-jp'>雨が降っているから、タクシーで行きましょう。</span></div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣在講週末做了什麼：<br><span class='gd-jp'>映画を見て、ご飯を食べました。</span>（看了電影，然後去吃飯：照順序交代）<br><span class='gd-jp'>映画を見てから、ご飯を食べました。</span>（看完電影<b>之後才</b>去吃飯：特別強調先後）<br><span class='gd-jp'>映画を見たり、ご飯を食べたりしました。</span>（看看電影、吃吃飯之類的：只是舉例，順序不重要，可能還做了別的）</div><div class='gd-warn'>判斷小訣竅：照順序一件件講用「て」，強調「做完A才做B」用「てから」，隨便舉幾件事用「たり～たり」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>て形後面還能接很多常用句型，例如「請～」：<span class='gd-jp'>ちょっと待ってください。</span>（請等一下），還有「正在～」：<span class='gd-jp'>今、ご飯を食べています。</span>（我現在正在吃飯）</div>",
  "n5-55": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜てください」就是中文的<b>「請〜」</b>，「〜ないでください」就是<b>「請不要〜」「請勿〜」</b>。朋友說「請等一下」是<span class='gd-jp'>ちょっと待ってください</span>，告示牌寫「請勿拍照」是<span class='gd-jp'>写真を撮らないでください</span>，用的就是這兩個句型。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>拜託別人</span>請對方幫你做某件事。</div><div class='gd-ex-line'>・<span class='gd-jp'>もう一度言ってください。</span>（請再說一次）</div><div class='gd-sec'><span class='gd-tag'>指示、交代</span>老師上課、醫生交代、說明步驟時很常聽到。</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに名前を書いてください。</span>（請在這裡寫名字）</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を毎日飲んでください。</span>（這個藥請每天吃）</div><div class='gd-sec'><span class='gd-tag'>請對方不要做</span>提醒、禁止、安慰都用得到。</div><div class='gd-ex-line'>・<span class='gd-jp'>心配しないでください。</span>（請不要擔心）</div><div class='gd-ex-line'>・<span class='gd-jp'>教室で食べないでください。</span>（請不要在教室吃東西）</div><div class='gd-h'>怎麼接：請做〜</div><div class='gd-sec'>先把動詞變成<b>て形</b>（就是「て形」那一課學的形），後面直接加<span class='gd-jp'>ください</span>。<br><b>第一類（五段動詞）</b>：看最後一個字決定怎麼變。<br>・う、つ、る結尾 → って：<span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span> → <span class='gd-jp'>待ってください</span></span><br>・む、ぶ、ぬ結尾 → んで：<span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んでください</span></span><br>・く結尾 → いて：<span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いてください</span></span><br>・ぐ結尾 → いで：<span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急いでください</span></span><br>・す結尾 → して：<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話してください</span></span><br>・例外：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行ってください</span></span>（不是行いて）</div><div class='gd-sec'><b>第二類（一段動詞）</b>：把「る」拿掉，加「て」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べてください</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見てください</span></span></div><div class='gd-sec'><b>第三類（する・来る）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>してください</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来てください</span>（きてください）</span></div><div class='gd-h'>怎麼接：請不要〜</div><div class='gd-sec'>先把動詞變成<b>ない形</b>，後面加<span class='gd-jp'>でください</span>。<br><b>第一類（五段動詞）</b>：最後一個音換成同一行的「あ」段音，加ない。<br><span class='gd-pair'><span class='gd-jp'>撮る</span> → る換成ら → <span class='gd-jp'>撮らない</span> → <span class='gd-jp'>撮らないでください</span></span><br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書かないでください</span></span><br>う結尾的要換成「わ」：<span class='gd-pair'><span class='gd-jp'>吸う</span> → <span class='gd-jp'>吸わないでください</span></span></div><div class='gd-sec'><b>第二類（一段動詞）</b>：把「る」拿掉，加ない。<br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないでください</span></span></div><div class='gd-sec'><b>第三類（する・来る）</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しないでください</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ないでください</span>（こないでください）</span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・「請不要」是ない後面接<b>で</b>：<span class='gd-jp'>見ないでください</span>，不是「見ないてください」，也沒有「見ませんでください」這種說法。<br>・う結尾變ない形是「わ」：<span class='gd-jp'>吸わない</span>、<span class='gd-jp'>買わない</span>，不是「吸あない」。<br>・来る兩種念法不一樣：<span class='gd-jp'>来てください</span>念<b>きて</b>，<span class='gd-jp'>来ないでください</span>念<b>こないで</b>。<br>・雖然中文翻成「請」，它其實是在<b>叫對方做事</b>。對老師、主管拜託事情，說<span class='gd-jp'>〜てくださいませんか</span>（能不能請您〜）會比較客氣。<br>・朋友之間常把ください省略：<span class='gd-jp'>ちょっと待って。</span>（等一下）<span class='gd-jp'>見ないで。</span>（不要看）<br>・店員對客人常說<span class='gd-jp'>少々お待ちください</span>（請稍候），那是更客氣的另一種形，不是本課的て形，聽到認得出來就好。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><span class='gd-jp'>ください</span>前面如果是<b>東西</b>，意思是「請給我」；前面是<b>動詞て形</b>，意思是「請你做」。</div><div class='gd-ex-line'>・<span class='gd-jp'>水をください。</span>（請給我水）</div><div class='gd-ex-line'>・<span class='gd-jp'>水を飲んでください。</span>（請喝水）</div><div class='gd-warn'>判斷小訣竅：「名詞＋をください」是跟人要東西，「て形＋ください」是請人做動作。</div>",
  "n5-57": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文的「我想要」其實有兩種：想要一個<b>東西</b>（我想要新手機），跟想<b>做</b>一件事（我想去日本）。日文把這兩種分開講：要東西用<b>「欲しい」</b>，要做動作用<b>「〜たい」</b>。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><span class='gd-tag'>想要東西</span>名詞＋が欲しいです</div><div class='gd-ex-line'>・<span class='gd-jp'>新しいスマホが欲しいです。</span>（我想要新手機）</div><div class='gd-ex-line'>・<span class='gd-jp'>誕生日に時計が欲しいです。</span>（生日我想要一支手錶）</div><div class='gd-sec'><span class='gd-tag'>想做動作</span>先把動詞變成ます形，把「ます」拿掉，再加「たいです」。<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → ます拿掉 → <span class='gd-jp'>行きたい</span></span><br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みたい</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べたい</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見たい</span></span><br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>したい</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来たい</span>（きたい）</span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行きたいです。</span>（我想去日本）</div><div class='gd-ex-line'>・<span class='gd-jp'>温泉に入りたいです。</span>（我想泡溫泉）</div><div class='gd-h'>助詞要注意</div><div class='gd-sec'><span class='gd-jp'>欲しい</span>前面用<b>が</b>。<br><span class='gd-jp'>〜たい</span>的話，原本用「を」的地方，可以保留「を」，也可以換成「が」，兩個都對：<br><span class='gd-jp'>水を飲みたいです。</span>／<span class='gd-jp'>水が飲みたいです。</span>（我想喝水）<br>其他助詞不能換，原本是什麼就是什麼：<span class='gd-jp'>友達に会いたいです。</span>（我想見朋友），這裡的「に」不能換成が。</div><div class='gd-h'>否定和過去：跟い形容詞一樣變</div><div class='gd-sec'><span class='gd-jp'>欲しい</span>和<span class='gd-jp'>〜たい</span>結尾都是「い」，所以變法跟い形容詞一模一樣：<br><span class='gd-pair'><span class='gd-jp'>欲しいです</span> → <span class='gd-jp'>欲しくないです</span></span>（不想要）<span class='gd-pair'><span class='gd-jp'>欲しかったです</span></span>（當時想要）<br><span class='gd-pair'><span class='gd-jp'>行きたいです</span> → <span class='gd-jp'>行きたくないです</span></span>（不想去）<span class='gd-pair'><span class='gd-jp'>行きたかったです</span></span>（當時想去）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は何もしたくないです。</span>（今天什麼都不想做）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・たい要接在ます形後面，不是接辭書形：寫成「行くたい」是錯的，要寫<span class='gd-jp'>行きたい</span>。<br>・たい已經是形容詞了，後面不能再加ます：要說<span class='gd-jp'>行きたいです</span>，不能說「行きたいます」；否定要說<span class='gd-jp'>行きたくないです</span>，不能說「行きたいません」。<br>・<span class='gd-jp'>来たい</span>念<b>きたい</b>。<br>・這兩個都是講<b>自己</b>的心情。直接說「田中さんは車が欲しいです」，日本人會覺得怪，因為你沒辦法替別人感覺。講別人的時候，可以說<span class='gd-jp'>田中さんは車が欲しいと言っていました。</span>（田中說他想要車）。用問句問對方倒是可以：<span class='gd-jp'>何が欲しいですか。</span>（你想要什麼？）<br>・對老師、上司、客人直接問「〜たいですか」，聽起來像在打探人家想幹嘛，不太禮貌。想請對方喝東西，說<span class='gd-jp'>コーヒーはいかがですか。</span>或<span class='gd-jp'>コーヒーを飲みませんか。</span>比較得體。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是一杯咖啡：<br><span class='gd-jp'>コーヒーが欲しいです。</span>（我想要咖啡：要的是「咖啡」這個東西）<br><span class='gd-jp'>コーヒーが飲みたいです。</span>（我想喝咖啡：想做的是「喝」這個動作）<br>台灣人最常卡在中文的「我想要去日本」。句子裡雖然有個「要」，但真正想做的是「去」這個動作，所以要說<span class='gd-jp'>日本へ行きたいです。</span>，不能用欲しい。</div><div class='gd-warn'>判斷小訣竅：把中文的「想要」拿掉看後面。後面是<b>名詞</b>（手機、咖啡）就用欲しい；後面是<b>動詞</b>（去、吃、看）就用たい。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>跟「に（目的）」合起來用：<span class='gd-jp'>映画を見に行きたいです。</span>（我想去看電影）。以後還會學到講別人想要什麼的說法：<span class='gd-jp'>欲しがっている</span>、<span class='gd-jp'>〜たがっている</span>。</div>",
  "n5-59": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜とき」就是中文的<b>「～的時候」</b>。差別在日文把「時候」放在最後面，前面整段話都是在形容這個「とき」，例如<span class='gd-jp'>暇なとき</span>（有空的時候）、<span class='gd-jp'>子どものとき</span>（小時候）。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>「とき」本身是個名詞，所以前面怎麼接，跟你學過的「形容一個名詞」的接法一模一樣。<br><b>動詞</b>：直接接<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くとき</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないとき</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったとき</span></span><br><b>い形容詞</b>：直接接<br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいとき</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いとき</span></span><br><b>な形容詞</b>：加「な」<br><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇なとき</span></span><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気なとき</span></span><br><b>名詞</b>：加「の」<br><span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どものとき</span></span><span class='gd-pair'><span class='gd-jp'>休み</span> → <span class='gd-jp'>休みのとき</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>暇なとき、何をしますか。</span>（你有空的時候都做什麼？）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものとき、よくこの公園で遊びました。</span>（我小時候常在這個公園玩）</div><div class='gd-ex-line'>・<span class='gd-jp'>わからないとき、先生に聞きます。</span>（不懂的時候就問老師）</div><div class='gd-ex-line'>・<span class='gd-jp'>時間がないとき、コンビニでご飯を買います。</span>（沒時間的時候，我會在超商買飯）</div><div class='gd-h'>最重要的一點：行くとき和行ったとき</div><div class='gd-sec'>動詞放在「とき」前面，要用原本的樣子還是た形，<b>不是看整句是現在還是過去</b>，而是看那個動作在那個時間點<b>完成了沒</b>。<br><span class='gd-tag'>辭書形＋とき</span>動作還沒完成，正要做、或正在途中。<br><span class='gd-tag'>た形＋とき</span>動作已經完成了。</div><div class='gd-ex-line'>・<span class='gd-jp'>出かけるとき、「いってきます」と言います。</span>（出門的時候說「我出門了」）</div><div class='gd-ex-line'>・<span class='gd-jp'>家に帰ったとき、「ただいま」と言います。</span>（回到家的時候說「我回來了」）</div><div class='gd-sec'>再看一組，兩句結尾都是過去式，意思卻差很多：</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に行くとき、辞書を買いました。</span>（要去日本的時候買了字典：出發前或路上買的）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に行ったとき、辞書を買いました。</span>（去了日本的時候買了字典：到日本才買的）</div><div class='gd-sec'>第一句明明是過去的事，前面還是用<span class='gd-jp'>行く</span>，因為買字典的那一刻，人還沒到日本。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞要加の：<span class='gd-jp'>子どものとき</span>，不是子どもとき。<br>・な形容詞要加な，而且不能用だ：<span class='gd-jp'>暇なとき</span>，不是暇とき，也不是暇だとき。過去才可以說<span class='gd-jp'>暇だったとき</span>。<br>・動詞和い形容詞後面<b>不要</b>加の：中文有「的」，很多人會講成「行くのとき」，這是錯的。<br>・「とき」前面不用ます、です：<span class='gd-jp'>行くとき、〜ます</span>就很有禮貌了，不要講成「行きますとき」。禮貌靠句子最後面決定。<br>・講習慣或條件時，常常加は變成「ときは」，像<span class='gd-jp'>寒いときは、温かいお茶を飲みます。</span>（冷的時候我會喝熱茶），聽起來很自然。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>你學過的<span class='gd-jp'>〜まえに</span>、<span class='gd-jp'>〜たあとで</span>也跟時間有關，容易跟「とき」混在一起。<br><b>とき</b>＝就在那個時候、那段過程中：<span class='gd-jp'>家に帰るとき、パンを買いました。</span>（回家的路上買了麵包）<br><b>まえに</b>＝只講「在那之前」，多久以前都可以：<span class='gd-jp'>家に帰るまえに、パンを買いました。</span>（回家之前先買了麵包）<br><b>たとき</b>＝做完的那個時間點：<span class='gd-jp'>家に帰ったとき、母はいませんでした。</span>（我回到家的時候，媽媽不在）<br><b>たあとで</b>＝做完之後，接著做下一件事：<span class='gd-jp'>家に帰ったあとで、宿題をしました。</span>（回家之後寫了功課）</div><div class='gd-warn'>判斷小訣竅：想說「在那個當下」用とき；想說「先後順序」用まえに或あとで。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「とき」前面的動作想說「已經做完的時候」，就用た形，這要先熟悉<span class='gd-jp'>た形</span>的變化。之後到 N4 學到<span class='gd-jp'>〜たら</span>（如果～的話、～之後），會常常拿來跟「とき」比較。</div>",
  "n5-60": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜でしょう」很像中文的「應該～吧」。語調往下，是自己在猜：「明天大概會下雨吧」；語調往上，是找對方確認：「很好吃吧？」同一個說法，<b>靠語調分成兩種意思</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>猜測（語調↓）</span>你沒有百分之百確定，只是自己推測。常常跟<span class='gd-jp'>たぶん</span>（大概）一起用，氣象預報也很愛用。</div><div class='gd-ex-line'>・<span class='gd-jp'>明日はたぶん雨でしょう。</span>（明天大概會下雨吧）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう帰ったでしょう。</span>（田中先生應該已經回去了吧）</div><div class='gd-sec'><span class='gd-tag'>確認（語調↑）</span>你覺得對方應該也這麼想，問一下，等對方點頭。</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしいでしょう？</span>（這個蛋糕很好吃吧？）</div><div class='gd-ex-line'>・<span class='gd-jp'>ほら、言ったでしょう？</span>（你看，我不是說過了嗎？）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'><b>動詞、い形容詞</b>：直接接在後面。否定、過去也一樣直接接。<br><span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るでしょう</span></span><span class='gd-pair'><span class='gd-jp'>降らない</span> → <span class='gd-jp'>降らないでしょう</span></span><span class='gd-pair'><span class='gd-jp'>降った</span> → <span class='gd-jp'>降ったでしょう</span></span><br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いでしょう</span></span><span class='gd-pair'><span class='gd-jp'>寒くない</span> → <span class='gd-jp'>寒くないでしょう</span></span></div><div class='gd-sec'><b>な形容詞、名詞</b>：要先把「だ」拿掉再接。<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → だ拿掉 → <span class='gd-jp'>静かでしょう</span></span><br><span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生でしょう</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨でしょう</span></span><br>過去的「だった」要留著：<span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったでしょう</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・名詞、な形容詞後面不能留「だ」：<span class='gd-jp'>学生でしょう</span>才對，說成「学生だでしょう」是錯的。<br>・前面不要再放です：<span class='gd-jp'>寒いでしょう</span>就好，不能說「寒いですでしょう」。でしょう本身就是です的「推測版」，已經有禮貌了。<br>・不能拿來講<b>自己打算</b>做的事。「私は明日行くでしょう」很怪，自己的打算直接說<span class='gd-jp'>明日行きます</span>。<br>・確認用的「でしょう？」帶有「你應該知道吧」的味道，對老師、上司用會有點不客氣。對長輩想客氣地問，要用<span class='gd-jp'>〜でしょうか</span>（請問～呢？），例如<span class='gd-jp'>駅はどこでしょうか。</span>（請問車站在哪裡呢？）<br>・朋友之間確認，常縮短成<span class='gd-jp'>でしょ？</span>，聽到別嚇到，意思一樣。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>ましょう</b> 跟 <b>でしょう</b> 尾巴都是「しょう」，但意思完全不同：<br>・<span class='gd-jp'>一緒に行きましょう。</span>（我們一起去吧：揪人）<br>・<span class='gd-jp'>田中さんも行くでしょう。</span>（田中先生大概也會去吧：猜測）<br>接法也不一樣：ましょう接在ます形後面（<span class='gd-jp'>行き</span>＋ましょう），でしょう接在辭書形這類普通形後面（<span class='gd-jp'>行く</span>＋でしょう）。</div><div class='gd-sec'><b>でしょう？</b> 跟 <b>ね</b> 都可以翻成「～吧」，差在對方有沒有一起感受到：<br>・兩個人一起走在外面：<span class='gd-jp'>寒いですね。</span>（好冷喔：當下一起感受到，順口附和）<br>・朋友剛從外面進來，你在屋裡問他：<span class='gd-jp'>外、寒いでしょう？</span>（外面很冷吧？：你沒在外面，是猜他會覺得冷，要他承認）</div><div class='gd-warn'>判斷小訣竅：「一起做～吧」是ましょう；「大概～吧」「～對吧？」是でしょう；兩個人當下都感受到、只是附和，用ね。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>想說把握更低的「說不定～」，可以用<span class='gd-jp'>〜かもしれません</span>：<span class='gd-jp'>明日は雨かもしれません。</span>（明天說不定會下雨）</div>",
  "n5-61": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「〜からです」就是中文的<b>「因為～」</b>。當對方用<span class='gd-jp'>どうして</span>（為什麼）問你的時候，你只要把原因說出來，後面加上「からです」回答就好。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>回答為什麼</span>對方先問「為什麼」，你只回答原因，前面發生什麼事不用再講一次。</div><div class='gd-ex-line'>・<span class='gd-jp'>どうして休んだんですか。</span>（你為什麼請假？）</div><div class='gd-ex-line'>・<span class='gd-jp'>熱があったからです。</span>（因為我發燒了）</div><div class='gd-ex-line'>・<span class='gd-jp'>どうして日本語を勉強しているんですか。</span>（你為什麼在學日文？）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本のアニメが好きだからです。</span>（因為我喜歡日本動畫）</div><div class='gd-sec'><span class='gd-tag'>自己補原因</span>先講一件事，再用下一句補充原因。</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はパーティーに行きません。忙しいからです。</span>（我今天不去派對。因為很忙）</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>「から」前面要用<b>沒有ます、沒有です的說法</b>（就是跟朋友講話的那種形），最後的禮貌交給「です」負責。<br><b>動詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くからです</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったからです</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないからです</span></span><br><b>い形容詞</b>：直接接。<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いからです</span></span><br><b>な形容詞、名詞</b>：中間要先加「だ」。<br><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きだからです</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だからです</span></span></div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・な形容詞和名詞忘了加「だ」：<span class='gd-jp'>好きからです</span>、<span class='gd-jp'>雨からです</span>都不對，要說<span class='gd-jp'>好きだからです</span>、<span class='gd-jp'>雨だからです</span>。<br>・反過來，い形容詞<b>不能</b>加「だ」：說<span class='gd-jp'>高いからです</span>，不是高いだからです。<br>・「から」前面不要放ます：<span class='gd-jp'>熱がありましたからです</span>是錯的，要說<span class='gd-jp'>熱があったからです</span>。<br>・中文習慣把「因為」放在最前面，日文的「から」卻是放在原因的<b>後面</b>。不要說成から熱があった。<br>・跟朋友講話，把です拿掉就好：<span class='gd-jp'>熱があったから。</span>（因為發燒啊）</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>你已經學過助詞「から」（原因・理由），它跟「からです」意思一樣，差在<b>句子怎麼排</b>。同一件事：<br><span class='gd-tag'>〜から、〜</span>原因在前、結果在後，一句講完。</div><div class='gd-ex-line'>・<span class='gd-jp'>熱があったから、休みました。</span>（因為發燒，所以請假了）</div><div class='gd-sec'><span class='gd-tag'>〜からです</span>結果先講，原因另外一句補上；或是被問「為什麼」時，只回答原因。</div><div class='gd-ex-line'>・<span class='gd-jp'>休みました。熱があったからです。</span>（我請假了。因為發燒）</div><div class='gd-warn'>判斷小訣竅：原因後面還要接「所以怎樣」，用「〜から、」；原因自己就是整句的結尾，用「〜からです」。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>把結果放在前面，加上「のは」，可以把原因講得更清楚：<span class='gd-jp'>昨日休んだのは、熱があったからです。</span>（我昨天請假，是因為發燒）</div>",
  "n5-63": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>疑問詞就是用來發問的詞，等於中文的「什麼、誰、哪裡、什麼時候、哪個、多少錢、怎麼樣」。用法跟中文很像：<b>想問什麼，就把疑問詞放在那個位置，句尾加か</b>。另外，疑問詞後面加「も」或加「か」，意思會整個變掉，這是這課的重點。</div><div class='gd-h'>先認識最常用的七個</div><div class='gd-ex-line'>・<span class='gd-jp'>これは何ですか。</span>（這是什麼？）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人は誰ですか。</span>（那個人是誰？）</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこですか。</span>（廁所在哪裡？）</div><div class='gd-ex-line'>・<span class='gd-jp'>誕生日はいつですか。</span>（你生日是什麼時候？）</div><div class='gd-ex-line'>・<span class='gd-jp'>どれがいいですか。</span>（哪一個好？）</div><div class='gd-ex-line'>・<span class='gd-jp'>これはいくらですか。</span>（這個多少錢？）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本はどうでしたか。</span>（日本怎麼樣？）</div><div class='gd-sec'>對客人、長輩要客氣一點時：<span class='gd-jp'>誰</span>可以換成<span class='gd-jp'>どなた</span>，<span class='gd-jp'>どう</span>可以換成<span class='gd-jp'>いかが</span>。店員常說<span class='gd-jp'>コーヒーはいかがですか。</span>（要不要來杯咖啡？）</div><div class='gd-h'>「何」念なに還是なん</div><div class='gd-sec'>後面接<span class='gd-jp'>です</span>、<span class='gd-jp'>の</span>，或接「～點、～個人」這種計算單位時，念<b>なん</b>：<span class='gd-jp'>何ですか</span>、<span class='gd-jp'>何の本</span>、<span class='gd-jp'>何時</span>、<span class='gd-jp'>何人</span>、<span class='gd-jp'>何曜日</span>。<br>後面接<span class='gd-jp'>を</span>、<span class='gd-jp'>が</span>、<span class='gd-jp'>も</span>、<span class='gd-jp'>か</span>時，念<b>なに</b>：<span class='gd-jp'>何を食べますか</span>、<span class='gd-jp'>何も</span>、<span class='gd-jp'>何か</span>。</div><div class='gd-h'>加「も」：全部都不</div><div class='gd-sec'><span class='gd-tag'>疑問詞＋も＋否定</span>變成「什麼都不～、誰都不～、哪裡都不～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>何も飲みませんでした。</span>（什麼都沒喝）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰も来ませんでした。</span>（誰都沒來）</div><div class='gd-ex-line'>・<span class='gd-jp'>日曜日はどこへも行きませんでした。</span>（星期天哪裡都沒去）</div><div class='gd-sec'>注意助詞：原本的<span class='gd-jp'>を</span>、<span class='gd-jp'>が</span>會被も取代（<span class='gd-pair'><span class='gd-jp'>何を</span> → <span class='gd-jp'>何も</span></span>）；但<span class='gd-jp'>へ</span>、<span class='gd-jp'>に</span>要留著，放在も前面：<span class='gd-jp'>どこへも</span>、<span class='gd-jp'>どこにも</span>、<span class='gd-jp'>誰にも</span>。</div><div class='gd-h'>加「か」：某個、不確定</div><div class='gd-sec'><span class='gd-tag'>疑問詞＋か</span>變成「某個東西、某個人、某個地方、哪天」，就是有，但說不出是哪個。</div><div class='gd-ex-line'>・<span class='gd-jp'>何か食べたいです。</span>（想吃點什麼）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰かいますか。</span>（有人在嗎？）</div><div class='gd-ex-line'>・<span class='gd-jp'>どこか静かな場所へ行きたいです。</span>（想去某個安靜的地方）</div><div class='gd-ex-line'>・<span class='gd-jp'>いつか日本に住みたいです。</span>（總有一天想住在日本）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・疑問詞當主角時後面用<b>が</b>，不用は：<span class='gd-jp'>誰が来ましたか。</span>，不能說誰は来ましたか。<br>・<span class='gd-jp'>いつも</span>不是「什麼時候都不～」，而是「總是」。後面接肯定、否定都可以：<span class='gd-jp'>いつも朝ご飯を食べます。</span>（我總是有吃早餐）／<span class='gd-jp'>いつも朝ご飯を食べません。</span>（我總是不吃早餐）<br>・<span class='gd-jp'>何も</span>念なにも，不是なんも。<br>・<span class='gd-jp'>どれ</span>是三個以上選一個；只有兩個時用<span class='gd-jp'>どちら</span>。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同樣是問朋友喝了什麼，差一個字意思就不同：<br><b>何を</b>＝問「是什麼」，對方要回答東西：<span class='gd-jp'>何を飲みましたか。</span>（你喝了什麼？）→ <span class='gd-jp'>お茶です。</span><br><b>何か</b>＝問「有沒有」，對方先回答はい・いいえ：<span class='gd-jp'>何か飲みましたか。</span>（你有喝什麼東西嗎？）→ <span class='gd-jp'>はい、お茶を飲みました。</span><br><b>何も</b>＋否定＝「什麼都沒有」：<span class='gd-jp'>いいえ、何も飲みませんでした。</span>（沒有，什麼都沒喝）</div><div class='gd-warn'>判斷小訣竅：想知道「是什麼」用何を；想知道「有沒有」用何か；要說「全部都沒有」用何も＋否定。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「這個、那個、哪個」整組一起記更好用，可以接著看指示詞（こそあど）：<span class='gd-jp'>どの本ですか。</span>（哪一本書？）</div>",
  "n5-64": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文只有「這」和「那」，日文分成四種：<b>こ</b>＝這（靠近我）、<b>そ</b>＝那（靠近你）、<b>あ</b>＝那（離我們兩個都遠）、<b>ど</b>＝哪。先記住「こそあど」這四個開頭，再換不同的尾巴，就能指東西、指地方、指方向。</div><div class='gd-h'>先用一個畫面想</div><div class='gd-sec'>你跟朋友站在路邊。你手上拿著手機，朋友手上拿著一杯咖啡，對面遠遠的地方有一棟大樓。<br>手機在你這邊，用<b>こ</b>。咖啡在朋友那邊，用<b>そ</b>。大樓離你們兩個都遠，用<b>あ</b>。不知道是哪一個，就用<b>ど</b>。</div><div class='gd-h'>四組一起看</div><div class='gd-sec'><span class='gd-tag'>指東西</span><span class='gd-jp'>これ・それ・あれ・どれ</span><br>這幾個字自己就能當主角，後面直接接「は」「が」。</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の傘です。</span>（這是我的傘）</div><div class='gd-ex-line'>・<span class='gd-jp'>それ、何ですか。</span>（你手上那個是什麼？）</div><div class='gd-ex-line'>・<span class='gd-jp'>あれは東京タワーです。</span>（那是東京鐵塔）</div><div class='gd-sec'><span class='gd-tag'>後面接名詞</span><span class='gd-jp'>この・その・あの・どの</span><br>這幾個字不能單獨用，後面一定要接一個名詞。</div><div class='gd-ex-line'>・<span class='gd-jp'>この本、おもしろいですよ。</span>（這本書很好看喔）</div><div class='gd-ex-line'>・<span class='gd-jp'>そのかばん、かわいいですね。</span>（你那個包包好可愛）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人はだれですか。</span>（那個人是誰？）</div><div class='gd-sec'><span class='gd-tag'>指地方</span><span class='gd-jp'>ここ・そこ・あそこ・どこ</span></div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこですか。</span>（廁所在哪裡？）</div><div class='gd-ex-line'>・<span class='gd-jp'>あそこにコンビニがあります。</span>（那邊有便利商店）</div><div class='gd-sec'><span class='gd-tag'>禮貌版</span><span class='gd-jp'>こちら・そちら・あちら・どちら</span><br>可以指方向、指地方，也可以客氣地介紹人。店員和櫃台人員很常用。跟朋友講話時會變成<span class='gd-jp'>こっち・そっち・あっち・どっち</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>受付はあちらです。</span>（櫃台在那邊）</div><div class='gd-ex-line'>・<span class='gd-jp'>こちらは田中さんです。</span>（這位是田中先生）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>この・その・あの・どの</span>不能單獨用。「這是我的」要說<span class='gd-jp'>これは私のです</span>，不能說このは私のです。<br>・地方的「那裡」是<b>あそこ</b>，不是あこ。這個字的長相跟同組的其他字不一樣，要特別背。<br>・中文都說「那個」，日文要分清楚：東西在對方旁邊或手上，用<b>それ</b>；離兩個人都遠，才用<b>あれ</b>。<br>・站的位置不同，用的字也會換。對方指著自己手上的東西問<span class='gd-jp'>これは何ですか</span>，你回答時要說<span class='gd-jp'>それは～です</span>，因為那個東西在他那邊。<br>・對方剛剛提到的事情，也用「そ」開頭的字來指：<span class='gd-jp'>それ、いいですね。</span>（那個不錯耶）<br>・介紹人時要用<span class='gd-jp'>こちら</span>。用<span class='gd-jp'>これ</span>指人，就像把人當成東西，很沒禮貌。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>これ</b>和<b>この</b>：意思都是「這」，差別在後面接什麼。<br><span class='gd-jp'>これは私の本です。</span>（這是我的書）<br><span class='gd-jp'>この本は私のです。</span>（這本書是我的）<br>第一句的<span class='gd-jp'>これ</span>後面接「は」。第二句的<span class='gd-jp'>この</span>後面接「本」。</div><div class='gd-sec'><b>どれ</b>和<b>どちら</b>：都是「哪一個」，差別在有幾個可以選。<br><span class='gd-jp'>この三つの中で、どれがいいですか。</span>（這三個裡面，哪個好？）<br><span class='gd-jp'>コーヒーと紅茶、どちらがいいですか。</span>（咖啡跟紅茶，你要哪一個？）<br>在三個以上的東西裡選「哪個」，用どれ；只有兩個選一個，用どちら。</div><div class='gd-warn'>判斷小訣竅：後面緊接名詞，用この；後面接「は」「が」，用これ。三個以上選一個，用どれ；二選一，用どちら。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>「ど」開頭這一組其實就是問問題用的字，可以接著學「疑問詞」，把<span class='gd-jp'>だれ</span>、<span class='gd-jp'>なに</span>、<span class='gd-jp'>いつ</span>一起學起來。</div>",
  "n5-65": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>中文說「一<b>張</b>紙、一<b>枝</b>筆、一<b>隻</b>貓」，數東西時中間要放「張、枝、隻」。日文也一樣，這種字叫<b>量詞</b>，分法也跟中文很像：薄薄的用<span class='gd-jp'>枚</span>，細細長長的用<span class='gd-jp'>本</span>。要說「大概」，就在數量後面加<span class='gd-jp'>くらい</span>。</div><div class='gd-h'>先記這幾個量詞</div><div class='gd-sec'><span class='gd-tag'>つ</span>一般的東西都能用，不知道該用哪個量詞時最萬用，點餐也很常用。1 到 10 要另外背：<span class='gd-jp'>ひとつ、ふたつ、みっつ、よっつ、いつつ、むっつ、ななつ、やっつ、ここのつ、とお</span>。超過 10 就不用つ了。</div><div class='gd-ex-line'>・<span class='gd-jp'>りんごを3つ買いました。</span>（我買了 3 顆蘋果）</div><div class='gd-sec'><span class='gd-tag'>人</span>數人。1、2 個人念法特別：<span class='gd-jp'>ひとり、ふたり</span>。3 個人以後是<span class='gd-jp'>さんにん</span>，4 個人是<span class='gd-jp'>よにん</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>家族は4人です。</span>（我家有 4 個人）</div><div class='gd-sec'><span class='gd-tag'>本</span>細長的東西：筆、瓶子、雨傘、香蕉。</div><div class='gd-ex-line'>・<span class='gd-jp'>鉛筆を1本貸してください。</span>（請借我一枝鉛筆）</div><div class='gd-sec'><span class='gd-tag'>枚</span>薄薄平平的東西：紙、郵票、襯衫、盤子。</div><div class='gd-ex-line'>・<span class='gd-jp'>切手を5枚ください。</span>（請給我 5 張郵票）</div><div class='gd-sec'><span class='gd-tag'>匹</span>貓、狗、魚這種小動物。</div><div class='gd-ex-line'>・<span class='gd-jp'>うちに猫が2匹います。</span>（我家有 2 隻貓）</div><div class='gd-sec'>另外常見的還有：書用<span class='gd-jp'>冊</span>，車子、電視這類機器用<span class='gd-jp'>台</span>，一杯一杯的飲料用<span class='gd-jp'>杯</span>。</div><div class='gd-h'>怎麼放進句子</div><div class='gd-sec'>最自然的順序是：<b>東西＋を（或が）＋數量＋動詞</b>。數量直接放在動詞前面，後面不用再加助詞。<br>中文說「買三顆蘋果」，日文是<span class='gd-jp'>りんごを3つ買います</span>，東西先講，數量後講。<br>要問「幾個」，就把數字換成<span class='gd-jp'>何</span>：<span class='gd-jp'>何人</span>（なんにん）、<span class='gd-jp'>何本</span>（なんぼん）、<span class='gd-jp'>何枚</span>（なんまい）。用つ數的東西則問<span class='gd-jp'>いくつ</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>兄弟は何人いますか。</span>（你有幾個兄弟姊妹？）</div><div class='gd-h'>時間怎麼說</div><div class='gd-sec'><span class='gd-jp'>時</span>是「幾點」，<span class='gd-jp'>時間</span>是「幾個小時」：<span class='gd-jp'>2時</span>是兩點，<span class='gd-jp'>2時間</span>是兩個小時。<br>分鐘的<span class='gd-jp'>分</span>念法會變，要背：<span class='gd-jp'>いっぷん、にふん、さんぷん、よんぷん、ごふん、ろっぷん、ななふん、はっぷん、きゅうふん、じゅっぷん</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日7時間寝ます。</span>（我每天睡 7 個小時）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで歩いて10分くらいです。</span>（走到車站大約 10 分鐘）</div><div class='gd-ex-line'>・<span class='gd-jp'>1時間くらいかかります。</span>（大概要花 1 個小時）</div><div class='gd-sec'><span class='gd-jp'>くらい</span>和<span class='gd-jp'>ぐらい</span>意思一樣，用哪個都可以。</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<b>「大概」的位置跟中文相反</b>：中文「大概一小時」把「大概」放前面，日文是<span class='gd-jp'>1時間くらい</span>，くらい放<b>後面</b>。<br>・數量後面不要再加を：是<span class='gd-jp'>りんごを3つ買いました</span>，不是「りんごを3つを買いました」。<br>・<span class='gd-jp'>本</span>和<span class='gd-jp'>匹</span>的念法會變：<span class='gd-jp'>1本</span>いっぽん、<span class='gd-jp'>3本</span>さんぼん、<span class='gd-jp'>6本</span>ろっぽん；<span class='gd-jp'>1匹</span>いっぴき、<span class='gd-jp'>3匹</span>さんびき。<br>・1、2 個人是ひとり、ふたり，不是「いちにん」「ににん」。<br>・4 點是<span class='gd-jp'>4時</span>（よじ），9 點是<span class='gd-jp'>9時</span>（くじ），不要念成よんじ、きゅうじ。<br>・數人一定用<span class='gd-jp'>人</span>，不能用つ。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>中文都說「大約、左右」，日文要看接在什麼後面：<br><b>くらい</b>接在<b>多久、多少</b>後面：<span class='gd-jp'>3時間くらい待ちました。</span>（等了大約 3 個小時）<br><b>ごろ</b>接在<b>幾點、哪一天</b>這種時間點後面：<span class='gd-jp'>3時ごろ着きます。</span>（3 點左右到）<br>口語裡也會聽到「3時くらい」，但反過來說「3時間ごろ」就是錯的。</div><div class='gd-warn'>判斷小訣竅：大約「多久、多少」用くらい，大約「幾點」用ごろ。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>數量後面加<span class='gd-jp'>だけ</span>＝只要這麼多：<span class='gd-jp'>1つだけください。</span>（只要一個就好）</div>",
  "n5-66": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>副詞就是放在動詞、形容詞前面，補充<b>「多麼～」「多少」「多常～」</b>的小字。中文的「很好吃」的「很」、「常常去」的「常常」、「不太喝」的「不太」，在日文裡都是副詞。這張卡片的重點分三組：<b>程度</b>、<b>數量</b>、<b>頻率</b>。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>程度：很</span><span class='gd-jp'>とても</span>＝很、非常，放在形容詞前面。</div><div class='gd-ex-line'>・<span class='gd-jp'>とても楽しかったです。</span>（非常開心）</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはとてもおいしいです。</span>（這碗拉麵很好吃）</div><div class='gd-sec'><span class='gd-tag'>數量：很多</span><span class='gd-jp'>たくさん</span>＝很多，講「量」。放在動詞前面，或用「たくさんの＋名詞」。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はたくさん食べました。</span>（昨天吃了很多）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅にたくさんの人がいます。</span>（車站有很多人）</div><div class='gd-sec'><span class='gd-tag'>頻率：多常做</span>從最常到完全不做，排成一條線：<br><b>いつも＞よく＞ときどき＞たまに＞あまり～ない＞全然～ない</b></div><div class='gd-ex-line'>・<span class='gd-jp'>いつも7時に起きます。</span>（我總是 7 點起床）</div><div class='gd-ex-line'>・<span class='gd-jp'>よくこの店に来ます。</span>（我常常來這家店）</div><div class='gd-ex-line'>・<span class='gd-jp'>ときどき料理をします。</span>（我有時候會煮飯）</div><div class='gd-ex-line'>・<span class='gd-jp'>たまに映画を見ます。</span>（我偶爾看電影）</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビはあまり見ません。</span>（我不太看電視）</div><div class='gd-ex-line'>・<span class='gd-jp'>お酒は全然飲みません。</span>（我完全不喝酒）</div><div class='gd-sec'><span class='gd-tag'>よく的另一個意思</span><span class='gd-jp'>よく</span>除了「常常」，也可以是「好好地、充分地」。看後面的動詞就知道是哪個。</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はよく寝ました。</span>（昨天睡得很好）</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、よく分かりません。</span>（不好意思，我不太清楚）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・<span class='gd-jp'>あまり</span>、<span class='gd-jp'>全然</span>後面要接<b>否定</b>：說「<span class='gd-jp'>あまり好きです</span>」是錯的，要說<span class='gd-jp'>あまり好きじゃないです</span>（不太喜歡）。<br>・中文說「不太好吃」，別直接翻成「とても」加否定，要用<span class='gd-jp'>あまりおいしくないです</span>。<br>・中文的「很」跟「很多」只差一個字，日文卻是兩個字：「很好吃」用とても，「很多人」用たくさん。說「とても人がいます」是錯的，要說<span class='gd-jp'>人がたくさんいます</span>。<br>・你可能會聽到日本年輕人說「<span class='gd-jp'>全然大丈夫</span>」（完全沒問題），這是口語說法。課本跟考試請先記「全然＋否定」。<br>・副詞通常放在它要修飾的動詞、形容詞前面：<span class='gd-jp'>よく行きます</span>，不要把よく放到句尾。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>あまり～ない</b>＝不太～，還是有一點：<span class='gd-jp'>お酒はあまり飲みません。</span>（不太喝酒，偶爾會喝一點）<br><b>全然～ない</b>＝完全不～，一點都沒有：<span class='gd-jp'>お酒は全然飲みません。</span>（完全不喝酒）<br>被問<span class='gd-jp'>よく行きますか。</span>（常去嗎？），偶爾去就回<span class='gd-jp'>いいえ、あまり行きません。</span>，從來不去才回<span class='gd-jp'>いいえ、全然行きません。</span></div><div class='gd-warn'>判斷小訣竅：中文想說「不太」用あまり，想說「完全不」用全然，兩個後面都要接否定。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>形容詞也能變成副詞，例如<span class='gd-pair'><span class='gd-jp'>早い</span> → <span class='gd-jp'>早く</span></span>：<span class='gd-jp'>早く起きます。</span>（早起）。可以接著看「形容詞的副詞用法」。</div>",
  "n5-67": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>這張卡片是三種讓日文聽起來更<b>像真人在講話</b>的小詞：<br><b>接續詞</b>＝中文的「然後、而且、但是、所以」，放在第二句開頭，把兩句話接起來。<br><b>感應詞</b>＝「是、不是、那個…、嗯…」這種回應或開口時的聲音。<br><b>擬聲擬態語</b>＝「汪汪、嘩啦嘩啦、笑咪咪」這種模仿聲音或樣子的詞，日文用得比中文多很多。</div><div class='gd-h'>接續詞：把兩句話接起來</div><div class='gd-sec'>用法很簡單：先講完第一句，第二句開頭放接續詞，後面通常加個逗號「、」。</div><div class='gd-sec'><span class='gd-tag'>そして</span>而且、然後。補充同方向的內容。</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いです。そして、おいしいです。</span>（這家店很便宜，而且很好吃）</div><div class='gd-sec'><span class='gd-tag'>それから</span>然後、還有。講接下來做的事，或補充「還有～」。</div><div class='gd-ex-line'>・<span class='gd-jp'>パンを買いました。それから、牛乳も買いました。</span>（我買了麵包，還買了牛奶）</div><div class='gd-sec'><span class='gd-tag'>でも</span>但是。後面講跟前面相反的事。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語は難しいです。でも、おもしろいです。</span>（日文很難，但是很有趣）</div><div class='gd-sec'><span class='gd-tag'>だから</span>所以。前面是原因，後面是結果。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りました。だから、行きませんでした。</span>（下雨了，所以沒去）</div><div class='gd-h'>感應詞：回應和開口</div><div class='gd-sec'><span class='gd-tag'>はい・いいえ</span>是／不是。</div><div class='gd-ex-line'>・<span class='gd-jp'>「学生ですか。」「はい、そうです。」</span>（「你是學生嗎？」「是，沒錯」）</div><div class='gd-sec'><span class='gd-tag'>あのう</span>想叫住人、要開口問事情時，帶點「不好意思打擾」的感覺。</div><div class='gd-ex-line'>・<span class='gd-jp'>あのう、すみません。駅はどこですか。</span>（那個…不好意思，車站在哪裡？）</div><div class='gd-sec'><span class='gd-tag'>ええと</span>一邊想一邊講，像中文的「嗯…」。</div><div class='gd-ex-line'>・<span class='gd-jp'>ええと、三つください。</span>（嗯…請給我三個）</div><div class='gd-h'>擬聲擬態語：模仿聲音和樣子</div><div class='gd-sec'><b>擬聲語</b>是模仿真的聲音，<b>擬態語</b>是用聲音去形容樣子或感覺。通常是兩個音重複一次。</div><div class='gd-ex-line'>・<span class='gd-jp'>雨がザーザー降っています。</span>（雨嘩啦嘩啦地下：擬聲）</div><div class='gd-ex-line'>・<span class='gd-jp'>犬がワンワン鳴いています。</span>（狗汪汪叫：擬聲）</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹がぺこぺこです。</span>（肚子好餓：擬態）</div><div class='gd-sec'>另外像<span class='gd-jp'>ゆっくり</span>（慢慢地）、<span class='gd-jp'>はっきり</span>（清楚地）是形容動作樣子的副詞，不是模仿聲音，但一樣超常用：</div><div class='gd-ex-line'>・<span class='gd-jp'>ゆっくり話してください。</span>（請說慢一點）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・接續詞要放在<b>第二句開頭</b>，不能塞在句子中間：<span class='gd-jp'>高いです。でも、買います。</span>可以，不能說「高いでも買います」。<br>・<span class='gd-jp'>だから</span>一開口就接「言ったでしょう」，像「だから、言ったでしょう」，是「我就說嘛」的不耐煩口氣，對長輩不要用。<br>・一般表示「所以」時，對長輩或在正式場合，可以把<span class='gd-jp'>だから</span>換成比較禮貌的<span class='gd-jp'>ですから</span>。<br>・感應詞<span class='gd-jp'>あのう</span>（也寫成<span class='gd-jp'>あの</span>、<span class='gd-jp'>あのー</span>）跟指示詞<span class='gd-jp'>あの</span>（那個＋名詞）來源相同但用法不同。叫人時說「あの、すみません」或稍微拉長說「あのう…」都可以，拉長會多一點猶豫、不好意思打擾的感覺。<br>・<span class='gd-jp'>はい</span>不只是「是」，被點名時回<span class='gd-jp'>はい</span>是「有、在」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'>同一個情境「很貴，但我要買」，可以有兩種講法：<br><span class='gd-jp'>高いです。でも、買います。</span>（兩句話，用<b>でも</b>開第二句）<br><span class='gd-jp'>高いですが、買います。</span>／<span class='gd-jp'>高いけど、買う。</span>（一句話，<b>が・けど</b>黏在前半句尾巴）<br><br>「下雨所以沒去」也一樣：<br><span class='gd-jp'>雨が降りました。だから、行きませんでした。</span>（兩句，用<b>だから</b>）<br><span class='gd-jp'>雨が降ったから、行きませんでした。</span>（一句，<b>から</b>黏在原因後面）</div><div class='gd-warn'>判斷小訣竅：<b>でも・だから</b>站在新句子的開頭；<b>が・けど・から</b>黏在前一句的尾巴。看前面有沒有句號就知道該用哪個。</div>",
  "n5-68": "<div class='gd-h'>一句話先懂</div><div class='gd-sec'>「AというB」就是中文的<b>「叫做A的B」</b>。像你跟朋友說「台中有一家叫『春水堂』的店」，日文就是用「という」把店名和「店」接起來。對方<b>可能不知道</b>某個名字時，就用它來介紹。</div><div class='gd-h'>怎麼接</div><div class='gd-sec'>名字（名詞A）＋という＋這是什麼東西（名詞B）<br><span class='gd-pair'><span class='gd-jp'>村田</span> ＋ <span class='gd-jp'>人</span> → <span class='gd-jp'>村田という人</span></span>（一個叫村田的人）<br><span class='gd-pair'><span class='gd-jp'>さくら</span> ＋ <span class='gd-jp'>店</span> → <span class='gd-jp'>さくらという店</span></span>（一家叫さくら的店）<br>後面的B通常是「人、店、町、食べ物、ドラマ、本」這種告訴對方「這是哪一種東西」的詞。</div><div class='gd-h'>什麼時候用</div><div class='gd-sec'><span class='gd-tag'>介紹名字</span>講到對方可能沒聽過的人、店、作品、食物。</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の前に「さくら」という喫茶店があります。</span>（車站前有一家叫「さくら」的咖啡店）</div><div class='gd-ex-line'>・<span class='gd-jp'>山田という人から電話がありました。</span>（有一個叫山田的人打電話來）</div><div class='gd-ex-line'>・<span class='gd-jp'>小籠包という食べ物を知っていますか。</span>（你知道一種叫小籠包的食物嗎？）</div><div class='gd-sec'><span class='gd-tag'>問名字</span>不知道東西叫什麼，就用<span class='gd-jp'>何という</span>來問，「何」在這裡念<b>なん</b>。</div><div class='gd-ex-line'>・<span class='gd-jp'>これは何という花ですか。</span>（這種花叫什麼名字？）</div><div class='gd-h'>容易搞錯的地方</div><div class='gd-warn'>・という後面<b>一定要接名詞</b>。不能說「さくらというです」，要講完整：<span class='gd-jp'>さくらという店です</span>。<br>・大家都知道的東西不要加。對日本人說「富士山という山」，聽起來像在說「有一座叫富士山的山，你應該沒聽過吧」，很奇怪。<br>・「いう」實際上常念成<b>ゆう</b>，但寫的時候還是寫「いう」，不要寫成「とゆう」。<br>・這個「いう」習慣寫平假名，不太寫漢字「言う」。</div><div class='gd-h'>跟長得很像的分清楚</div><div class='gd-sec'><b>という</b>＝叫做～的：<span class='gd-jp'>村田という人</span>（一個名字叫村田的人）<br><b>の</b>＝屬於～、～那邊的：<span class='gd-jp'>村田さんの友達</span>（村田先生的朋友）<br>中文都有「的」，所以台灣人很容易把「叫村田的人」寫成「村田の人」。但「村田の人」意思會變成「村田家／村田那邊的人」，不是「叫做村田」。</div><div class='gd-sec'>另外，自我介紹時常聽到的<span class='gd-jp'>林といいます。</span>（我叫林）是把「叫做」放在<b>句子最後</b>，後面不接名詞。<br><span class='gd-jp'>林といいます。</span>（我叫林）<br><span class='gd-jp'>林という人がいます。</span>（有一個叫林的人）<br>講自己的名字時<b>不能加さん</b>：說「林さんといいます」是錯的。</div><div class='gd-warn'>判斷小訣竅：中文是「<b>叫做</b>～的」就用という；只是「誰的、哪裡的」就用の。</div><div class='gd-h'>學會之後可以接著學</div><div class='gd-sec'>問「這個用日文怎麼說」：<span class='gd-jp'>これは日本語で何といいますか。</span>（這個日文叫什麼？）</div>"
});
(window.GRAMMAR_DETAIL_LV = window.GRAMMAR_DETAIL_LV || {}).n5 = true;
